def _t1h(_i):
    """TRAP #1 handler address for slot _i (entry + signed first word)."""
    _e = 0xF003D8 + 4 * _i
    _o = _w(_e)
    return _e + (_o - 0x10000 if _o >= 0x8000 else _o)
