check('$0C8E is acquired once via T0P and released four times via T0V',
      _bsrw(0xF03D40) == 0xF006E8
      and all(_bsrw(a + 4) == 0xF00788
              for a in (0xF0413C, 0xF0432E, 0xF0436C, 0xF0437E)))
check('...all six sites inside the CMR region $F03D38-$F0437E',
      all(0xF03D38 <= a <= 0xF0437E for a in _sem[0x0C8E]))
_t1 = []
for _i in range(len(_rom) - 1):
    if _rom[_i] == 0x4E and _rom[_i + 1] == 0x41:
        _d = None
        for _b in range(2, 26, 2):
            _o = _i - _b
            if _o < 0:
                break
            if _rom[_o] == 0x70:
                _d = _rom[_o + 1]
                break
            if _rom[_o] == 0x30 and _rom[_o + 1] == 0x3C:
                _d = (_rom[_o + 2] << 8) | _rom[_o + 3]
                break
        _t1.append((0xF00000 + _i, _d))
check('there are 71 trap #1 sites', len(_t1) == 71, len(_t1))
check('...65 of them resolve to a directive',
      sum(1 for _, d in _t1 if d is not None) == 65)
check('...across exactly 14 distinct directives',
      len({d for _, d in _t1 if d is not None}) == 14)
check('$10 TERMT is issued at 5 sites -- the model is NOT wholly dormant',
      sum(1 for _, d in _t1 if d == 0x10) == 5)
check('...including $F084D6, the XP channel-abort arm',
      (0xF084D6, 0x10) in _t1)
check('...and neither TERMT nor RSTATE site tests the returned status',
      _rom[0xF084D8 - 0xF00000:0xF084D8 - 0xF00000 + 2] == b'\x30\x01'
      and _rom[0xF08592 - 0xF00000:0xF08592 - 0xF00000 + 4] == b'\x4f\xef\x00\x0c')
_unres = [a for a, d in _t1 if d is None]
check('the six unresolved trap #1 sites are the ISR-exit stubs',
      len(_unres) == 6
      and all(_rom[a - 0xF00000 - 4:a - 0xF00000] == b'\x44\xfc\x00\x0c'
              for a in _unres))
check('...and trap_address - 4 equals each CNCTIRQ ISR-exit field, 6 for 6',
      sorted(a - 4 for a in _unres)
      == sorted([0xF050FC, 0xF05E4C, 0xF060F0, 0xF06B08, 0xF07508, 0xF07F08]))
check('the other six privileged directives are absent',
      not any(d in (0x0E, 0x16, 0x18, 0x1C, 0x33, 0x49) for _, d in _t1))
# The privilege bit is tested and never granted.
_b28 = [(0xF00000 + i, _rom[i + 1] & 0xF8, _rom[i + 3] % 8)
        for i in range(len(_rom) - 5)
        if _rom[i] == 0x08 and (_rom[i + 1] & 0xF8) in (0xE8, 0xA8, 0x28, 0x88)
        and _rom[i + 2] == 0x00 and ((_rom[i + 4] << 8) | _rom[i + 5]) == 0x28]
check('34 bit operations address TCB+$28', len(_b28) == 34, len(_b28))
check('...and every one is btst -- nothing ever grants or revokes the privilege',
      all(op == 0x28 for _, op, _b in _b28))
check('...32 of them on bit 7, the privilege flag',
      sum(1 for _, _o, b in _b28 if b == 7) == 32)
check('...spelled BOTH #$F and #$7, so a #$F-only census loses three sites',
      len({_rom[a - 0xF00000 + 3] for a, _o, b in _b28 if b == 7}) == 2)
_alloc = [0xF00000 + i for i in range(len(_rom) - 5)
          if _rom[i:i + 4] == b'\x4f\xef\xff\xa0']
check('lea -$60(a7),a7 occurs exactly 4 times, one per XP task',
      len(_alloc) == 4, [hex(a) for a in _alloc])
check('...every one immediately followed by `pea (a7)`',
      all(_rom[a - 0xF00000 + 4:a - 0xF00000 + 6] == b'\x48\x57' for a in _alloc))
check('...and lea +$60(a7),a7 occurs ZERO times -- the leak is universal',
      not any(_rom[i:i + 4] == b'\x4f\xef\x00\x60' for i in range(len(_rom) - 3)))
check('the three uniform tasks are $A00 apart at this site',
      _alloc[3] - _alloc[2] == 0xA00 and _alloc[2] - _alloc[1] == 0xA00)
check("...and XP4I's sits -$18 off that grid, reconfirming its template shift",
      _alloc[1] - _alloc[0] == 0xA00 + 0x18)
_rst = 0xF0857A
check("the pushes after `pea (a7)` complete RSTATE's 12-byte block on the stack",
      _rom[0xF08580 - 0xF00000:0xF08580 - 0xF00000 + 6]
      == b'\x2f\x3c\x00\x00\x00\x00'
      and _rom[0xF08586 - 0xF00000:0xF08586 - 0xF00000 + 6]
      == b'\x2f\x3c\x55\x53\x45\x52')
check('...and `lea $c(a7),a7` releases exactly the 12 declared bytes',
      _rom[0xF08592 - 0xF00000:0xF08592 - 0xF00000 + 4] == b'\x4f\xef\x00\x0c')
check('...leaving a7 at the buffer base, so $3c(a7) is inside the $60 block',
      _rom[0xF08596 - 0xF00000:0xF08596 - 0xF00000 + 4] == b'\x26\x6f\x00\x3c'
      and _w(0xF08598) < 0x60)
check("`'USER'` occurs 13 times in the image",
      sum(1 for i in range(len(_rom) - 3) if _rom[i:i + 4] == b'USER') == 13)
check('...and the four RSTATE ones are `move.l #imm,-(a7)` operands',
      all(_rom[a - 0xF00000 - 2:a - 0xF00000] == b'\x2f\x3c'
          for a in (0xF06770, 0xF07188, 0xF07B88, 0xF08588)))
check("RDHC's CNCTIRQ block completes the set: vector $41, $F04930, $F050FC",
      _rom[0xF04600 - 0xF00000:0xF04600 - 0xF00000 + 4] == b'RDHC'
      and _l(0xF04608) == 0x41 and _l(0xF0460C) == 0xF04930
      and _l(0xF04610) == 0xF050FC)
check('...and RDHC BREAKS the exit = entry + $22 rule the five templates share',
      (0xF050FC - 0xF04930) != 0x22)
check("RDHC's name table is 6 entries at stride 8, ending where its GTSEG begins",
      all(_rom[0xF0467E - 0xF00000 + 8 * i:0xF0467E - 0xF00000 + 8 * i + 4] == n
          for i, n in enumerate([b'XP1I', b'XP2I', b'XP3I', b'XP4I',
                                 b'USER', b'USER']))
      and 0xF0467E + 6 * 8 == 0xF046AE
      and _rom[0xF046B0 - 0xF00000:0xF046B0 - 0xF00000 + 4] == b'RDHC')
check("the USER task's CRTCB block declares $3000 at +$18, not $190",
      _rom[0xF04614 - 0xF00000:0xF04614 - 0xF00000 + 4] == b'USER'
      and _l(0xF0462C) == 0x00003000)
check('...with $6464 at +$10 and $08000001 at +$14',
      _l(0xF04624) == 0x00006464 and _l(0xF04628) == 0x08000001)
check('...and the block is 28 bytes, ending where the START block begins',
      0xF04614 + 28 == 0xF04630
      and _rom[0xF04630 - 0xF00000:0xF04630 - 0xF00000 + 4] == b'USER')
check('IO1I is the exception: its ISR exit is entry + $76, not + $22',
      (0xF05E4C - 0xF05DD6) == 0x76)
check('the CNCTIRQ block proper is 16 bytes from +$04, matching its declared size',
      (0xF05F14 - 0xF05F04) == 16)
# PROG comes from the TDTI table, STCK from inside each task.
_prog = [0xF00000 + i for i in range(len(_rom) - 3) if _rom[i:i + 4] == b'PROG']
_stck = [0xF00000 + i for i in range(len(_rom) - 3) if _rom[i:i + 4] == b'STCK']
check('PROG occurs 6 times, one per TDTI record at +$40',
      len(_prog) == 6 and _prog == [0xF0A640 + 96 * i for i in range(6)])
check('...each followed by attribute byte $80',
      all(_rom[a - 0xF00000 + 4] == 0x80 for a in _prog))
check('STCK occurs 6 times, one per task, never in the TDTI table',
      len(_stck) == 6 and not any(0xF0A600 <= a < 0xF0A600 + 6 * 96 for a in _stck))
check('...and five of the six sit at task base + $20',
      sorted(_stck)[1:] == sorted(b + 0x20 for b, *_ in _taskhdr))
# The TDTI records vary in only four fields.
_recs = [_rom[0xF0A600 - 0xF00000 + 96 * i:0xF0A600 - 0xF00000 + 96 * (i + 1)]
         for i in range(6)]
_tdiff = [o for o in range(96) if len({r[o] for r in _recs}) > 1]
check('the six TDTI records differ in exactly 8 byte positions',
      _tdiff == [0x04, 0x05, 0x06, 0x07, 0x1E, 0x1F, 0x21, 0x23], _tdiff)
check('...i.e. the name plus only the LOW halves of three address fields',
      all(r[0x1C:0x1E] == b'\x00\xf0' for r in _recs)
      and all(r[0x20] == 0xF0 and r[0x22] == 0xF0 for r in _recs))
check('...and 72 of the 96 bytes are zero in every record',
      all(sum(1 for o in range(96) if r[o] == 0) == 72 for r in _recs))
check("RDHC's second GTSEG block declares USER/UPGM at $10000 length $D000",
      _rom[0xF046C8 - 0xF00000:0xF046C8 - 0xF00000 + 4] == b'USER'
      and _rom[0xF046D4 - 0xF00000:0xF046D4 - 0xF00000 + 4] == b'UPGM'
      and _l(0xF046D8) == 0x00010000 and _l(0xF046DC) == 0x0000D000)


# --- The chassis can rewrite the SBC's stacked PC (2026-08-01) --------------
# The bit-7 register interface indexes into the panel ISR's own saved frame.
# EVERY constant below is read out of the ROM, not restated: a check that
# compares one literal against another tests this file, not the image.
_pcw_nreg = bin(_w(0xF04932)).count('1')          # movem mask $FFFF -> 16
_pcw_fbase = 4 * _pcw_nreg                        # ...so the frame starts at +64
_pcw_sh = (_w(0xF049A8) >> 9) & 7                 # lsl.w #$2,d0
_pcw_thr = _w(0xF049AC)                           # cmpi.w #$3c
_pcw_sub = (_w(0xF049B0) >> 9) & 7                # subq.w #$2
_pcw_ceil = _w(0xF049CC)                          # cmpi.w #$44
_pcw_half = _w(0xF04A32)                          # the $2 in $2(a7,d0.w)

def _pcw_frame_off(code, bit6):
    d = code << _pcw_sh
    if d > _pcw_thr:
        d -= _pcw_sub
    return d + (0 if bit6 else _pcw_half)

check('$F04930 saves 16 longwords (movem.l d0-d7/a0-a7,-(a7))',
      _rom[0xF04930 - 0xF00000:0xF04930 - 0xF00000 + 2] == b'\x48\xe7'
      and _pcw_nreg == 16, _pcw_nreg)
check('...so the stacked SR sits at +64 and the stacked PC at +66/+68',
      _pcw_fbase == 64)
check('...the dispatcher scales the code by 4 and steps over a word past $3C',
      (_w(0xF049A8) & 0xF1F8) == 0xE148 and _pcw_sh == 2 and _pcw_thr == 0x3C
      and _pcw_sub == 2, (_pcw_sh, hex(_pcw_thr), _pcw_sub))
check('...and bit 6 of $E87 selects (a7,d0.w) vs $2(a7,d0.w) -- BOTH frame writes',
      _rom[0xF049D0 - 0xF00000:0xF049D0 - 0xF00000 + 6] == b'\x3f\xa8\x02\x04\x00\x00'
      and _rom[0xF04A2E - 0xF00000:0xF04A2E - 0xF00000 + 6] == b'\x3f\xa8\x02\x04\x00\x02')
check('code $11 addresses the stacked PC: bit6 set -> high word, clear -> low',
      _pcw_frame_off(0x11, True) == _pcw_fbase + 2
      and _pcw_frame_off(0x11, False) == _pcw_fbase + 4)
check('...code $10 with bit 6 CLEAR addresses the stacked SR',
      _pcw_frame_off(0x10, False) == _pcw_fbase)
check('...and the $44 ceiling is exactly the last offset inside the frame',
      _pcw_frame_off(0x11, False) == _pcw_ceil
      and _pcw_frame_off(0x12, True) > _pcw_ceil, hex(_pcw_ceil))
# The guard at $F04988 rejects code $10 with bit 6 set.  Its only reason to
# exist is that the subq makes that combination ALIAS $0F/bit6-clear -- so the
# guard is proof that the author's frame map is this frame map.
check('$F04988 rejects code $10 when $E87 bit 6 is set',
      _w(0xF04988) == 0x0C40 and _w(0xF0498A) == 0x0010 and _w(0xF0498E) == 0x6000
      and _rom[0xF0497E - 0xF00000:0xF0497E - 0xF00000 + 8]
          == b'\x08\x39\x00\x06\x00\x00\x0e\x87')
check('...and that rejected combination is EXACTLY the one alias the subq creates',
      _pcw_frame_off(0x10, True) == _pcw_frame_off(0x0F, False) == _pcw_fbase - 2)
check('...while the other three code-16/17 arms map to distinct frame fields',
      len({_pcw_frame_off(c, b) for c in (0x10, 0x11) for b in (True, False)}
          - {_pcw_fbase - 2}) == 3)
# Detector flaw #10: a displacement-only matcher sees neither frame write.
_pcw_disp = [a for a in (0xF049D0, 0xF04A2E)
             if (_w(a) & 0xF1F8) == 0x3168]          # move.w Dn,d16(An)
check('CONTROL (detector #10): neither frame write matches the d16(An) form',
      _pcw_disp == [], _pcw_disp)


# --- The read direction returns via RDHC, and the USP write arm is buggy ----
check('the bit-7 read arms all deposit into $0E74 and nothing else',
      all(_w(a) == 0x33F7 or _w(a) == 0x33C9 or _w(a) == 0x33C1
          for a in (0xF04A04, 0xF04A58, 0xF04A64, 0xF04A14)))
check('RDHC echoes $E74 to CHANNEL_SELECT at $F04924',
      _rom[0xF04924 - 0xF00000:0xF04924 - 0xF00000 + 8] == b'\x3b\x79\x00\x00\x0e\x74\x02\x04')
check('...re-arming BIM0 ch0 to $5E immediately BEFORE publishing the result',
      _rom[0xF0491E - 0xF00000:0xF0491E - 0xF00000 + 6] == b'\x3b\x7c\x00\x5e\x02\x30')
check('...and then branching back to RDHCs $13 WAIT',
      _w(0xF0492C) == 0x6000
      and 0xF0492C + 2 + _w(0xF0492E) - 0x10000 == 0xF04736)
_e74echo = [a for a in range(0xF04488, 0xF0A825, 2)
            if _rom[a - 0xF00000:a - 0xF00000 + 6] == b'\x3b\x79\x00\x00\x0e\x74']
check('...and it is the ONLY site echoing $E74 through a base register',
      _e74echo == [0xF04924], [hex(x) for x in _e74echo])

# The USP high-half write preserves the other half; the low-half write does not.
check('the USP HIGH-half write preserves the low half (swap/move.w/swap)',
      _w(0xF049E8) == 0x4842 and _w(0xF049EA) == 0x3401 and _w(0xF049EC) == 0x4842)
check('the USP LOW-half write uses movea.w -- it SIGN-EXTENDS over the high half',
      _rom[0xF04A3E - 0xF00000:0xF04A3E - 0xF00000 + 8] == b'\x4e\x69\x32\x68\x02\x04\x4e\x61')
check('...and its leading `move usp,a1` is DEAD: a1 is overwritten before use',
      _w(0xF04A3E) == 0x4E69 and (_w(0xF04A40) & 0xFFC0) == 0x3240)
check('...whereas the USP READ arms extract their half correctly',
      _w(0xF04A0E) == 0x4E69 and _w(0xF04A12) == 0x4841        # read hi: swap
      and _w(0xF04A62) == 0x4E69 and _w(0xF04A64) == 0x33C9)   # read lo: no swap


# --- The SLC ASCII-hex converter and the two terminator parsers -------------
# $F05150 turns one 16-bit word into one byte, two ASCII hex chars per lane.
_slc_split = _w(0xF05156)          # cmpi.b #$40 -- the '@' split, NOT '9'
_slc_hi = _w(0xF0515C)             # subi.w #$37  (the > $40 arm)
_slc_lo = _w(0xF05162)             # subi.w #$30  (the <= $40 arm)

def _slc_nib(ch):
    return ch - _slc_lo if ch <= _slc_split else ch - _slc_hi

check('$F05150 splits at $40 and subtracts $37 / $30',
      (_slc_split, _slc_hi, _slc_lo) == (0x40, 0x37, 0x30),
      (hex(_slc_split), hex(_slc_hi), hex(_slc_lo)))
check("...so it converts '0'-'9' and 'A'-'F' correctly",
      [_slc_nib(c) for c in b'0189ABF'] == [0, 1, 8, 9, 10, 11, 15])
check("...but LOWERCASE hex silently yields wrong values, with no error path",
      _slc_nib(ord('a')) != 10 and _slc_nib(ord('a')) == 0x2A)
check("...and ':;<=>?' alias 'A'-'F' because they are <= $40",
      [_slc_nib(c) for c in b':;<=>?'] == [10, 11, 12, 13, 14, 15])
check('...combining the high lane shifted by 4 with the low lane',
      _w(0xF05164) == 0xE94B and _w(0xF05166) == 0x0242 and _w(0xF05168) == 0x00FF)

# The two terminator parsers accept different d4 sets -- same field, different
# unit -- and only the SLC one supports a 4-byte (S7) entry address.
_slc_widths = {_w(a): _w(b) for a, b in
               ((0xF05258, 0xF0525E), (0xF05264, 0xF0526A), (0xF05270, 0xF05276))}
_cpl_widths = {_w(a): _w(b) for a, b in
               ((0xF055FE, 0xF05604), (0xF0560A, 0xF05610))}
check('the SLC terminator parser maps d4 3/4/5 -> shift 8/16/24',
      _slc_widths == {3: 0x08, 4: 0x10, 5: 0x18}, _slc_widths)
check('the CPLOAD terminator parser maps d4 2/3 -> shift 0/16',
      _cpl_widths == {2: 0x00, 3: 0x10}, _cpl_widths)
check('...so SLC reaches a 4-byte entry address (S7) and CPLOAD does not',
      max(_slc_widths.values()) == 0x18 and max(_cpl_widths.values()) == 0x10)
check('...and both reject anything else with panel $260',
      _w(0xF0528E) == 0x0260 and _w(0xF05616) == 0x0260)
check('CPLOAD reads its record with move.w (a0)+ -- no handshake',
      _w(0xF055F6) == 0x3418)
# $0E7E is the ENTRY address from the terminator, relocated by the staging base.
check('the terminator parser adds $10000 and stores the result to $0E7E',
      _rom[0xF052D0 - 0xF00000:0xF052D0 - 0xF00000 + 6]
      == b'\xd3\xfc\x00\x01\x00\x00'
      and _rom[0xF052D6 - 0xF00000:0xF052D6 - 0xF00000 + 6]
      == b'\x23\xc9\x00\x00\x0e\x7e')


# --- The seven "real code rendered as data" items, closed 2026-08-01 --------
# A reconnection sweep over every DC.W run in BOTH listings (drop known tables,
# drop $0000-$0007 padding, keep runs that disassemble end to end and land
# exactly on the next established instruction boundary) yields these seven and
# nothing else.  Locking the bytes down so a regenerated listing cannot quietly
# lose one.
_cad = {
    0xF044A2: (b'\x08\x38\x00\x0e\x0c\x34', 'trace hook: btst.b #$e,$c34.w'),
    0xF049A4: (b'\x60\x00\x00\xc8',           'dead bra.w $F04A6E'),
    0xF08F70: (b'\x48\xe7\x80\x1c',           'movem.l d0/a3-a5,-(a7)'),
    0xF098EC: (b'\x48\xe7\x80\xe0',           'movem.l d0/a0-a2,-(a7)'),
    0xF09D6A: (b'\x61\x00\x05\x9a',           'skipped bsr.w $F0A306'),
    0xF0A492: (b'\x23\xca\x00\x00\x0e\x48', 'unreachable $0E48 caching'),
    0xF00A1C: (b'\x4a\xb8\x0c\x78',           'unreachable $F70030 routine'),
}
for _ca, (_cb, _cd) in sorted(_cad.items()):
    check('code-as-data %06X is %s' % (_ca, _cd),
          _rom[_ca - 0xF00000:_ca - 0xF00000 + len(_cb)] == _cb)

# The two movem masks are PREDECREMENT (bit 0 = a7 ... bit 15 = d0).  Decoding
# a 2-byte slice in isolation gives a plausible but WRONG register list, so the
# mask is asserted explicitly.
def _cad_regs(mask):
    _r = []
    for _i in range(16):
        if mask & (1 << _i):
            _r.append('d%d' % (15 - _i) if _i >= 8 else 'a%d' % (7 - _i))
    return set(_r)
check('$F08F70 saves d0 and a3-a5',
      _cad_regs(_w(0xF08F72)) == {'d0', 'a3', 'a4', 'a5'}, _cad_regs(_w(0xF08F72)))
check('$F098EC saves d0 and a0-a2',
      _cad_regs(_w(0xF098EE)) == {'d0', 'a0', 'a1', 'a2'}, _cad_regs(_w(0xF098EE)))
check('...and $F09986 carries the IDENTICAL word, which the tool decodes fine',
      _w(0xF09986) == _w(0xF098EC) and _w(0xF09988) == _w(0xF098EE))

# $F09D6A is stepped over by an unconditional bra.b, and both it and the
# guarded call at $F09D60 target the SAME init-failure reporter.
check('$F09D68 is an unconditional bra.b that skips $F09D6A',
      _w(0xF09D68) == 0x6004)
check('...and $F09D6A and the guarded $F09D60 both call $F0A306',
      _bsrw(0xF09D6A) == 0xF0A306 and _bsrw(0xF09D60) == 0xF0A306,
      (hex(_bsrw(0xF09D6A)), hex(_bsrw(0xF09D60))))
check('...which loads the $A2 init-failure progress code',
      _w(0xF0A32A) == 0x323C and _w(0xF0A32C) == 0x00A2)


# --- The SBC<->AC interface is closed in both directions (2026-08-01) -------
_ACREG = [(0xF04600, 0xF05D00, 'RDHC'), (0xF05D00, 0xF05F00, 'IO1I'),
          (0xF05F00, 0xF06900, 'XP4I'), (0xF06900, 0xF07300, 'XP3I'),
          (0xF07300, 0xF07D00, 'XP2I'), (0xF07D00, 0xF08700, 'XP1I')]

def _acwho(_a):
    for _lo, _hi, _nm in _ACREG:
        if _lo <= _a < _hi:
            return _nm
    return None

_accmd = {}          # immediate -> {task: count}   written as move.w #imm,(a0)
_acdreg = []         # sites writing a DATA REGISTER to (a0)
_acopnd = {}         # move.w Dn,$2(a1)  -> the operation code slot
_acbt = {}           # (form, bit) -> {task: count}
for _aa in range(0xF04488, 0xF0A825, 2):
    _t = _acwho(_aa)
    if not _t:
        continue
    _o = _w(_aa)
    if (_o & 0xF1FF) == 0x30BC and ((_o >> 9) & 7) == 0:            # move.w #imm,(a0)
        _accmd.setdefault(_w(_aa + 2), {}).setdefault(_t, 0)
        _accmd[_w(_aa + 2)][_t] += 1
    if (_o & 0xF1F8) == 0x3080 and ((_o >> 9) & 7) == 0:            # move.w Dn,(a0)
        _acdreg.append((_aa, _t))
    if (_o & 0xF1F8) == 0x3140 and ((_o >> 9) & 7) == 1 \
            and _w(_aa + 2) == 0x0002 and (_o & 7) == 0:            # move.w d0,$2(a1)
        _acopnd.setdefault(_t, 0)
        _acopnd[_t] += 1
    if (_o & 0xFFC0) == 0x0800:                                     # btst #imm,<ea>
        _f = 'reg' if ((_o >> 3) & 7) == 0 else 'mem'
        _b = _w(_aa + 2) & (31 if _f == 'reg' else 7)
        _acbt.setdefault((_f, _b), {}).setdefault(_t, 0)
        _acbt[(_f, _b)][_t] += 1

# NOTE: `a0` is not always the command-register pointer, so this set is five,
# not three -- an earlier draft of this check asserted three and FAILED.  The
# two extras are XP4I's semaphore-block latch values, written through the
# pointer the $2B SGSEM trap leaves in a0, and they are XP4I-only.
check('only five immediates are written through (a0) in the task regions',
      set(_accmd) == {0x8000, 0x8004, 0x8005, 0x1F41, 0x1F45},
      sorted(hex(k) for k in _accmd))
check('...and the two non-command values are XP4I ALONE -- its semaphore latch',
      set(_accmd[0x1F41]) == {'XP4I'} and set(_accmd[0x1F45]) == {'XP4I'},
      (_accmd[0x1F41], _accmd[0x1F45]))
check('...REQUEST-TRANSFER $8004 six times in each of the five transaction copies',
      all(_accmd[0x8004].get(_t) == 6
          for _t in ('RDHC', 'XP1I', 'XP2I', 'XP3I', 'XP4I')), _accmd[0x8004])
check('...CONTINUE-TRANSFER $8005 four times in each',
      all(_accmd[0x8005].get(_t) == 4
          for _t in ('RDHC', 'XP1I', 'XP2I', 'XP3I', 'XP4I')), _accmd[0x8005])
check('...and $8000 ONLY in XP1I/XP2I/XP3I -- never XP4I, never RDHC',
      set(_accmd[0x8000]) == {'XP1I', 'XP2I', 'XP3I'}, _accmd[0x8000])
check('the command register is never given a computed value in a transaction',
      len(_acdreg) == 1 and _acdreg[0][1] == 'IO1I', _acdreg)
check('...while the operation code goes to the DATA-LOW half, once per copy',
      set(_acopnd) == {'RDHC', 'XP1I', 'XP2I', 'XP3I', 'XP4I'}
      and set(_acopnd.values()) == {1}, _acopnd)

_acreg_bits = {_b for (_f, _b) in _acbt if _f == 'reg'}
check('the only bits tested in a register operand are 0,1,7,11,13,14,15,29',
      _acreg_bits == {0, 1, 7, 11, 13, 14, 15, 29}, sorted(_acreg_bits))
check('...so the AC status word has exactly four examined bits (15/14/13/11)',
      not (_acreg_bits & {2, 3, 4, 5, 6, 8, 9, 10, 12}))
check('...bit 13 ERROR is the most-tested bit, ahead of bit 14 DONE',
      sum(_acbt[('reg', 13)].values()) > sum(_acbt[('reg', 14)].values())
      > sum(_acbt[('reg', 15)].values()))
check('bit 29 is tested exactly once, in TCBIO1I -- the mailbox attention bit',
      _acbt[('reg', 29)] == {'IO1I': 1}, _acbt[('reg', 29)])
# XP4I tests bit 11 in a REGISTER where the others test the latched status byte.
check('memory bit 3 (word bit 11 of $1066) is absent from XP4I',
      set(_acbt[('mem', 3)]) == {'XP1I', 'XP2I', 'XP3I'}, _acbt[('mem', 3)])
check('...and XP4I carries one MORE register bit-11 test than the others',
      _acbt[('reg', 11)]['XP4I'] > _acbt[('reg', 11)]['XP1I'], _acbt[('reg', 11)])


# --- Issuer call sites: 122 releasable, 11 terminal (2026-08-01) ------------
# A level-6 request is blocked at IPL 6 as well as IPL 7 (only level 7 is
# non-maskable), so BIM0 ch0 -- the panel responder, CR $5E -- cannot preempt a
# spin entered from inside an interrupt handler.  Measured: RDHC's $25C spin
# runs at SR $2600 and TCBIO1I's $281 spin at SR $2700.
_ISSUERS = (0xF04500, 0xF05688, 0xF05E56, 0xF068A8,
            0xF072C0, 0xF07CC0, 0xF086C0, 0xF0A57E)
check('all eight panel-command issuers end in `bra .` 48 bytes in',
      all(_rom[_i + 48 - 0xF00000:_i + 48 - 0xF00000 + 2] == b'\x60\xfe'
          for _i in _ISSUERS))
_isrsite = []
for _sa in range(0, len(_rom) - 5, 2):
    if _rom[_sa] == 0x4E and _rom[_sa + 1] == 0xB9 \
            and int.from_bytes(_rom[_sa + 2:_sa + 6], 'big') in _ISSUERS:
        _isrsite.append(0xF00000 + _sa)
check('there are 133 jsr sites targeting the eight issuers',
      len(_isrsite) == 133, len(_isrsite))
_panel = [_x for _x in _isrsite if 0xF04930 <= _x < 0xF05160]
_io1i = [_x for _x in _isrsite if 0xF05DD6 <= _x < 0xF05E90]
_xpisr = [_x for _x in _isrsite
          if any(_lo <= _x < _lo + 0x32
                 for _lo in (0xF060CE, 0xF06AE6, 0xF074E6, 0xF07EE6))]
check('...10 of them are inside the panel ISR, where IPL 6 blocks the responder',
      len(_panel) == 10, len(_panel))
check('...exactly ONE is inside TCBIO1I\'s ISR -- the $281 site, at IPL 7',
      len(_io1i) == 1, _io1i)
check('...the four XP channel ISRs contain NO issuer call at all',
      _xpisr == [], _xpisr)
check('...leaving 122 in task context, releasable by a level-6 redirect',
      len(_isrsite) - len(_panel) - len(_io1i) == 122)
# Read the CR values the firmware actually writes rather than restating them:
# the MC68153 control register's bits 0-2 are the level it requests.
_crv = {}
for _ca2 in range(0xF00000, 0xF0A825, 2):
    if (_w(_ca2) & 0xF1FF) == 0x317C and _w(_ca2 + 4) in (0x0230, 0x0244):
        _crv[_w(_ca2 + 4)] = _w(_ca2 + 2)
check('BIM0 ch0 is programmed $5E = level 6, the channels $5F = level 7',
      _crv.get(0x0230) == 0x5E and _crv.get(0x0244) == 0x5F
      and (_crv[0x0230] & 7) == 6 and (_crv[0x0244] & 7) == 7, _crv)


# --- Each issuer copy serves one region; $F0A57E serves none (2026-08-01) ---
_isscall = {_i: [] for _i in _ISSUERS}
for _sb in range(0, len(_rom) - 5, 2):
    if _rom[_sb] == 0x4E and _rom[_sb + 1] == 0xB9:
        _tg = int.from_bytes(_rom[_sb + 2:_sb + 6], 'big')
        if _tg in _isscall:
            _isscall[_tg].append(0xF00000 + _sb)
check('RDHC calls its own issuer 39 times', len(_isscall[0xF05688]) == 39,
      len(_isscall[0xF05688]))
check('...the four XP copies have IDENTICAL caller counts of 22',
      {len(_isscall[_i]) for _i in (0xF068A8, 0xF072C0, 0xF07CC0, 0xF086C0)} == {22},
      {hex(_i): len(_isscall[_i]) for _i in (0xF068A8, 0xF072C0, 0xF07CC0, 0xF086C0)})
check('...TCBIO1I five times', len(_isscall[0xF05E56]) == 5)
check('$F04500 is the KERNEL\'s copy, called exactly once from $F001A4',
      _isscall[0xF04500] == [0xF001A4], [hex(_x) for _x in _isscall[0xF04500]])
check('...reporting $2B2 PCMD_KERNEL_FATAL and then hanging AGAIN itself',
      _w(0xF001A0) == 0x303C and _w(0xF001A2) == 0x02B2
      and _rom[0xF001AA - 0xF00000:0xF001AA - 0xF00000 + 2] == b'\x60\xfe')
check('...having first saved the USP and the BUS-ERROR VECTOR contents',
      _w(0xF00194) == 0x4E69                      # move usp,a1
      and _l(0xF00196) == 0x21C90848              # move.l a1,$848
      and _l(0xF0019A) == 0x21F80008)             # move.l $8.w,$84C
check('$F0A57E is a complete issuer copy that NOTHING calls',
      _isscall[0xF0A57E] == [], _isscall[0xF0A57E])
check('...so seven issuers are live, not eight',
      sum(1 for _i in _ISSUERS if _isscall[_i]) == 7)
check('...and the 133 calls are fully accounted for by those seven',
      sum(len(_v) for _v in _isscall.values()) == 133)


# --- Retracted names must not survive in the EMITTERS (2026-08-01) ----------
# Every naming this project corrected in prose was still live in the code that
# prints it: the bus log called an S-record type error "PCMD_CH3_CONFIG", and
# $26A/$26C -- timeout vs error -- were SWAPPED.  A correction that reaches only
# the documentation leaves the tool asserting the wrong name into a log that
# later analysis reads as evidence.  Third occurrence of this pattern after the
# ROMChecksumTest and TCBDefinitionTable renames.
#
# The check is on QUOTED occurrences only: several of these survive as C macro
# identifiers (they index ch_config[] and drive the APIF decode) and renaming
# those would move behaviour.  It is the emitted string that must be right.
_RETRACTED = [
    'PCMD_CH1_INIT', 'PCMD_CH1_ACK', 'PCMD_CH1_FLUSH', 'PCMD_RESET_STATUS',
    'PCMD_CH1_CONFIG', 'PCMD_CH2_CONFIG', 'PCMD_CH3_CONFIG', 'PCMD_CH4_CONFIG',
    'XLTR_CH1_CONFIG', 'XLTR_CH2_CONFIG', 'XLTR_CH3_CONFIG', 'XLTR_CH4_CONFIG',
    'PCMD_TIMEOUT_ABORT', 'PCMD_RELEASE', 'PCMD_INIT_STEP',
    'APIF_CMD_ARG_LO', 'APIF_CMD_ARG_HI', 'ROMChecksumTest',
]
_EMITTERS = ['emulator/versabus.c', 'build_clean_disasm.py']
_stale = []
for _ef in _EMITTERS:
    try:
        _et = open(os.path.join(os.path.dirname(ROM) or '.', _ef)).read()
    except OSError:
        continue
    for _rn in _RETRACTED:
        for _q in ('"%s"' % _rn, "'%s'" % _rn):
            if _q in _et:
                _stale.append((_ef, _rn))
check('no retracted label survives as an emitted string in the tools',
      _stale == [], _stale)
# ...and a known-positive control: the CORRECTED names must actually be there,
# or the check above would pass trivially on a file that lost its table.
_haveok = 0
try:
    _vb = open(os.path.join(os.path.dirname(ROM) or '.',
                            'emulator/versabus.c')).read()
    _haveok = sum(1 for _n in ('PCMD_ERR_SREC_TYPE', 'PCMD_TIMEOUT',
                               'PCMD_FAIL_START_USER', 'APIF_PANEL_CMD',
                               'BIM1_CR2 (XP1I)') if '"%s"' % _n in _vb)
except OSError:
    pass
check('CONTROL: the corrected labels are present, so the sweep is not vacuous',
      _haveok == 5, _haveok)


# --- CPRUN golden master: the seventh task exists (2026-08-01) --------------
# The first configuration in this project's history that creates USER.  Locks
# the whole prerequisite chain: CPLOAD with a TERMINATOR sets $E7E, op $8
# range-checks it, CHANNEL_SELECT must read 0, and the issuer-return hook is
# required because op $8's ISR handler exits only through a panel issuer.
with tempfile.TemporaryDirectory() as _cprd:
    subprocess.run([EMU, '-rom', ROM, '-cycles', '250000000',
                    '-dump-ram', f'{_cprd}/r'],
                   capture_output=True, timeout=600,
                   env={**os.environ,
                        'FPS3K_ISSUER_RETURN': '1',
                        'FPS3K_RESPSEQ': '0x0B,0x94,0x0B,0x08',
                        'FPS3K_XPIRQ': '6',
                        'FPS3K_CHSEL_RD': '0000',
                        'FPS3K_CHASSIS_CMD':
                            '4,B,53310004,0000DEAD,BEEF0000,53390002,00000000'})
    _cpr = open(f'{_cprd}/r', 'rb').read()

def _cprl(_o):
    return int.from_bytes(_cpr[_o:_o + 4], 'big')

check('CPLOAD with a terminator sets $0E7E to the relocated ENTRY address',
      _cprl(0x0E7E) == 0x00010000, hex(_cprl(0x0E7E)))
check('...and the S1 data lands at the staging base $10010',
      _cprl(0x10010) == 0xDEADBEEF, hex(_cprl(0x10010)))
check('CPRUN pre-fills $10000 with EXACTLY eight $4E71 NOPs',
      _cpr[0x10000:0x10010] == b'\x4e\x71' * 8
      and _cpr[0x10010:0x10012] != b'\x4e\x71', _cpr[0x10000:0x10012].hex())
check('...and a SEVENTH !TCB named USER exists at $1DB00',
      _cpr[0x1DB00:0x1DB04] == b'!TCB' and _cpr[0x1DB10:0x1DB14] == b'USER')
check('...created UNPRIVILEGED: TCB+$28 = $0800, bit 15 clear',
      int.from_bytes(_cpr[0x1DB28:0x1DB2A], 'big') == 0x0800,
      hex(int.from_bytes(_cpr[0x1DB28:0x1DB2A], 'big')))
# The RUNTIME value is not the $A000 the TDTI record requests: the kernel adds
# bit 0 to all six, and bit 7 to the five that own semaphores (RDHC owns none).
_tcb28 = {_n: int.from_bytes(_cpr[_t + 0x28:_t + 0x2A], 'big') for _n, _t in
          (('XP1I', 0x1E900), ('XP2I', 0x1EB00), ('XP3I', 0x1ED00),
           ('XP4I', 0x1EF00), ('IO1I', 0x1F100), ('RDHC', 0x1F300))}
check('...against the six TDTI tasks, all of which are PRIVILEGED (bit 15)',
      all(_v & 0x8000 for _v in _tcb28.values()), _tcb28)
check('...and all carry bit 13 (snapshot on termination) and bit 0',
      all((_v & 0x2001) == 0x2001 for _v in _tcb28.values()), _tcb28)
check('...but the runtime word is $A081/$A001, NOT the $A000 the record asks for',
      set(_tcb28.values()) == {0xA081, 0xA001}, _tcb28)
check('...bit 7 is set in exactly the five tasks that OWN SEMAPHORES, not RDHC',
      {_n for _n, _v in _tcb28.items() if _v & 0x0080}
      == {'XP1I', 'XP2I', 'XP3I', 'XP4I', 'IO1I'},
      {_n: hex(_v) for _n, _v in _tcb28.items()})
check('...with its entry point and saved PC both $00010000',
      _cprl(0x1DB6C) == 0x00010000 and _cprl(0x1DBFC) == 0x00010000)
check('...and USER at the head of the ALL-TASKS list, linking to XP1I',
      _cprl(0x0C10) == 0x0001DB00 and _cprl(0x1DB04) == 0x0001E900)
# The attribute word is a ROM constant, not inherited from RDHC.
check('the $0800 comes from the CRTCB block at $F04628, not from propagation',
      _w(0xF04628) == 0x0800)

# --- The allocatable-region configuration, source to result (2026-08-01) ----
def _cprl2(_o):
    return int.from_bytes(_cpr[_o:_o + 4], 'big')

_srcflags = _w(0xF0A54A)
_srclimit = _l(0xF0A550)
check('the region SOURCE record at $F0A54A has a zero flags word',
      _srcflags == 0, hex(_srcflags))
check('...and its limit is the config RAM top $00020000',
      _srclimit == 0x00020000, hex(_srclimit))
_rlp = _cprl2(0x0C00)
check('$0C00 points at the built region list just below the supervisor stack',
      _rlp == 0x0001FE1A, hex(_rlp))
check('...whose single record is base $01100, limit $1FE00',
      int.from_bytes(_cpr[_rlp:_rlp + 2], 'big') == 0
      and _cprl2(_rlp + 2) == 0x00001100 and _cprl2(_rlp + 6) == 0x0001FE00,
      (hex(_cprl2(_rlp + 2)), hex(_cprl2(_rlp + 6))))
check('...terminated by a NEGATIVE flags word, not the literal $FFFF alone',
      int.from_bytes(_cpr[_rlp + 10:_rlp + 12], 'big') & 0x8000)
check('...the limit is the config RAM top minus $200',
      _srclimit - _cprl2(_rlp + 6) == 0x200)
check('...and the list itself sits at the RAM top minus $1E6',
      _srclimit - _rlp == 0x1E6)
# $F0A57E's ADDRESS is load-bearing: rounded up it is the TDTI table.
# Read the marker address out of the `lea $F0A57E,a3` at $F09D30 rather than
# restating it, so the rounding is applied to a ROM-sourced value.
# $F09D30 is `lea (d16,PC),a3` ($47FA), NOT lea abs.l -- so the marker is
# PC-relative and _bsrw() computes it (opcode address + 2 + signed displacement).
_marker = _bsrw(0xF09D30)
check('$F09D30 loads the end-of-code marker PC-relatively, and it is $F0A57E',
      _w(0xF09D30) == 0x47FA and _marker == 0xF0A57E, hex(_marker))
check('...rounding it up to a page gives the TDTI table, tagged !TCB',
      ((_marker + 0xFF) & ~0xFF) == 0xF0A600
      and _rom[0xF0A600 - 0xF00000:0xF0A600 - 0xF00000 + 4] == b'!TCB')
check('...and that marker address is the DEAD issuer copy, called by nobody',
      _marker in _ISSUERS and _isscall[_marker] == [])

# The 21-word VMOD vector table: predicted from the ROM writer at $F0A4BE,
# checked against post-boot RAM.  Pure static decode on one side, machine state
# on the other -- three blocks of SEVEN words, pre-decrementing, offsets
# $1000/$0FF0/$0FE0, filling $1FFD2-$1FFFF with $1FFE0 and $1FFF0 skipped.
_vmpred = {}
_vma = 0xF0A4BE
for _vb in range(3):
    _voff = _w(_vma)
    _vma += 2
    _vp = 0x1F000 + _voff
    for _vk in range(7):
        _vv = _w(_vma)
        _vma += 2
        _vp -= 2
        _vmpred[_vp] = _vv
_vmbad = [(hex(_k), hex(_v), hex(int.from_bytes(_cpr[_k:_k + 2], 'big')))
          for _k, _v in sorted(_vmpred.items())
          if int.from_bytes(_cpr[_k:_k + 2], 'big') != _v]
check('all 21 predicted VMOD vector words are present in post-boot RAM',
      len(_vmpred) == 21 and _vmbad == [], _vmbad[:4])
check('...and $1FFE0, the word the three blocks skip, is untouched',
      0x1FFE0 not in _vmpred
      and int.from_bytes(_cpr[0x1FFE0:0x1FFE2], 'big') == 0)
check('...while $1FFF0 reads ZERO in RAM because it is a DEVICE register',
      0x1FFF0 not in _vmpred
      and int.from_bytes(_cpr[0x1FFF0:0x1FFF2], 'big') == 0)


# --- Word fields addressed as TWO byte fields (2026-08-01) ------------------
# A `$28(a6)`-only sweep misses every operation on `$29(a6)`, the low byte of
# the same word.  On a 68000 `btst` on memory is byte-sized and mod 8, so any
# field wider than a byte MUST be reached at two displacements -- every
# field-level sweep here has to run against disp AND disp+1.
_BITOPS = {0x08E8: 'bset', 0x08A8: 'bclr', 0x08C8: 'bchg', 0x0868: 'btst'}

def _bitsweep(_disp):
    _out = {}
    for _ba in range(0xF00000, 0xF0A825, 2):
        _o = _w(_ba) & 0xFFF8
        if _o in _BITOPS and _w(_ba + 4) == _disp:
            _out.setdefault(_BITOPS[_o], []).append((_ba, _w(_ba + 2) & 7))
    return _out

_a29 = _bitsweep(0x29)
check('TCB+$29 -- the attribute word LOW byte -- carries 14 bit operations',
      sum(len(_v) for _v in _a29.values()) == 14
      and len(_a29.get('bset', [])) == 11 and len(_a29.get('bclr', [])) == 3,
      {_k: len(_v) for _k, _v in _a29.items()})
check('...so "34 ops on TCB+$28, all btst" describes only the HIGH byte',
      all(_op != 'btst' for _op in _a29))
check('...word bit 0 is set at $F0226E, inside $4C CNCTIRQ (handler $F02216)',
      (0xF0226E, 0) in _a29['bset'])
check('...and word bit 7 at $F031F0, in the CRSEM/ATSEM shared body',
      (0xF031F0, 7) in _a29['bset'])
# The TRAP #1 slot is {self-relative offset word, flags}, so the handler is
# entry + SIGNED offset.  An earlier draft of this check differenced the table
# ENTRY addresses instead and asserted -16 == 16.
def _tr1(_d):
    _e = 0xF003D8 + 4 * _d
    _o = _w(_e)
    return _e + (_o - 0x10000 if _o & 0x8000 else _o)
check('...CRSEM $2D falls through into ATSEM $29: handlers six bytes apart',
      _tr1(0x29) - _tr1(0x2D) == 6, (hex(_tr1(0x2D)), hex(_tr1(0x29))))

# The task state word is 13 bits wide across its two halves, not the 8 documented.
_hi = {_b for _v in _bitsweep(0x2C).values() for _, _b in _v}
_lo = {_b for _v in _bitsweep(0x2D).values() for _, _b in _v}
check('the task state word uses bits 9-15 in its high byte (bit 8 unused)',
      {_b + 8 for _b in _hi} == {9, 10, 11, 12, 13, 14, 15},
      sorted(_b + 8 for _b in _hi))
check('...and bits 2-7 in its low byte (bits 0 and 1 unused)',
      _lo == {2, 3, 4, 5, 6, 7}, sorted(_lo))
check('...13 live bits in total, five of them (3,4,5,7,15) undocumented',
      len({_b + 8 for _b in _hi} | _lo) == 13)

# The hazard is confined to byte-addressed RAM: the XLTR has no memory-form
# bit operations at all, so its bit maps cannot hide a second addressing form.
_xltrbits = sum(len(_v) for _d in range(0x200, 0x261)
                for _v in _bitsweep(_d).values())
check('NO memory-form bit operation exists on any XLTR displacement $200-$260',
      _xltrbits == 0, _xltrbits)
check('CONTROL: the same sweep finds 34 operations at displacement +$001',
      sum(len(_v) for _v in _bitsweep(0x01).values()) == 34,
      sum(len(_v) for _v in _bitsweep(0x01).values()))


# --- XP4I is a NOTIFY-ONLY channel controller (2026-08-01) ------------------
# Located by absolute-address census (alignment-independent); an earlier byte
# diff at a single global shift gave a wrong extent and was retracted, because
# XP4I's template shift is not uniform across its 2560 bytes.
def _recbits(_rec):
    _out = []
    for _ra in range(0xF00000, 0xF0A825, 2):
        if (_w(_ra) & 0xFFC0) == 0x0800 and (_w(_ra) & 0x3F) == 0x39 \
                and _l(_ra + 4) == _rec:
            _out.append(((_w(_ra) >> 6) & 3, (_w(_ra + 2) & 7) + 8))
    return _out

_recs = {_c: _recbits(0x1066 + (_c - 1) * 6) for _c in (1, 2, 3, 4)}
check('channels 1-3 test word bits 15, 14, 11, 11 on their latched status',
      all([_b for _t, _b in _recs[_c]] == [15, 14, 11, 11] for _c in (1, 2, 3)),
      {_c: [_b for _, _b in _recs[_c]] for _c in (1, 2, 3)})
check('...and ALL of them are btst, never a write',
      all(_t == 0 for _c in (1, 2, 3, 4) for _t, _ in _recs[_c]))
check('XP4I tests only bits 15 and 14 -- it has NO bit-11 arm',
      [_b for _, _b in _recs[4]] == [15, 14], [_b for _, _b in _recs[4]])
check('...so XP4I can never reach the $1B/$8000 sub-mode bit 11 selects',
      len(_recs[4]) == 2 and len(_recs[1]) == 4)
# What it does instead: signal one of its two semaphores.
# moveq #$2B,d0 is $702B -- the register field is bits 9-11, and an earlier
# draft wrote $7A2B, which is moveq into d5.
check('XP4I signals $2B SGSEM on BOTH status arms, with different descriptors',
      _w(0xF06070) == 0x702B and _w(0xF06098) == 0x702B,
      (hex(_w(0xF06070)), hex(_w(0xF06098))))
check('...descriptor 2 at $a(a6) on the bit-15-clear arm, descriptor 1 at (a6)',
      _w(0xF06072) == 0x41EE and _w(0xF06074) == 0x000A   # lea $a(a6),a0
      and _w(0xF0609A) == 0x41D6)                          # lea (a6),a0
check('...and it stamps its OWN channel number into $1062 on that arm',
      _rom[0xF06068 - 0xF00000:0xF06068 - 0xF00000 + 8]
      == b'\x33\xfc\x00\x04\x00\x00\x10\x62')
check('...both SGSEM failures report panel $271, as in every XP task',
      _w(0xF0607C) == 0x0271 and _w(0xF060A2) == 0x0271)


# --- The 65-condition self-test invariant (2026-08-01) ---------------------
# Every failure path in the power-on suite sets d7 to the same sentinel and
# retries forever -- there is no failure exit anywhere in it.  So "how many of
# the 65 sites execute" is a far finer tripwire than "does the boot finish":
# 0 means the model satisfied every condition the firmware checks, first pass.
_stfail = [0xF00000 + _a for _a in range(0xF08700 - 0xF00000, 0xF09C00 - 0xF00000, 2)
           if _rom[_a:_a + 6] == b'\x2e\x3c\xf0\xf0\xf0\xf0']
check('the self-test has 65 failure sites, all inside $F08700-$F09C00',
      len(_stfail) == 65, len(_stfail))
check('...and every one of them sets the SAME sentinel, $F0F0F0F0',
      all(_rom[_f - 0xF00000:_f - 0xF00000 + 6] == b'\x2e\x3c\xf0\xf0\xf0\xf0'
          for _f in _stfail))
with tempfile.TemporaryDirectory() as _std:
    subprocess.run([EMU, '-rom', ROM, '-cycles', '250000000',
                    '-trace', f'{_std}/t'], capture_output=True, timeout=600)
    _stpcs = set()
    for _ln in open(f'{_std}/t'):
        if len(_ln) >= 6 and _ln[0] in '0123456789ABCDEF':
            try:
                _stpcs.add(int(_ln[:6], 16))
            except ValueError:
                pass
_sttrip = [hex(_f) for _f in _stfail if _f in _stpcs]
check('a clean boot trips NONE of the 65 self-test failure conditions',
      _sttrip == [], _sttrip[:6])
check('CONTROL: the trace does reach the self-test region at all',
      len([_p for _p in _stpcs if 0xF08700 <= _p < 0xF09C00]) > 1000,
      len([_p for _p in _stpcs if 0xF08700 <= _p < 0xF09C00]))


# --- $FF021A polarity, measured (2026-08-01) -------------------------------
# $F084A4 maps channel -> bit as 1->5, 2->4, 3->3, 4->2.  The POLARITY was
# recorded as "not established"; driving a channel's own interrupt ALONE settles
# it -- the teardown CLEARS the bit, so a set bit means the transaction is live.
# NOTE: FPS3K_CHCMD=C000 SUPPRESSES this path (bit 15+14 makes the task take the
# "transaction complete" arm instead of issuing), which is why an earlier attempt
# concluded the teardown never runs.
def _maskrun(_env):
    _r = subprocess.run([EMU, '-rom', ROM, '-cycles', '250000000'],
                        capture_output=True, timeout=600,
                        env={**os.environ, **_env})
    _m = re.findall(r'mask=([0-9A-F]{4})',
                    _r.stdout.decode('latin1') + _r.stderr.decode('latin1'))
    return int(_m[-1], 16) if _m else None

_mask_clean = _maskrun({})
_mask_ch1 = _maskrun({'FPS3K_XPIRQ': '1', 'FPS3K_ISSUER_RETURN': '1'})
_mask_ch4 = _maskrun({'FPS3K_XPIRQ': '4', 'FPS3K_CHANNELS': '4',
                      'FPS3K_ISSUER_RETURN': '1'})
check('$FF021A rests at $0FFF after boot -- the self-test leaves all ones',
      _mask_clean == 0x0FFF, hex(_mask_clean) if _mask_clean else None)
check('...driving channel 1 alone CLEARS bit 5, exactly as $F084A4 maps it',
      _mask_ch1 == 0x0FFF & ~(1 << 5), hex(_mask_ch1) if _mask_ch1 else None)
check('...driving channel 4 alone CLEARS bit 2',
      _mask_ch4 == 0x0FFF & ~(1 << 2), hex(_mask_ch4) if _mask_ch4 else None)
check('...so the polarity is SET while a transaction is live, CLEARED on teardown',
      _mask_ch1 is not None and _mask_ch4 is not None
      and _mask_ch1 < _mask_clean and _mask_ch4 < _mask_clean)


# --- The semaphore architecture: five producers, one consumer (2026-08-01) --
_SEMREG = [(0xF04600, 0xF05D00, 'RDHC'), (0xF05D00, 0xF05F00, 'IO1I'),
           (0xF05F00, 0xF06900, 'XP4I'), (0xF06900, 0xF07300, 'XP3I'),
           (0xF07300, 0xF07D00, 'XP2I'), (0xF07D00, 0xF08700, 'XP1I')]

def _semwho(_a):
    for _lo, _hi, _n in _SEMREG:
        if _lo <= _a < _hi:
            return _n
    return None

_sem = {}
for _sa in range(0xF04488, 0xF0A825, 2):
    _v = _w(_sa)
    if (_v & 0xFF00) == 0x7000 and ((_v >> 9) & 7) == 0 and (_v & 0xFF) in (0x29, 0x2A, 0x2B, 0x2D):
        _t = _semwho(_sa)
        if _t:
            _sem.setdefault(_t, {}).setdefault(_v & 0xFF, 0)
            _sem[_t][_v & 0xFF] += 1

check('RDHC alone issues ATSEM and WTSEM, and never CRSEM or SGSEM',
      _sem['RDHC'] == {0x29: 1, 0x2A: 1}, _sem['RDHC'])
check('...the four XP tasks each CREATE and SIGNAL twice, and never attach or wait',
      all(_sem[_t] == {0x2B: 2, 0x2D: 2} for _t in ('XP1I', 'XP2I', 'XP3I', 'XP4I')),
      {_t: _sem[_t] for _t in ('XP1I', 'XP2I', 'XP3I', 'XP4I')})
check('...and TCBIO1I once each, matching the 2/2/2/2/1/0 declaration count',
      _sem['IO1I'] == {0x2B: 1, 0x2D: 1}, _sem['IO1I'])

# $F05652 attaches to a NAMED semaphore and then blocks on it -- it is not a
# "poster".  The name arrives in d1; $F053B6 sets it to 'HXP0' + channel.
check('$F05652 is ATTACH-then-WAIT on a 10-byte stack block, not a post',
      _w(0xF0565E) == 0x2F01            # move.l d1,-(a7)
      and _w(0xF05662) == 0x7029        # moveq #$29 ATSEM
      and _w(0xF0566C) == 0x702A        # moveq #$2A WTSEM
      and _w(0xF05670) == 0x4FEF and _w(0xF05672) == 0x000A)   # lea $a(a7),a7
check("...and the name it waits on is 'HXP0' + channel",
      _l(0xF053B8) == 0x48585030)

# The ROM templates carry the semaphore names; IO1I has only the H form.
check('each XP template holds AXPn then HXPn; TCBIO1I holds HIO1 alone',
      all(_rom[_a - 0xF00000:_a - 0xF00000 + 4] == _nm
          for _a, _nm in ((0xF07D2C, b'AXP1'), (0xF0732C, b'AXP2'),
                          (0xF0692C, b'AXP3'), (0xF05F2C, b'AXP4'),
                          (0xF05D2C, b'HIO1')))
      and _rom[0xF07D36 - 0xF00000:0xF07D36 - 0xF00000 + 4] == b'HXP1')
# Both SGSEM sites in every XP task use $a(a6) then (a6) -- HXPn then AXPn.
check('every XP task signals $a(a6) first and (a6) second',
      _w(0xF07E70) == 0x41EE and _w(0xF07E72) == 0x000A
      and _w(0xF07EA6) == 0x41D6
      and _w(0xF06072) == 0x41EE and _w(0xF06074) == 0x000A
      and _w(0xF0609A) == 0x41D6)


# --- The RTOS config block is a longword table from $F0A4EE (2026-08-01) ----
_CFG = {
    0xF0A4EE: 0x00000000, 0xF0A4F2: 0x00F08700, 0xF0A4F6: 0x00F00100,
    0xF0A4FA: 0x00F04600, 0xF0A4FE: 0x00000C00, 0xF0A502: 0x00000000,
    0xF0A506: 0x00000000, 0xF0A512: 0x00F00100, 0xF0A516: 0x00000001,
    0xF0A51A: 0x00000002, 0xF0A51E: 0x00000001, 0xF0A522: 0x00000001,
    0xF0A526: 0x00000001, 0xF0A52C: 0x00F70000, 0xF0A542: 0x00F000BC,
    0xF0A546: 0x00000000, 0xF0A550: 0x00020000,
}
_cfgbad = [(hex(_k), hex(_v), hex(_l(_k))) for _k, _v in sorted(_CFG.items())
           if _l(_k) != _v]
check('every RTOS config longword holds its documented value',
      _cfgbad == [], _cfgbad[:4])
check('...the two WORD fields are the trace mask $0000 and the tick period 10 ms',
      _w(0xF0A52A) == 0x0000 and _w(0xF0A530) == 0x000A,
      (hex(_w(0xF0A52A)), hex(_w(0xF0A530))))
check('...and the quantum word is 2, giving a 20 ms slice at a 10 ms tick',
      _w(0xF0A532) == 0x0002)
check('...the allocator page counts are 1,2,1,1,1 with the 2 being !UST',
      [_l(_a) for _a in (0xF0A516, 0xF0A51A, 0xF0A51E, 0xF0A522, 0xF0A526)]
      == [1, 2, 1, 1, 1])
# Word-sized fields are read with move.l and land in the HIGH half.
check('$F09E4E copies the QUANTUM longword into $0C54 with move.l',
      _w(0xF09E4E) == 0x21FA and _w(0xF09E52) == 0x0C54)
check('...so $0C54 receives $00020000 and its WORD reads 2',
      (_l(0xF0A532) >> 16) == 2)
check('the config-to-globals copy writes nine fields at $F09E1E-$F09E4E',
      _w(0xF09E36) == 0x21FA and _w(0xF09E3A) == 0x0C10
      and _w(0xF09E3C) == 0x21FA and _w(0xF09E40) == 0x0C14)


# --- The exception ladders and their frame arithmetic (2026-08-01) ----------
def _exlad(_lo, _hi):
    _out = []
    for _la in range(_lo, _hi, 2):
        _o = _w(_la)
        if (_o & 0xFF00) == 0x6100 and (_o & 0xFF):
            _d = _o & 0xFF
            _out.append((_la, _la + 2 + (_d - 0x100 if _d & 0x80 else _d)))
    return _out

_lad1 = _exlad(0xF00A74, 0xF00A94)
check('ladder 1 is 16 adjacent bsr.b, every one to $F00A96',
      len(_lad1) == 16 and {_t for _, _t in _lad1} == {0xF00A96}, len(_lad1))
check('...terminated by a nop at $F00A94', _w(0xF00A94) == 0x4E71)
_lad2 = _exlad(0xF00AD8, 0xF00AEA)
check('ladder 2 is 9 entries whose FIRST TWO have their own handlers',
      len(_lad2) == 9 and _lad2[0][1] == 0xF00B2A and _lad2[1][1] == 0xF00B34,
      [(hex(_a), hex(_t)) for _a, _t in _lad2[:3]])
check('...while the remaining seven all share $F00B10',
      {_t for _, _t in _lad2[2:]} == {0xF00B10})
# The static vector table points INTO the ladder, one entry per vector.
_vecs = {}
for _vi in range(23):
    _e = 0xF0011E + 4 * _vi
    _vecs[_rom[_e - 0xF00000]] = int.from_bytes(b'\x00' + _rom[_e - 0xF00000 + 1:_e - 0xF00000 + 4], 'big')
check('vectors $02/$04/$05/$09/$0A each point at their OWN ladder entry',
      _vecs.get(0x02) == 0xF00AD8 and _vecs.get(0x04) == 0xF00ADC
      and _vecs.get(0x05) == 0xF00ADE and _vecs.get(0x09) == 0xF00AEE
      and _vecs.get(0x0A) == 0xF00AE6,
      {hex(_k): hex(_v) for _k, _v in _vecs.items() if _k in (2, 4, 5, 9, 10)})
# Frame format is encoded in the handler's constant, not tested at run time.
check('the shared handler reads the stacked SR at $4(a7) -- a 3-word frame',
      _w(0xF00B1C) == 0x082F and _w(0xF00B1E) == 0x000D and _w(0xF00B20) == 0x0004)
check('...and the group-0 handlers at $C(a7) -- a 7-word frame',
      _w(0xF00B2A) == 0x082F and _w(0xF00B2E) == 0x000C
      and _w(0xF00B40) == 0x082F and _w(0xF00B44) == 0x000C)
check('...the 8-byte difference being exactly 14 - 6, the two frame sizes',
      _w(0xF00B2E) - _w(0xF00B20) == 8)


# --- The ladder descriptors are {base, attr bit, TCB offset, bias} ----------
def _desc(_a):
    return (_l(_a), _w(_a + 4), _w(_a + 6), _w(_a + 8))

check('the TRAP ladder descriptor at $F00ACE is {$F00A76, 3, $4C, 2}',
      _desc(0xF00ACE) == (0xF00A76, 3, 0x4C, 2), _desc(0xF00ACE))
check('the CPU-exception descriptor at $F00B6A is {$F00ABA, 4, $48, $10}',
      _desc(0xF00B6A) == (0xF00ABA, 4, 0x48, 0x10), _desc(0xF00B6A))
check('...so the attribute bits are 3 and 4 and the tables TCB+$4C and TCB+$48',
      {_desc(0xF00ACE)[1], _desc(0xF00B6A)[1]} == {3, 4}
      and {_desc(0xF00ACE)[2], _desc(0xF00B6A)[2]} == {0x4C, 0x48})
check('the dispatcher computes (return - base) >> 1 and bounds it at 24',
      _w(0xF00B74) == 0x2E1F and _w(0xF00B76) == 0x9E95
      and _w(0xF00B78) == 0xE28F
      and _w(0xF00B7A) == 0x0C07 and _w(0xF00B7C) == 0x0018)
check('...reads the attribute bit LONG from a data register, so it is mod 32',
      _w(0xF00B8A) == 0x0302)          # btst.l d1,d2
check('...and indexes the per-task table through the descriptor offset',
      _w(0xF00B8E) == 0x322D and _w(0xF00B90) == 0x0006
      and _w(0xF00B92) == 0x2C36)
# TRAP #2's vector lands on ladder entry 2 relative to the descriptor base.
check('vector $22 (TRAP #2) resolves to index 2 against the descriptor base',
      (0xF00A7A - _desc(0xF00ACE)[0]) // 2 == 2)


# --- The two TCB words, fully attributed (2026-08-01) ----------------------
# 17 of 77 TRAP #1 slots point at one error stub, which is why 60 are "live".
_deadslots = []
for _dn in range(77):
    _de = 0xF003D8 + 4 * _dn
    _do = _w(_de)
    if _de + (_do - 0x10000 if _do & 0x8000 else _do) == 0xF003D0:
        _deadslots.append(_dn)
check('17 TRAP #1 slots point at the shared error stub $F003D0',
      len(_deadslots) == 17, len(_deadslots))
check('...leaving exactly 60 live slots, the recorded count',
      77 - len(_deadslots) == 60)
# move.w #imm,d16(a6) is $3D7C -- the destination register field is bits 9-11.
check('...and the stub returns status +1 rather than faulting',
      _w(0xF003D0) == 0x3D7C and _w(0xF003D2) == 0x0001
      and _w(0xF003D4) == 0x0102 and _w(0xF003D6) == 0x4E73)

# $1A and $1B install the two per-task exception tables from the caller's a0.
check('$1A installs a CPU-exception table at TCB+$48 and sets attribute bit 4',
      _l(0xF0312E) == 0x2D6E0120 and _w(0xF03132) == 0x0048
      and _w(0xF03134) == 0x08EE and _w(0xF03136) == 0x0004
      and _w(0xF03138) == 0x0029)
check('$1B installs a TRAP table at TCB+$4C and sets attribute bit 3',
      _l(0xF0313C) == 0x2D6E0120 and _w(0xF03140) == 0x004C
      and _w(0xF03142) == 0x08EE and _w(0xF03144) == 0x0003
      and _w(0xF03146) == 0x0029)
check('...both take their argument in the caller SAVED a0 at TCB+$120',
      _w(0xF03130) == 0x0120 and _w(0xF0313E) == 0x0120)

# The state word: bit 3 cleared by WAIT, bit 4 by the scheduler on dispatch.
check('$13 WAIT sets state bit 14 and CLEARS state bit 3',
      _w(0xF02C3E) == 0x08EE and _w(0xF02C40) == 0x000E and _w(0xF02C42) == 0x002C
      and _w(0xF02C44) == 0x08AE and _w(0xF02C46) == 0x0003 and _w(0xF02C48) == 0x002D)
check('the scheduler clears state bit 4 on first dispatch',
      _w(0xF0053C) == 0x08AE and _w(0xF0053E) == 0x0004 and _w(0xF00540) == 0x002D)
check('$11 SUSPND sets state bit 9; $12 RESUME clears it on the TARGET',
      _w(0xF02CAC) == 0x08EE and _w(0xF02CAE) == 0x0009
      and _w(0xF02CB4) == 0x08A8 and _w(0xF02CB6) == 0x0009)


# --- The ready-list insert and its priority order (2026-08-01) -------------
check('$F007C0 sets state bit 4 and uses the SAME bset as a double-queue guard',
      _w(0xF007C2) == 0x08E8 and _w(0xF007C4) == 0x0004 and _w(0xF007C6) == 0x002D
      and (_w(0xF007C8) & 0xFF00) == 0x6600)
check('...walks the ready list through TCB+$0C',
      _w(0xF007DC) == 0x226A and _w(0xF007DE) == 0x000C)
check('...comparing the CURRENT priority at TCB+$26, continuing while <=',
      _w(0xF007E8) == 0xB029 and _w(0xF007EA) == 0x0026
      and (_w(0xF007EC) & 0xFF00) == 0x6300)          # bls
check('...and links the new node in through TCB+$0C at both ends',
      _w(0xF007EE) == 0x2149 and _w(0xF007F0) == 0x000C
      and _w(0xF007F2) == 0x2548 and _w(0xF007F4) == 0x000C)
check('$F007FC restores the BASE priority TCB+$24 into the CURRENT one TCB+$26',
      _w(0xF007FC) == 0x1168 and _w(0xF007FE) == 0x0024 and _w(0xF00800) == 0x0026)
# Higher number = higher priority, so USER is created BELOW every firmware task.
# Higher TCB+$26 = higher priority, so these two constants say the CP program
# yields to every firmware task.
check('the CRTCB block gives USER priority $64/$64',
      _w(0xF04626) == 0x6464)
check("...while every TDTI record's +$16 priority byte is $96",
      all(_rom[0xF0A600 - 0xF00000 + 96 * _i + 0x16] == 0x96 for _i in range(6)),
      [hex(_rom[0xF0A600 - 0xF00000 + 96 * _i + 0x16]) for _i in range(6)])
check('...so USER (100) is created BELOW the firmware tasks (150)',
      (_w(0xF04626) >> 8) < _rom[0xF0A600 - 0xF00000 + 0x16])


# --- Blocking and waking are exact complements (2026-08-01) ----------------
check('T0P decrements the count, stores it, and blocks only if negative',
      _w(0xF006F8) == 0x5340 and _w(0xF006FA) == 0x3080
      and (_w(0xF006FC) & 0xFF00) == 0x6B00)          # bmi
check('...then enqueues on the waiter list and RE-INSERTS into the ready list',
      (_w(0xF00702) & 0xFF00) == 0x6100
      and _bsrw(0xF00710) == 0xF007C0)
check('T0V clears the LOCK BIT IN THE VALUE, so one store releases and updates',
      _w(0xF007AC) == 0x0880 and _w(0xF007AE) == 0x000F
      and _w(0xF007B0) == 0x3080)                     # move.w d0,(a0)
check('...and wakes by clearing state bit 13 only -- no ready-list touch',
      _w(0xF007B6) == 0x08A9 and _w(0xF007B8) == 0x000D and _w(0xF007BA) == 0x002C)
check('$13 WAIT clears AND TESTS state bit 3 -- the event-pending flag',
      _w(0xF02C44) == 0x08AE and _w(0xF02C46) == 0x0003 and _w(0xF02C48) == 0x002D
      and (_w(0xF02C4A) & 0xFF00) == 0x6600)          # bne -> already signalled
check('T0WAKEUP sets the reschedule-pending flag $0C5B bit 7',
      _w(0xF02C6E) == 0x08F8 and _w(0xF02C70) == 0x0007 and _w(0xF02C72) == 0x0C5B)
check('...and RE-INSERTS the woken task, completing the block/wake symmetry',
      _bsrw(0xF02C9E) == 0xF007FC)
check('...delivering a status into the woken task\'s saved d0 at TCB+$100',
      _w(0xF02C94) == 0x317C and _w(0xF02C96) == 0x0813 and _w(0xF02C98) == 0x0100)



# --- the delay facility: TCB+$58, the !DLY tag, and status +5 ---------------
check('the delay path pops a block from a free list at $4(a1)',
      _w(0xF02D82) == 0x2029 and _w(0xF02D84) == 0x0004 and      # move.l $4(a1),d0
      _w(0xF02D86) == 0x6724 and                                  # beq -> $F02DAC
      _w(0xF02D8A) == 0x2352 and _w(0xF02D8C) == 0x0004)          # move.l (a2),$4(a1)
check('...sets the block\'s +$4 back-pointer to the owning TCB',
      _w(0xF02D90) == 0x254E and _w(0xF02D92) == 0x0004)          # move.l a6,$4(a2)
check('...tags it !DLY at offset +$16, not at the block head',
      _w(0xF02D98) == 0x257C and _l(0xF02D9A) == 0x21444C59 and
      _w(0xF02D9E) == 0x0016)
check('...and links it into TCB+$58, the delay-block pointer',
      _w(0xF02DA0) == 0x2D4A and _w(0xF02DA2) == 0x0058)          # move.l a2,$58(a6)
check('...while an empty free list returns status +5',
      _w(0xF02DAE) == 0x3D7C and _w(0xF02DB0) == 0x0005 and
      _w(0xF02DB2) == 0x0102)

# --- the marker census method, validated ------------------------------------
_TAGS = {0x21544342:'!TCB', 0x21434342:'!CCB', 0x21415351:'!ASQ',
         0x21545354:'!TST', 0x21444C59:'!DLY', 0x21475354:'!GST',
         0x21494456:'!IDV', 0x21494F56:'!IOV', 0x21504154:'!PAT',
         0x21554452:'!UDR', 0x21555354:'!UST', 0x21564354:'!VCT'}
_mw = {}                       # tag -> list of (site, offset)
for _a in range(0xF00000, 0xF0A825, 2):
    _o = _w(_a)
    if (_o & 0xF1FF) == 0x20BC and _l(_a + 2) in _TAGS:          # move.l #imm,(An)
        _mw.setdefault(_TAGS[_l(_a + 2)], []).append((_a, 0))
    elif (_o & 0xF1FF) == 0x217C and _l(_a + 2) in _TAGS:        # move.l #imm,d16(An)
        _mw.setdefault(_TAGS[_l(_a + 2)], []).append((_a, _w(_a + 6)))
check('exactly 11 of the 12 markers have an immediate write site',
      len(_mw) == 11)
check('...!VCT is the one with none -- it is a ROM tag, never written',
      '!VCT' not in _mw)
check('...and each of the 11 is written at exactly one site',
      all(len(v) == 1 for v in _mw.values()))
check('...10 of the 11 sit at offset +$0, so a head-scan finds them',
      sum(1 for v in _mw.values() if v[0][1] == 0) == 10)
check('...!DLY alone sits at +$16, and it is the one with no instance',
      _mw['!DLY'][0][1] == 0x16 and _mw['!DLY'][0][0] == 0xF02D98)


# --- !PAT is the delay facility; !DLY is a type tag inside its slots --------
check('the delay path\'s base register is the !PAT slot $0C2C',
      _w(0xF02CE6) == 0x2278 and _w(0xF02CE8) == 0x0C2C)
check('...so $4(a1) is the free list and $8(a1) the active list',
      _w(0xF02CEA) == 0x45E9 and _w(0xF02CEC) == 0x0008)     # lea $8(a1),a2
check('$F0110C is a SORTED insert keyed on the block\'s +$8',
      _w(0xF0110C) == 0x49E9 and _w(0xF0110E) == 0x0008 and   # lea $8(a1),a4
      _w(0xF01118) == 0xB4AC and _w(0xF0111A) == 0x0008 and   # cmp.l $8(a4),d2
      _w(0xF0111C) == 0x6CF2 and                              # bge -> loop
      _w(0xF0111E) == 0x2542 and _w(0xF01120) == 0x0008)      # move.l d2,$8(a2)
check('...and it terminates by linking the new block in and returning',
      _w(0xF01122) == 0x2480 and _w(0xF01124) == 0x208A and _w(0xF01126) == 0x4E75)
check('the reclaim walk matches blocks by owning TCB at +$4',
      _w(0xF02CFC) == 0xBDEA and _w(0xF02CFE) == 0x0004)      # cmpa.l $4(a2),a6
check('...then SKIPS any block whose +$16 type field is non-zero',
      _w(0xF02D02) == 0x4AAA and _w(0xF02D04) == 0x0016 and   # tst.l $16(a2)
      _w(0xF02D06) == 0x66E6)                                 # bne -> keep walking
check('...so only UNTAGGED blocks are unlinked and released',
      _w(0xF02D08) == 0x2692)                                 # move.l (a2),(a3)
check('!DLY is written into that same +$16 field, making it a TYPE TAG',
      _w(0xF02D9E) == 0x0016 and _l(0xF02D9A) == 0x21444C59)
check('...and the timed wait sets TCB+$2C bit 14 before allocating',
      _w(0xF02D64) == 0x08EE and _w(0xF02D66) == 0x000E and _w(0xF02D68) == 0x002C)


# --- directives $15/$1E are SLEEP; $11/$12 are SUSPND/RESUME ---------------
_T1dly = 0xF003D8
def _t1h_dly(d):                  # TRAP #1 handler address for directive d
    _e = _T1dly + d * 4
    _o = _w(_e)
    return _e + (_o - 0x10000 if _o & 0x8000 else _o)
check('directives $1E and $15 share one handler, entered 4 bytes apart',
      _t1h_dly(0x1E) == 0xF02CCA and _t1h_dly(0x15) == 0xF02CCE)
check('...$1E seeds d7=1 and falls through to $15\'s clr.l d7',
      _w(0xF02CCA) == 0x7E01 and _w(0xF02CCC) == 0x6002 and _w(0xF02CCE) == 0x4287)
check('...both declare a ZERO-size parameter block, so a0 is the argument',
      (_w(_T1dly + 0x1E * 4 + 2) >> 8) == 0 and (_w(_T1dly + 0x15 * 4 + 2) >> 8) == 0)
check('...and the argument is taken straight out of a0',
      _w(0xF02CD0) == 0x2408)                                  # move.l a0,d2
check('the delay is clamped to 86,400,000 ms -- exactly one day',
      _w(0xF02CD2) == 0x0C82 and _l(0xF02CD4) == 0x05265C00 and
      _w(0xF02CDA) == 0x243C and _l(0xF02CDC) == 0x05265C00)
check('...the SAME constant the tick ISR wraps the time-of-day on',
      _l(0xF02CD4) == 86400000)
check('...then the millisecond clock is read and added to give an ABSOLUTE expiry',
      _w(0xF02CE0) == 0x6100 and
      0xF02CE2 + (_w(0xF02CE2) - 0x10000 if _w(0xF02CE2) & 0x8000 else _w(0xF02CE2)) == 0xF00F96
      and _w(0xF02CE4) == 0xD481)                              # add.l d1,d2
check('$11 SUSPND is bset bit 9 of the task state word, and nothing else',
      _t1h_dly(0x11) == 0xF02CAC and _w(0xF02CAC) == 0x08EE and
      _w(0xF02CAE) == 0x0009 and _w(0xF02CB0) == 0x002C and _w(0xF02CB2) == 0x4E73)
check('$12 RESUME is the matching bclr on the same bit',
      _t1h_dly(0x12) == 0xF02CB4 and _w(0xF02CB4) == 0x08A8 and
      _w(0xF02CB6) == 0x0009 and _w(0xF02CB8) == 0x002C)
check('...and returns status +10 when the target was not suspended',
      _w(0xF02CBA) == 0x6608 and _w(0xF02CBC) == 0x066E and
      _w(0xF02CBE) == 0x000A and _w(0xF02CC0) == 0x0102)


# --- the per-directive $102 status profile ---------------------------------
_sp_hs = []
for _i in range(35):
    _v = _l(0xF001D6 + _i * 4)
    if 0xF00000 <= _v <= 0xF0FFFF:
        _sp_hs.append((0, _i, _v - 2))
for _i in range(77):
    _o = _w(0xF003D8 + _i * 4)
    if _o:
        _e = 0xF003D8 + _i * 4
        _sp_hs.append((1, _i, _e + (_o - 0x10000 if _o & 0x8000 else _o)))
_sp_hs.sort(key=lambda t: t[2])
_sp_hs.append((9, 0, 0xF04488))
_sp_sites = []
for _a in range(0xF00000, 0xF04488, 2):
    _o = _w(_a)
    if _o in (0x066E, 0x3D7C) and _w(_a + 4) == 0x0102:
        _sp_sites.append((_a, _w(_a + 2)))
    elif (_o & 0xF1FF) == 0x506E and _w(_a + 2) == 0x0102:
        _n = (_o >> 9) & 7
        _sp_sites.append((_a, _n if _n else 8))
_sp = {}
for _a, _c in _sp_sites:
    for _i in range(len(_sp_hs) - 1):
        if _sp_hs[_i][2] <= _a < _sp_hs[_i + 1][2]:
            _sp.setdefault((_sp_hs[_i][0], _sp_hs[_i][1]), set()).add(_c)
            break
check('every $102 status code +1..+16 is populated, none outside that range',
      {c for _, c in _sp_sites} == set(range(1, 17)))
check('...over 113 write sites in the kernel',
      len(_sp_sites) == 113)
check('...attributed to 42 handlers with 34 distinct profiles',
      len(_sp) == 42 and len({frozenset(v) for v in _sp.values()}) == 34)
check('$3E can return exactly {+9, +14} -- +14 is its "vector has no owner"',
      _sp[(1, 0x3E)] == {9, 14})
check('$49 SETTOD is privileged and +9 is its ONLY failure',
      _sp[(1, 0x49)] == {9})
check('$12 RESUME can return only +10, the precondition failure',
      _sp[(1, 0x12)] == {10})
check('$15 sleep can return only +5, the exhausted !PAT pool',
      _sp[(1, 0x15)] == {5})
check('$3B, the magic-key directive, can return only +1',
      _sp[(1, 0x3B)] == {1})
check('+4 is confined to the ASQ/event family plus SERVER and CDIR',
      {k[1] for k in _sp if 4 in _sp[k] and k[0] == 1} == {0x21, 0x22, 0x23, 0x24, 0x33, 0x3A})
check('+13 occurs in exactly one handler, TRAP #1 $06',
      [k for k in _sp if 13 in _sp[k]] == [(1, 0x06)])
check('...but is NOT that handler\'s only status -- +7, +9, +11, +12 too',
      _sp[(1, 0x06)] == {7, 9, 11, 12, 13})


# --- the SBC->AC command vocabulary is exactly three verbs ------------------
_acv = {}
for _a in range(0xF00000, 0xF0A825, 2):
    if (_w(_a) & 0xF1FF) == 0x30BC:                 # move.w #imm,(An)
        _acv.setdefault(_w(_a + 2), []).append(_a)
check('the channel primitive uses TWO pointers: a1 -> +$08, a0 -> +$0E',
      _w(0xF07F18) == 0x32BC and _w(0xF07F1A) == 0x0000 and    # move.w #0,(a1)
      _w(0xF07F1E) == 0x3340 and _w(0xF07F20) == 0x0002 and    # move.w d0,$2(a1)
      _w(0xF07F22) == 0x30BC and _w(0xF07F24) == 0x8004)       # move.w #$8004,(a0)
check('...so a $6(a1) census finds no command write at all',
      not any((_w(_a) & 0xF1F8) == 0x3140 and _w(_a + 2) == 0x0006
              and 0xF04600 <= _a <= 0xF086FF for _a in range(0xF04600, 0xF08700, 2)))
check('REQUEST-TRANSFER $8004 is written at 30 sites',
      len(_acv.get(0x8004, [])) == 30)
check('CONTINUE-TRANSFER $8005 is written at 20 sites',
      len(_acv.get(0x8005, [])) == 20)
check('...30+20 is the five copies\' 6+4 request/continue sites',
      30 + 20 == 5 * (6 + 4))
check('$8000 is written at exactly 3 sites -- XP1I, XP2I, XP3I',
      sorted(_acv.get(0x8000, [])) == [0xF06AD0, 0xF074D0, 0xF07ED0])
check('...none of them in XP4I ($F05F00-$F068FF), re-confirming its divergence',
      not any(0xF05F00 <= _a <= 0xF068FF for _a in _acv.get(0x8000, [])))
check('no OTHER immediate reaches a channel command register',
      # Scope to the task regions.  A bare "bit 15 set" filter also catches
      # $F09E1A's `move.w #$ffff,(a3)`, which is the ALLOCATABLE-REGION LIST
      # TERMINATOR in RTOS init -- 10-byte records ending in $FFFF -- and has
      # nothing to do with a channel.  That false positive is the check doing
      # its job: the proxy was wrong, not the finding.
      {v for v, sites in _acv.items() if v & 0x8000
       and any(0xF04600 <= _s <= 0xF086FF for _s in sites)}
      == {0x8000, 0x8004, 0x8005})
check('...and the $FFFF that a bare bit-15 filter catches is the region-list terminator',
      _acv.get(0xFFFF) == [0xF09E1A] and _w(0xF09E1A) == 0x36BC)
check('the BIM mask $4F appears once per copy of the primitive',
      len(_acv.get(0x004F, [])) == 5 and
      sorted(_acv[0x004F]) == [0xF056BA, 0xF060FA, 0xF06B12, 0xF07512, 0xF07F12])
check('...against 50 matching $5F restores',
      len(_acv.get(0x005F, [])) == 50)


