# --- the channel ERROR teardown is fall-through only -----------------------
def _td_reaches(_t, _lo=0xF04600, _hi=0xF08700):
    _n = 0
    for _a in range(_lo, _hi, 2):
        _o = _w(_a)
        if (_o & 0xF000) == 0x6000:
            _d = _o & 0xFF
            if _d == 0xFF:
                continue
            _tg = _bsrw(_a) if _d == 0 else _a + 2 + (_d - 256 if _d > 127 else _d)
            if _tg == _t:
                _n += 1
        elif _o in (0x4EF9, 0x4EB9) and _l(_a + 2) == _t:
            _n += 1
    return _n
check('the timeout arm reports $26C through a non-returning issuer',
      _w(0xF07F4C) == 0x303C and _w(0xF07F4E) == 0x026C and
      _w(0xF07F50) == 0x4EB9 and _l(0xF07F52) == 0x00F086C0)
check('the error arm reports $269 the same way',
      _w(0xF07F5C) == 0x303C and _w(0xF07F5E) == 0x0269 and
      _w(0xF07F60) == 0x4EB9 and _l(0xF07F62) == 0x00F086C0)
check('...and the TEARDOWN after it is reached by NOTHING -- fall-through only',
      _td_reaches(0xF07F66) == 0)
check('...in ALL FIVE copies of the primitive, at the same +$54 offset',
      all(_td_reaches(_b + 0x54) == 0 and _w(_b + 0x54) == 0x302C
          for _b in (0xF056BA, 0xF060FA, 0xF06B12, 0xF07512, 0xF07F12)))
check('...unlike the dispatch entry and the error test, which are branched to',
      _td_reaches(0xF07F84) == 1 and _td_reaches(0xF07F56) == 2)
check('the teardown clears the channel bit via the $F084A4 table, mod 32',
      _w(0xF07F66) == 0x302C and _w(0xF07F68) == 0x021A and
      _w(0xF07F6C) == 0x4BF9 and _l(0xF07F6E) == 0x00F084A4 and
      _w(0xF07F78) == 0x0B80)                                   # bclr.l d5,d0
check('...and restores the BIM control register to $5F',
      _w(0xF07F7E) == 0x36BC and _w(0xF07F80) == 0x005F and _w(0xF07F82) == 0x4E75)


