def _pd_target(_slot, _base=0xF05BA4):
    """Resolve a PanelStatusDispatch slot: each is `jmp d16(pc)` ($4EFA)."""
    _e = _base + _slot * 4
    _d = _w(_e + 2)
    return _e + 2 + (_d - 0x10000 if _d >= 0x8000 else _d)
check('...and $0F dispatches to D1_SEND ($F058B2), which never reads a2',
      _w(0xF05BA4 + 0x0F * 4) == 0x4EFA and _pd_target(0x0F) == 0xF058B2)
check('...the same handler slot $0D reaches, by a different displacement',
      _pd_target(0x0D) == 0xF058B2 and
      _w(0xF05BA4 + 0x0F * 4 + 2) != _w(0xF05BA4 + 0x0D * 4 + 2))
check('$14 dispatches to D2_FIN ($F05738), which also never reads a2',
      _pd_target(0x14) == 0xF05738)


# --- the 42-slot dispatch table, resolved PROGRAMMATICALLY -----------------
_ps_bases = {'RDHC': 0xF05BA4, 'XP4I': 0xF065E4, 'XP3I': 0xF06FFC,
             'XP2I': 0xF079FC, 'XP1I': 0xF083FC}
def _ps_profile(_base):
    """Each slot is `jmp d16(pc)` ($4EFA) or the do-nothing pair rts/nop."""
    _out = []
    for _s in range(42):
        _e = _base + _s * 4
        if _w(_e) == 0x4E75 and _w(_e + 2) == 0x4E71:
            _out.append('N')
            continue
        if _w(_e) != 0x4EFA:
            _out.append('?')
            continue
        _d = _w(_e + 2)
        _out.append(_e + 2 + (_d - 0x10000 if _d >= 0x8000 else _d) - _base)
    return _out
_ps_ref = _ps_profile(0xF05BA4)
check('every one of the 42 slots is either jmp d16(pc) or the rts/nop pair',
      '?' not in _ps_ref)
check('the handler census is 13 no-op / 10 D1_SEND / 9 POLL / 9 BLK_XFR / 1 D2_FIN',
      _ps_ref.count('N') == 13 and
      _ps_ref.count(0xF058B2 - 0xF05BA4) == 10 and
      _ps_ref.count(0xF05A12 - 0xF05BA4) == 9 and
      _ps_ref.count(0xF05B0E - 0xF05BA4) == 9 and
      _ps_ref.count(0xF05738 - 0xF05BA4) == 1)
check('...and the slot NUMBERS match the hand-enumerated map exactly',
      [_i for _i, _v in enumerate(_ps_ref) if _v == 'N']
      == [0x00, 0x0B, 0x0C, 0x11, 0x12, 0x13, 0x15, 0x20, 0x21,
          0x26, 0x27, 0x28, 0x29] and
      [_i for _i, _v in enumerate(_ps_ref) if _v == 0xF058B2 - 0xF05BA4]
      == [0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x0D, 0x0E, 0x0F, 0x10] and
      [_i for _i, _v in enumerate(_ps_ref) if _v == 0xF05A12 - 0xF05BA4]
      == [0x01, 0x0A, 0x16, 0x17, 0x19, 0x1B, 0x1F, 0x22, 0x24] and
      [_i for _i, _v in enumerate(_ps_ref) if _v == 0xF05B0E - 0xF05BA4]
      == [0x08, 0x09, 0x18, 0x1A, 0x1C, 0x1D, 0x1E, 0x23, 0x25] and
      [_i for _i, _v in enumerate(_ps_ref) if _v == 0xF05738 - 0xF05BA4] == [0x14])
check('all FIVE copies are identical slot-for-slot in relative profile',
      all(_ps_profile(_b) == _ps_ref for _b in _ps_bases.values()))
check('...using exactly four distinct handler offsets',
      len({_v for _v in _ps_ref if _v != 'N'}) == 4)


