# --- flaw #15: naming tests must cover PC-relative references -------------
def _pcrel_refs(_t):
    """Sites naming _t via lea/pea (d16,PC) -- invisible to a byte search."""
    _out = []
    for _a in range(0xF00000, 0xF0FFFC, 2):
        _o = _w(_a)
        if (_o & 0xF1FF) == 0x41FA or _o == 0x487A:
            _d = _w(_a + 2)
            if _a + 2 + (_d - 0x10000 if _d & 0x8000 else _d) == _t:
                _out.append(_a)
    return _out
check('the FPS exception reporters ARE named, by PC-relative lea',
      _pcrel_refs(0xF0A23A) == [0xF0A0FE] and
      _pcrel_refs(0xF0A242) == [0xF0A106] and
      _pcrel_refs(0xF0A24A) == [0xF0A10E])
check('...so a byte-sequence naming test alone would call them unreferenced',
      _rom_bytes.count(bytes.fromhex('f0a23a')) == 0)
check('and NONE of the seven code-as-data items is named PC-relatively either',
      all(not _pcrel_refs(_t) for _t in (0xF044A2, 0xF049A4, 0xF08F70,
                                         0xF098EC, 0xF09D6A, 0xF0A492, 0xF00A1C)))


