    check('measured: $0C00 = $1FE1A', L(0x0C00)==0x0001FE1A, hex(L(0x0C00)))
    check('measured: record 0 base $1100 limit $1FE00',
          L(0x1FE1C)==0x001100 and L(0x1FE20)==0x01FE00)
    check('measured: the seed address $10EE is untouched', L(0x10EE)==0)
    free,alloc=L(0x1108),L(0x110C)
    check('measured: node $1100 free = 460 pages', free==0x1CC, hex(free))
