def _abort_path_unlocked():
    import os
    src=open('emulator/versabus.c').read()
    check('FPS3K_CHDATA hook exists', 'FPS3K_CHDATA' in src)
    check('the data-pair echo is preserved when CHDATA is unset',
          'if (cd_have[c])' in src and 'return apif.ch_data[c][0];' in src)
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    if os.path.exists(SP+'ram_new2.bin') and os.path.exists(SP+'ram.bin'):
        check('default boot still byte-identical after the CHDATA change',
              open(SP+'ram.bin','rb').read()==open(SP+'ram_new2.bin','rb').read())
    f=SP+'ram_abort.bin'
    if os.path.exists(f):
        r=open(f,'rb').read()
        g=lambda x:int.from_bytes(r[x:x+2],'big')
        check('ABORT PATH: $1062 stamped with the channel', g(0x1062)==1, hex(g(0x1062)))
        check('ABORT PATH: status latched with bit 15 clear',
              g(0x1066)==0x0100 and not (g(0x1066) & 0x8000))
        check('ABORT PATH: $0E6E NOT written (issuer bypassed)', g(0x0E6E)==0,
              hex(g(0x0E6E)))
    # the panel code is channel + $264, computed
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('channel 1 abort code is $264 + 1 = $265', 0x264+1==0x265)
    check('MODE1 bit set is channel + 7 (bit 8 for channel 1)',
          w(0xF084EA)==0x5E40 and 1+7==8)
_abort_path_unlocked()

def _all_status_arms():
    import os
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_262.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    g=lambda x:int.from_bytes(r[x:x+2],'big')
    s2=g(0x1066)
    check('$262 arm: status latched $8000 (b15 set, b14 clear)', s2==0x8000, hex(s2))
    check('$262 arm: b15=1', bool(s2 & 0x8000))
    check('$262 arm: b14=0', not (s2 & 0x4000))
    check('$262 arm leaves $1062 unstamped (it is the bit-15-SET arm)',
          g(0x1062)==0, hex(g(0x1062)))
    # $0E6E is a shared global -- last writer wins, so it is NOT a reliable
    # per-arm indicator; the device log is.
    check('$0E6E holds a later writer\'s code, not $0262', g(0x0E6E)!=0x0262)
_all_status_arms()

def _ac_operation_observed():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    # the opening transaction of a normal request: d0 = $10, verb $8004
    check('normal request opens with AC operation $10 at $F08508',
          w(0xF08508)==0x303C and w(0xF0850A)==0x0010)
    check('the primitive polls bit 14 (DONE) after issuing',
          any(w(a)==0x0804 and w(a+2)==0x000E
              for a in range(0xF07F12,0xF07FA0,2)))
    check('a constant status cannot assert DONE, so the poll must time out',
          (0x0100 & 0x4000)==0)
    check('OR-ing the ack bit fixes it without disturbing the other arms',
          (0x0100|0x4000)&0x4000 and not ((0x8000|0)&0x4000))
_ac_operation_observed()

def _issuer_return_semantics():
    src=open('emulator/versabus.c').read()
    check('FPS3K_ISSUER_RETURN hook exists', 'FPS3K_ISSUER_RETURN' in src)
    check('...documented as the chassis performing the deferred rts',
          'deferred `rts`' in src or 'deferred rts' in src)
    # the release mechanism: code $11 writes the stacked PC (offsets 64/66/68)
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('the panel ISR saves 16 longwords (movem.l d0-d7/a0-a7,-(a7))',
          w(0xF04930)==0x48E7 and w(0xF04932)==0xFFFF)
    check('the ISR frame is 16 longwords, so the stacked PC follows it',
          w(0xF04930)==0x48E7 and w(0xF04932)==0xFFFF and 16*4+4==68)
    check('the bit-7 dispatcher range-checks against $44, the frame ceiling',
          any(w(a)==0x0C40 and w(a+2)==0x0044 for a in range(0xF0495C,0xF049F0,2)))
_issuer_return_semantics()

def _normal_request_block():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('{mode,opcode} built by move.w #$ffff / swap / move.w',
          w(0xF08502)==0x303C and w(0xF08504)==0xFFFF and w(0xF08506)==0x4840)
    check('transaction 1 opcode is $10', w(0xF08508)==0x303C and w(0xF0850A)==0x0010)
    check('transaction 1 payload d1 = $10', w(0xF0850C)==0x7210)
    check('transaction 1 continue payload d2 = $1', w(0xF0851A)==0x7401)
    check('a2 loaded from the per-channel pointer $1080(a2)',
          w(0xF08516)==0x246A and w(0xF08518)==0x1080)
    check('transaction 2 opcode is $0E', w(0xF08528)==0x303C and w(0xF0852A)==0x000E)
    check('transaction 2 operand is PRE-DECREMENTED from $101E',
          w(0xF0852C)==0x2222)
    check('transaction 2 payload d2 = $10', w(0xF0852E)==0x7410)
    check('both transactions call the same primitive $F07F12',
          w(0xF0851C)==0x4EB9 and w(0xF08530)==0x4EB9)
    check('teardown clears $1080 (stride 4) and $1098 (stride 2)',
          w(0xF0853C)==0x257C and w(0xF08548)==0x357C)
_normal_request_block()

def _transaction_primitive():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    check('primitive masks the BIM with $4F', w(0xF07F12)==0x36BC and w(0xF07F14)==0x004F)
    check('pushes d4', w(0xF07F16)==0x3F04)
    check('zeroes the data high half', w(0xF07F18)==0x32BC and w(0xF07F1A)==0x0000)
    check('writes the opcode to +$0A', w(0xF07F1E)==0x3340 and w(0xF07F20)==0x0002)
    check('issues $8004', w(0xF07F22)==0x30BC and w(0xF07F24)==0x8004)
    check('poll budget is 1000', l(0xF07F28)==0x3E8)
    check('DONE test is btst.l #$e on d4 (a DATA register -> long)',
          w(0xF07F30)==0x0804 and w(0xF07F32)==0x000E)
    check('ERROR test is btst.l #$d on d4', w(0xF07F3E)==0x0804 and w(0xF07F40)==0x000D)
    check('timeout reports $26C', w(0xF07F4C)==0x303C and w(0xF07F4E)==0x026C)
    check('error reports $269', w(0xF07F5C)==0x303C and w(0xF07F5E)==0x0269)
    op=w(0xF07F5A); d=op & 0xFF
    tgt=0xF07F5A+2+sw(d|(0xFF00 if d & 0x80 else 0))
    check('success branch targets the dispatch $F07F84', tgt==0xF07F84)
    check('the pop at $F07F6A is SKIPPED on the success path', tgt>0xF07F6A)
    check('so the primitive does not return on success', w(0xF07F6A)==0x381F)
_transaction_primitive()

def _continue_phase():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('continue phase composes d2 by swap/write/swap/write',
          w(0xF07F90)==0x4842 and w(0xF07F92)==0x3282 and
          w(0xF07F94)==0x4842 and w(0xF07F96)==0x3342)
    check('high half goes to +$08, low half to +$0A',
          w(0xF07F98)==0x0002)
    check('continue phase issues $8005', w(0xF07F9A)==0x30BC and w(0xF07F9C)==0x8005)
    check('same 1000-iteration budget', l(0xF07FA0)==0x3E8)
    check('same DONE/ERROR tests on d4', w(0xF07FA8)==0x0804 and
          w(0xF07FAA)==0x000E and w(0xF07FCE)==0x0804 and w(0xF07FD0)==0x000D)
    check('continue phase timeout is $26C (shared with request)',
          w(0xF07FC4)==0x303C and w(0xF07FC6)==0x026C)
    check('continue phase error is $26B (request uses $269)',
          w(0xF07FD4)==0x303C and w(0xF07FD6)==0x026B)
    check('dispatch is lsl #2 / lea base A / jmp (a4,d0.w)',
          w(0xF07F84)==0xE548 and w(0xF07F86)==0x49F9 and
          l(0xF07F88)==0xF083FC and w(0xF07F8C)==0x4EF4)
_continue_phase()

def _blk_xfr_decode():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    check('BLK_XFR opens with swap d0 (the mode word)', w(0xF05B0E)==0x4840)
    check('it forms $FF0008 as the bulk-port pointer',
          l(0xF05B12)==0xFF0000 and w(0xF05B16)==0x4BEC and w(0xF05B18)==0x0008)
    check('the special case compares the CALLER pointer a2 against it',
          w(0xF05B1A)==0xBBCA)
    check('the ready poll reads $FF0004 and tests bit 0',
          w(0xF05B1E)==0x382C and w(0xF05B20)==0x0004 and
          w(0xF05B22)==0x0804 and w(0xF05B24)==0x0000)
    op=w(0xF05B26); d=op & 0xFF
    tgt=0xF05B26+2+sw(d|(0xFF00 if d & 0x80 else 0))
    check('the poll branches BACK to itself: unbounded spin, no budget',
          (op>>8)==0x67 and tgt==0xF05B1E)
    check('...unlike the transaction poll, which is bounded at 1000',
          l(0xF07F28)==0x3E8)
    check('the mode test is cmpi.w #$0 on the swapped d0',
          w(0xF05B30)==0x0C40 and w(0xF05B32)==0x0000)
_blk_xfr_decode()

def _unbounded_waits():
    import re, subprocess, os
    if not os.path.exists('tools/find_unbounded_waits.py'): return
    try:
        out=subprocess.run(['python3','tools/find_unbounded_waits.py'],
                           capture_output=True,text=True,timeout=180).stdout
    except Exception:
        return
    if not out.strip(): return
    body=[l for l in out.split('\n') if l.strip().startswith('$F0')]
    op=[l for l in body if not re.search(r'\$F0(8[7-9C-F]|9[0-9A-F]|A4)', l)]
    n218=sum(1 for l in op if re.search(r'\$218\(a[0-7]\)', l))
    n004=sum(1 for l in op if re.search(r'\$4\(a[0-7]\)', l))
    check('$FF0218 bit 15 has 20 unbounded spin sites', n218==20, str(n218))
    check('...matching the independently-censused "polled at 20 sites"', n218==20)
    check('$FF0004 bit 0 has 11 unbounded spin sites', n004==11, str(n004))
    check('these are the only unbounded operational device waits',
          n218+n004==31)
_unbounded_waits()

