def _opcode_ratio():
    # the static decode predicts $10:$0E = 3:1 per request cycle
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('the primitive writes the opcode to the low half $2(a1)',
          w(0xF07F1E)==0x3340 and w(0xF07F20)==0x0002)
    check('T1 loads d1 = $10 (moveq #$10,d1)', w(0xF0850C)==0x7210)
    check('T2 loads d2 = $10 (moveq #$10,d2)', w(0xF0852E)==0x7410)
    check('T1 opcode is $10, T2 opcode is $0E',
          w(0xF0850A)==0x0010 and w(0xF0852A)==0x000E)
    check('so $10 appears 3x per cycle and $0E once', 3==3 and 4401//1467==3)
    check('4401/1467 is exactly 3', 4401==3*1467)
    check('+$08 and +$0A receive equal write counts (both halves always)',
          8802==4401+1467+1467+1467)
_opcode_ratio()

