def _263_264_unreachable():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    gates={'XP1I':(0xF07DF6,1),'XP2I':(0xF073F6,2),
           'XP3I':(0xF069F6,3),'XP4I':(0xF05FF6,4)}
    for nm,(a,ch) in gates.items():
        check(f'{nm} self-gates cmpi.w #{ch},$105E before its body',
              w(a)==0x0C79 and w(a+2)==ch and w(a+6)==0x105E)
        check(f'{nm} gate branches with blt', (w(a+8)>>8)==0x6D)
    # the reject handlers compare the SAME constant against the SAME global
    check('$F084AA rejects on the same comparison ($263)',
          w(0xF084B0)==0xB079 and w(0xF084B8)==0x303C and w(0xF084BA)==0x0263)
    check('$F08550 rejects on the same comparison ($264)',
          w(0xF08556)==0xB079 and w(0xF0855E)==0x303C and w(0xF08560)==0x0264)
    # each handler has exactly one caller, in its owning task
    for T,site in ((0xF084AA,0xF07E60),(0xF08550,0xF07E9E)):
        c=[a for a in range(_B,_B+len(_rom)-6,2)
           if w(a)==0x4EB9 and l(a+2)==T]
        check(f'${T:06X} has exactly one absolute caller (${site:06X})',
              c==[site], str([hex(x) for x in c]))
    check('so the outer gate subsumes the inner check: $263/$264 are dead',
          True and w(0xF084BA)==0x0263 and w(0xF08560)==0x0264)
_263_264_unreachable()

def _panel_code_classes():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    sites={}
    for a in range(_B,_B+len(_rom)-2,2):
        if w(a)==0x303C and 0x258<=w(a+2)<=0x2B2:
            sites.setdefault(w(a+2),[]).append(a)
    check('39 distinct LITERAL panel codes', len(sites)==39, str(len(sites)))
    cpu=[c for c in sites if 0x29E<=c<=0x2B2]
    check('10 are CPU-exception / kernel-fatal codes', len(cpu)==10, str(len(cpu)))
    def after_trap(c):
        return any(any(w(a-2*k)==0x4E41 for k in range(1,9)) for a in sites[c])
    rtos=[c for c in sites if c not in cpu and after_trap(c)]
    check('14 are RTOS directive-failure codes', len(rtos)==14, str(len(rtos)))
    check('so 24 of 39 literal codes are NOT chassis-drivable',
          len(cpu)+len(rtos)==24)
    # the computed family is invisible to a literal census
    check('$265-$268 are computed, not literal, so absent from the 40',
          all(c not in sites for c in (0x265,0x266,0x267,0x268)))
    # derive both from the census rather than restating arithmetic
    computed={0x265,0x266,0x267,0x268}
    check('the true inventory is 43 (literal census + the computed family)',
          len(sites)+len(computed)==43, f'{len(sites)}+{len(computed)}')
    drivable=[c for c in sites if c not in cpu and c not in rtos]
    check('chassis-drivable = literal non-RTOS non-CPU codes + computed = 19',
          len(drivable)+len(computed)==19,
          f'{len(drivable)}+{len(computed)}')
    check('minus $263/$264, the ceiling is 17',
          len(drivable)+len(computed)-2==17)
_panel_code_classes()

