def _error_surface_offsets():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    BLK=[0xF056BA,0xF060FA,0xF06B12,0xF07512,0xF07F12]
    exp={0x269:1,0x26A:4,0x26B:2,0x26C:9}
    for code,per in exp.items():
        offs={}
        for a in range(_B,_B+len(_rom)-2,2):
            if w(a)==0x303C and w(a+2)==code:
                for b in BLK:
                    if 0 <= a-b < 0x5A0:
                        offs.setdefault(a-b,0)
                        offs[a-b]+=1
                        break
        check(f'${code:03X} occupies {per} offset(s) per copy', len(offs)==per,
              str(sorted(hex(o) for o in offs)))
        check(f'${code:03X} appears in all five copies at every offset',
              all(v==5 for v in offs.values()), str(sorted(offs.values())))
        check(f'${code:03X} totals {per*5} sites', sum(offs.values())==per*5)
    check('nine bounded polls = 1 primitive + 1 continue + 4 D2_FIN + 3 D1_SEND',
          1+1+4+3==9)
    check('seven of the nine carry an error report', 1+2+4==7)
_error_surface_offsets()

def _block_access_map():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    BLK=[0xF056BA,0xF060FA,0xF06B12,0xF07512,0xF07F12]
    PAT={0x30BC:'verb',0x3340:'d0lo',0x32BC:'imm',0x3282:'d2hi',0x3342:'d2lo',
         0x3341:'d1lo',0x3281:'d1hi',0x36BC:'bim',0x3810:'stat',
         0x382C:'rdy',0x302C:'mask'}
    acc={}
    for a in range(_B,_B+len(_rom)-2,2):
        if w(a) in PAT:
            for b in BLK:
                if 0 <= a-b < 0x5A0:
                    k=(a-b, PAT[w(a)])
                    acc[k]=acc.get(k,0)+1
                    break
    check('57 distinct device-access offsets in the block', len(acc)==57,
          str(len(acc)))
    check('every offset appears in exactly 5 copies',
          all(v==5 for v in acc.values()),
          str(sorted({v for v in acc.values()})))
    kinds={}
    for (o,k),v in acc.items(): kinds[k]=kinds.get(k,0)+1
    # MEASURED, not estimated: 10 verb, 11 BIM, 10 $FF021A offsets per copy.
    check('10 verb writes per copy', kinds.get('verb')==10, str(kinds.get('verb')))
    check('11 BIM bracket writes per copy', kinds.get('bim')==11, str(kinds.get('bim')))
    check('10 teardown reads of $FF021A per copy', kinds.get('mask')==10,
          str(kinds.get('mask')))
    # NB: 10 != the 9 $26C poll points -- the earlier "two censuses agree" claim
    # was based on an estimated 9 and is RETRACTED.
    check('$FF021A reads (10) exceed the $26C poll points (9)',
          kinds.get('mask')==10)
_block_access_map()

def _xp4i_offset_map():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    TASK={'XP4I':0xF05F00,'XP3I':0xF06900,'XP2I':0xF07300,'XP1I':0xF07D00}
    PAT={0x30BC,0x32BC,0x337C,0x3B41,0x36BC,0x3B7C,0x322D,0x302C}
    acc={}
    for a in range(_B,_B+len(_rom)-2,2):
        if w(a) in PAT:
            for nm,base in TASK.items():
                if 0 <= a-base < 0xA00:
                    acc.setdefault((a-base,w(a)),set()).add(nm); break
    x4={o for (o,k),v in acc.items() if v=={'XP4I'}}
    oth={o for (o,k),v in acc.items() if v=={'XP1I','XP2I','XP3I'}}
    check('41 XP4I-only device-access offsets', len(x4)==41, str(len(x4)))
    check('41 other-three-only offsets', len(oth)==41, str(len(oth)))
    pairs=[a for a in x4 if any(b-a==24 for b in oth)]
    check('39 pair at exactly 24 bytes with XP4I lower', len(pairs)==39,
          str(len(pairs)))
    check('exactly two XP4I offsets are unpaired',
          sorted(set(x4)-set(pairs))==[0x106,0x118],
          str(sorted(hex(x) for x in set(x4)-set(pairs))))
    # the missing three-access acknowledgement on channels 1-3
    for o,op in ((0x1C6,0x32BC),(0x1CA,0x337C),(0x1D0,0x30BC)):
        check(f'+${o:03X} present in XP1I/2I/3I only',
              acc.get((o,op))=={'XP1I','XP2I','XP3I'}, str(acc.get((o,op))))
_xp4i_offset_map()

def _issuer_identity():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    ISS=[0xF04500,0xF05688,0xF05E56,0xF068A8,0xF072C0,0xF07CC0,0xF086C0,0xF0A57E]
    diff=[i for i in range(0,48,2) if len({w(b+i) for b in ISS})!=1]
    check('all eight issuers are word-identical over 48 bytes',
          diff==[], str([hex(x) for x in diff]))
    check('that is 24 words x 8 copies with zero variation', 48//2==24)
_issuer_identity()

def _tcbio1i_device_map():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('TCBIO1I programs BIM2 ch2 with $5F',
          w(0xF05DB8)==0x3B7C and w(0xF05DBA)==0x005F and w(0xF05DBC)==0x0254)
    check('saves MODE2 at $F05DE6', w(0xF05DE6)==0x3E2D and w(0xF05DE8)==0x0210)
    check('pages MODE2 to $F at $F05DEA',
          w(0xF05DEA)==0x3B7C and w(0xF05DEC)==0x000F)
    check('restores MODE2 at $F05E44', w(0xF05E44)==0x3B47 and w(0xF05E46)==0x0210)
    check('mailbox base $700000 loaded as an immediate into a4',
          w(0xF05DE0)==0x287C and l(0xF05DE2)==0x700000)
    check('mailbox READ is +$1C off that base',
          w(0xF05DF0)==0x222C and w(0xF05DF2)==0x001C)
    check('mailbox WRITE is +$20 off that base',
          w(0xF05E40)==0x2941 and w(0xF05E42)==0x0020)
    # no loops: no backward branch inside the ISR span
    def sw(v): return v-0x10000 if v & 0x8000 else v
    back=[a for a in range(0xF05DD6,0xF05E50,2)
          if 0x60 <= (w(a)>>8) <= 0x6F and (w(a)&0xFF) not in (0,0xFF)
          and a+2+sw((w(a)&0xFF)|(0xFF00 if w(a)&0x80 else 0)) < a]
    # RETRACTED: $F05E20 branches back to $F05E00 -- the $282 re-sync loop.
    check('the ISR span contains exactly one backward branch, the $282 re-sync',
          back==[0xF05E20], str([hex(x) for x in back]))
_tcbio1i_device_map()

def _rdhc_profile():
    import re
    from collections import Counter
    src=open('fps3k_custom.asm').read()
    c=Counter()
    for m in re.finditer(r'^([0-9A-F]{6})  (?:[0-9a-f]{2} )+\s+(\S+)\s+(.*)$',src,re.M):
        a=int(m.group(1),16)
        if not (0xF04600 <= a < 0xF05D00): continue
        for d in re.finditer(r'\$([2][0-9a-f]{2})\(a[0-7]\)', m.group(3)):
            c[int(d.group(1),16)]+=1
    check('RDHC touches $FF0218 most, 36 times', c[0x218]==36, str(c[0x218]))
    check('RDHC touches CHANSEL 26 times', c[0x204]==26, str(c[0x204]))
    check('RDHC touches the IRQ mask 20 times', c[0x21A]==20, str(c[0x21A]))
    check('RDHC touches 9 distinct XLTR registers', len(c)==9, str(sorted(hex(x) for x in c)))
    # the false positive: lea $a(a7),a7 is a stack adjustment, not $FF000A
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('$F05670 is lea $a(a7),a7 -- a stack adjustment, not a device access',
          w(0xF05670)==0x4FEF and w(0xF05672)==0x000A)
    check('...releasing the 10-byte semaphore block after ATSEM/WTSEM',
          w(0xF05662)==0x7029 and w(0xF0566C)==0x702A)
_rdhc_profile()

def _selftest_device_map():
    import re
    from collections import Counter
    src=open('fps3k_custom.asm').read()
    absr=Counter(); disp=Counter()
    for m in re.finditer(r'^([0-9A-F]{6})  (?:[0-9a-f]{2} )+\s+(\S+)\s+(.*)$',
                         src, re.M):
        a=int(m.group(1),16); ops=m.group(3)
        if not (0xF08700 <= a < 0xF09C00): continue
        for d in re.finditer(r'\$(1fff0|f70018|f70019|f70001)\b', ops):
            absr[d.group(1)]+=1
        for d in re.finditer(r'\$(2[0-9a-f]{2})\(a[0-7]\)', ops):
            disp[int(d.group(1),16)]+=1
    check('self-test holds all 23 $1FFF0 references', absr['1fff0']==23,
          str(absr['1fff0']))
    check('self-test holds all 9 $F70018 references', absr['f70018']==9,
          str(absr['f70018']))
    check('$FF0214 has exactly one self-test access', disp[0x214]==1,
          str(disp[0x214]))
    check('$FF0200 and $FF021A each: one literal write + one read-back',
          disp[0x200]==2 and disp[0x21A]==2,
          f'{disp[0x200]},{disp[0x21A]}')
    check('$FF0204 dominates as the phase-counter broadcast', disp[0x204]==74,
          str(disp[0x204]))
    # the three range-resident immediates are NOT device accesses
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('$F08A70 is cmpi.l #$FFFFFFFF, not a device access', w(0xF08A70)==0x0C87)
    check('$F0998E is move.l #$FF00FF,d0, a walking pattern', w(0xF0998E)==0x203C)
    check('$F08E90 is ori.l #$FF0F1F,(a7)+, not a device access', w(0xF08E90)==0x009F)
_selftest_device_map()

def _rtosinit_device_map():
    import re
    from collections import Counter
    src=open('fps3k_custom.asm').read()
    absr=Counter(); disp=Counter()
    for m in re.finditer(r'^([0-9A-F]{6})  (?:[0-9a-f]{2} )+\s+(\S+)\s+(.*)$',
                         src, re.M):
        a=int(m.group(1),16); ops=m.group(3)
        if not (0xF09C00 <= a < 0xF0A826): continue
        for d in re.finditer(r'\$(70001c|700020)\b', ops): absr[d.group(1)]+=1
        for d in re.finditer(r'\$(2[0-9a-f]{2})\(a[0-7]\)', ops):
            disp[int(d.group(1),16)]+=1
    check('RTOS init reads the mailbox once', absr['70001c']==1,
          str(absr['70001c']))
    bim=[o for o in disp if o>=0x230]
    vr=[o for o in bim if (o & 0xF)>=8]
    cr=[o for o in bim if (o & 0xF)<8]
    check('RTOS init programs exactly ten BIM vector registers', len(vr)==10,
          str(sorted(hex(o) for o in vr)))
    check('...and six control registers', len(cr)==6,
          str(sorted(hex(o) for o in cr)))
    check('$25E (BIM2 VR3) is NOT among them', 0x25E not in bim)
    check('MODE2 is touched twice (read, then forced zero)', disp[0x210]==2,
          str(disp[0x210]))
_rtosinit_device_map()

def _status_15_16_pair():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('the type byte is read from $9(a5)',
          w(0xF0315A)==0x1C2D and w(0xF0315C)==0x0009)
    check('type is range-checked to 1..3',
          w(0xF0315E)==0x0C06 and w(0xF03160)==0x0001 and
          w(0xF03166)==0x0C06 and w(0xF03168)==0x0003)
    check('type below 1 branches to the +15 site',
          (w(0xF03164)>>8)==0x6D)
    check('type above 3 branches to the same +15 site',
          (w(0xF0316A)>>8)==0x6E)
    check('the flags byte is the ADJACENT $8(a5)',
          w(0xF03170)==0x1E2D and w(0xF03172)==0x0008)
    check('flags bit 7 is tested long on a data register',
          w(0xF03174)==0x0807 and w(0xF03176)==0x0007)
    check('bit 7 SET yields +16', w(0xF0317A)==0x066E and w(0xF0317C)==0x0010)
    check('the +15 arm is the sibling at $F03182',
          w(0xF03182)==0x066E and w(0xF03184)==0x000F)
    # site counts
    import re
    ker=open('fps3k_kernel.asm').read()
    n15=len(re.findall(r'(addi|move)\.w +#\$f, \$102\(a6\)', ker))
    n16=len(re.findall(r'(addi|move)\.w +#\$10, \$102\(a6\)', ker))
    check('+15 has 5 sites', n15==5, str(n15))
    check('+16 has 4 sites', n16==4, str(n16))
_status_15_16_pair()

def _atsem_descriptor_fields():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    # directive $29's handler is the +15/+16 test's own address
    e=0xF003D8+0x29*4
    check('TRAP #1 slot $29 resolves to $F03150', e+sw(w(e))==0xF03150,
          hex(e+sw(w(e))))
    # the four ROM templates: flags 0, type 2
    for a,nm in ((0xF05F2C,'AXP4'),(0xF0692C,'AXP3'),
                 (0xF0732C,'AXP2'),(0xF07D2C,'AXP1')):
        d=_rom[a-_B:a-_B+10]
        check(f'{nm} template names itself', d[:4]==nm.encode())
        check(f'{nm} template flags byte (+8) is $00', d[8]==0x00)
        check(f'{nm} template type byte (+9) is $02', d[9]==0x02)
        check(f'{nm} passes ATSEM: type in 1..3 and flags bit 7 clear',
              1 <= d[9] <= 3 and not (d[8] & 0x80))
    check('the descriptor is 10 bytes = name + longword + flags + type',
          4+4+1+1==10)
_atsem_descriptor_fields()

def _directives_1C_45():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    T=0xF003D8
    for d,size,handler in ((0x1C,14,0xF03CC2),(0x45,12,0xF036C2)):
        e=T+d*4
        check(f'directive ${d:02X} handler resolves to ${handler:06X}',
              e+sw(w(e))==handler, hex(e+sw(w(e))))
        check(f'directive ${d:02X} declares a {size}-byte block',
              (w(e+2)>>8)==size, str(w(e+2)>>8))
        check(f'directive ${d:02X} carries flag bits 6 and 7',
              (w(e+2) & 0xC0)==0xC0, hex(w(e+2) & 0xFF))
    check('$1C opens with the privilege check btst.b #$f,$28(a6)',
          w(0xF03CC2)==0x082E and w(0xF03CC4)==0x000F and w(0xF03CC6)==0x0028)
    check('...failing with +9', w(0xF03CCA)==0x066E and w(0xF03CCC)==0x0009)
    check('$45 tests target state bit 10 (btst.b #$a,$2c(a5))',
          w(0xF036C4)==0x082D and w(0xF036C6)==0x000A and w(0xF036C8)==0x002C)
    check('...failing with +10', w(0xF036CC)==0x066D and w(0xF036CE)==0x000A)
    check('memory btst: 10 mod 8 = 2, and $2C is the HIGH byte -> word bit 10',
          (10 % 8)==2)
_directives_1C_45()

def _state_bit_owners():
    import subprocess, re
    try:
        out=subprocess.run(['python3','tools/attribute_state_bits.py'],
                           capture_output=True,text=True,timeout=180).stdout
    except Exception:
        return
    if not out.strip(): return
    def line(b):
        m=re.search(r'^   bit %-2d  (.*)$'%b, out, re.M)
        return m.group(1) if m else ''
    check('bit 7 is set by $0F and $10 only',
          'bset($0F,$10)' in line(7), line(7))
    check('bit 7 has no bclr anywhere (sticky TERMINATED)',
          'bclr' not in line(7), line(7))
    check('bit 5 is set by $21 and cleared by $20 DEASQ',
          'bset($21)' in line(5) and '$20' in line(5), line(5))
    check('bit 3 is set by $14 and cleared by $13 WAIT',
          'bset($14' in line(3) and '$13' in line(3), line(3))
    check('bit 10 is touched by the exception directives $40/$41/$45',
          all(d in line(10) for d in ('$40','$41','$45')), line(10))
    check('bits 0, 1 and 8 have no operations at all',
          line(0)=='' and line(1)=='' and line(8)=='')
    # $4B is UNIMPLEMENTED -- its slot points at the shared error stub $F003D0,
    # so it must not appear as an owner at all.
    n4b=sum(1 for b in range(16) if '$4B' in line(b))
    check('$4B never appears as an owner (it is an unimplemented slot)',
          n4b==0, str(n4b))
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    e=0xF003D8+0x4B*4
    check('$4B resolves to the shared error stub $F003D0',
          e+sw(w(e))==0xF003D0, hex(e+sw(w(e))))
    shared=sum(1 for i in range(77)
               for ee in [0xF003D8+i*4]
               if sw(w(ee)) and ee+sw(w(ee))==0xF003D0)
    check('17 slots share that stub', shared==17, str(shared))
_state_bit_owners()

def _attribution_audit():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    def sw(v): return v-0x10000 if v & 0x8000 else v
    from collections import Counter
    T=0xF003D8; c=Counter()
    for i in range(77):
        e=T+i*4
        if sw(w(e)): c[e+sw(w(e))]+=1
    tbl=sorted((e+sw(w(e)),i) for i in range(77)
               for e in [T+i*4] if sw(w(e)) and c[e+sw(w(e))]==1)
    def owner(a):
        for k,(h,i) in enumerate(tbl):
            if h<=a and (k+1>=len(tbl) or a<tbl[k+1][0]): return i
        return None
    for site,d in ((0xF03150,0x29),(0xF0317A,0x29),(0xF021C2,0x3D),
                   (0xF03CF8,0x1C),(0xF03734,0x45)):
        check(f'${site:06X} attributes to directive ${d:02X} under sound bounds',
              owner(site)==d, str(owner(site)))
    check('$4B is excluded because its handler is shared',
          all(i!=0x4B for _,i in tbl))
_attribution_audit()

def _attr_word_owners():
    import subprocess, re
    try:
        out=subprocess.run(['python3','tools/attribute_attr_bits.py'],
                           capture_output=True,text=True,timeout=180).stdout
    except Exception:
        return
    if not out.strip(): return
    def line(b):
        m=re.search(r'^   bit %-2d  (.*)$'%b, out, re.M)
        return m.group(1) if m else ''
    check('attr bit 7 is set by $29 (the CRSEM/ATSEM body)',
          'bset($29)' in line(7), line(7))
    check('attr bit 6: set by $40, cleared by $41', 'bset($40)' in line(6)
          and 'bclr($41' in line(6), line(6))
    check('attr bit 4 is set by $1A', 'bset($1A)' in line(4), line(4))
    check('attr bit 3 is set by $1B', 'bset($1B)' in line(3), line(3))
