def _cpu_exception_class_drivable():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    # the firmware jsrs into RAM at $10AE + (ch-1)*4
    check('the CP trampoline is called with jsr (a2) at FOUR sites, one per XP task',
          all(w(x)==0x4E92 for x in (0xF067E0,0xF071F8,0xF07BF8,0xF085F8)))
    check('...each immediately preceded by lea $10ae(a2),a2',
          all(w(x-4)==0x45EA and w(x-2)==0x10AE
              for x in (0xF067E0,0xF071F8,0xF07BF8,0xF085F8)))
    check('...INCLUDING XP4I, which keeps the request arm',
          w(0xF067E0)==0x4E92 and w(0xF067DC)==0x45EA)
    check('the ILLEGAL opcode $4AFC never occurs in the stock ROM image',
          _rom.count(b'\x4a\xfc')==0)
    check('divu #0,d0 ($80FC 0000) never occurs in the stock ROM image',
          _rom.count(b'\x80\xfc\x00\x00')==0)
    # the FPS layer owns illegal and divide-by-zero reporters
    for code,off in ((0x2A0,0xF0A24A),(0x2A1,0xF0A252)):
        found=any(w(a)==0x303C and w(a+2)==code
                  for a in range(0xF0A23A,0xF0A280,2))
        check(f'the ${code:03X} reporter exists in the exception table', found)
    check('$2B2 is the kernel fatal stub inside the kernel region',
          any(w(a)==0x303C and w(a+2)==0x02B2 for a in range(0xF00190,0xF001C0,2)))
_cpu_exception_class_drivable()

def _address_error_disabled():
    cfg=open('emulator/musashi/m68kconf.h').read()
    import re
    m=re.search(r'#define\s+M68K_EMULATE_ADDRESS_ERROR\s+(\S+)', cfg)
    check('M68K_EMULATE_ADDRESS_ERROR is present in m68kconf.h', m is not None)
    # WAS: "...and is OFF, so vector 3 can never fire".  Turned ON 2026-08-03
    # after an odd-address move.w to the MC6840 in tools/fps3k_probe.py ran
    # clean here and would have faulted on iron.  Verified behaviour-neutral by
    # CLEAN builds both ways: identical final PC and a byte-identical 128 KB RAM
    # image, so the stock firmware never makes such an access.
    check('...and is ON, so vector 3 fires as a real 68000 does',
          m and 'ON' in m.group(1), m.group(1) if m else '?')
    mt=re.search(r'#define\s+M68K_EMULATE_TRACE\s+(\S+)', cfg)
    check('M68K_EMULATE_TRACE is ON (the documented earlier fix)',
          mt and 'ON' in mt.group(1), mt.group(1) if mt else '?')
    # the $29F reporter is installed and correct despite being unreachable
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('the $29F reporter exists at $F0A242',
          w(0xF0A242)==0x303C and w(0xF0A244)==0x029F)
_address_error_disabled()

def _exception_reporters_driven():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    # every reporter the trampoline reached exists at its table slot
    for code,addr in ((0x29E,0xF0A23A),(0x29F,0xF0A242),(0x2A0,0xF0A24A),
                      (0x2A1,0xF0A252)):
        check(f'the ${code:03X} reporter is at ${addr:06X}',
              w(addr)==0x303C and w(addr+2)==code)
    # 68000 CHK is word-only: 41BC, not the 68020 long form 413C
    check('the application region contains ZERO chk instructions ($41BC)',
          _rom[0xF04488-_B:0xF0A825-_B].count(b'\x41\xbc')==0)
    check('...and zero of the 68020 long form $413C either',
          _rom[0xF04488-_B:0xF0A825-_B].count(b'\x41\x3c')==0)
    # a privileged instruction faulting proves user mode
    check('ori.w #imm,sr ($007C) does occur -- the level-7 mask at $F00A1C',
          w(0xF00A24)==0x007C or _rom.count(b'\x00\x7c\x70\x00')>0)
_exception_reporters_driven()

