def _rtos_failure_timing():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    TASK={'XP4I':(0xF05F00,0xF06900),'XP3I':(0xF06900,0xF07300),
          'XP2I':(0xF07300,0xF07D00),'XP1I':(0xF07D00,0xF08700),
          'RDHC':(0xF04600,0xF05D00),'IO1I':(0xF05D00,0xF05F00)}
    def where(a):
        for nm,(lo,hi) in TASK.items():
            if lo <= a < hi: return nm
        return '?'
    def sites(code):
        return [a for a in range(_B,_B+len(_rom)-2,2)
                if w(a)==0x303C and w(a+2)==code]
    for code,n in ((0x26D,4),(0x270,4)):
        s=sites(code)
        check(f'${code:03X} has one site per XP task', len(s)==n, str(len(s)))
    for code,n in ((0x26E,8),(0x271,8)):
        s=sites(code)
        check(f'${code:03X} has two sites per XP task', len(s)==n, str(len(s)))
    check('$276-$27B are RDHC-only',
          all({where(a) for a in sites(c)}=={'RDHC'}
              for c in (0x276,0x277,0x278,0x279,0x27A,0x27B)))
    check('$27E-$280 are TCBIO1I-only',
          all({where(a) for a in sites(c)}=={'IO1I'}
              for c in (0x27E,0x27F,0x280)))
    check('$27D is emitted by both RDHC and TCBIO1I',
          {where(a) for a in sites(0x27D)}=={'RDHC','IO1I'})
_rtos_failure_timing()

