def _cprun_executed():
    import os
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_cp2.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    W=lambda a:int.from_bytes(r[a:a+2],'big')
    L=lambda a:int.from_bytes(r[a:a+4],'big')
    n=[W(0x10000+2*i) for i in range(9)]
    check('CPRUN wrote EIGHT NOP words at $10000',
          all(x==0x4E71 for x in n[:8]), str([hex(x) for x in n[:8]]))
    check('...and exactly eight -- the ninth is untouched', n[8]==0x0000)
    check('the terminator entry address was in range',
          L(0x0E7E)==0x00010001)
    check('op $8 success cleared $0E74, satisfying the main-loop gate',
          W(0x0E74)==0x0000)
_cprun_executed()

def _user_task_created():
    import os
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_cp2.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    W=lambda a:int.from_bytes(r[a:a+2],'big')
    L=lambda a:int.from_bytes(r[a:a+4],'big')
    tcbs=[a for a in range(0x1D000,0x20000,0x100) if r[a:a+4]==b'!TCB']
    check('seven TCBs exist after CPRUN', len(tcbs)==7, str(len(tcbs)))
    check('the new one is USER at $1DB00',
          0x1DB00 in tcbs and r[0x1DB10:0x1DB14]==b'USER')
    check("USER's entry point is the staging buffer $10000",
          L(0x1DB00+0x6C)==0x00010000)
    check('USER is created UNPRIVILEGED (attr bit 15 clear)',
          not (W(0x1DB00+0x28) & 0x8000), hex(W(0x1DB00+0x28)))
    check('...unlike every TDTI task, which reads $A081/$A001',
          (W(0x1E900+0x28) & 0x8000) and (W(0x1F300+0x28) & 0x8000))
    check('CRTCB reported success', W(0x1DB00+0x102)==0)
    check('the seventh TCB sits BELOW the clean-boot heap bottom $1DD00',
          min(tcbs) < 0x1DD00, hex(min(tcbs)))
_user_task_created()

def _mode1_b14_ownership():
    import re
    L=open('fps3k_custom.asm').read().split('\n')
    st=[];cl=[]
    for i,l in enumerate(L):
        m=re.match(r'^(F0[0-9A-F]{4})\s+[0-9a-f ]+\s+(bset|bclr)\.l\s+#\$e,\s*d(\d)',l)
        if not m: continue
        for j in range(i+1,min(i+4,len(L))):
            if re.search(r'move\.w\s+d%s,\s*\$202\('%m.group(3),L[j]):
                (st if m.group(2)=='bset' else cl).append(m.group(1)); break
    check('MODE1 bit 14 has exactly ONE bset site', len(st)==1, str(st))
    check('...and it is $F047DE, the successful $0D START of USER', st==['F047DE'])
    check('MODE1 bit 14 has 13 bclr sites', len(cl)==13, str(len(cl)))
    check('...including $F04814, the successful $10 TERMT of USER', 'F04814' in cl)
    src=open('fps3k_custom.asm').read()
    check('the CPRUN NOP fill writes $4E71', 'move.w   #$4e71, (a0)+' in src)
    check('...bounded by cmpi.l #$8 / ble  => EIGHT nops',
          'F047B8  0c 80 00 00 00 08' in src and 'F047BE  6f f2' in src)
    check('CPRUN gates on CHANNEL_SELECT==0 to pick START over STOP',
          'F0476A  0c 6d 00 00 02 04' in src)
    check("the CRTCB block is $F04614 (mislabelled TCBDefEntry_RDHC)",
          'F04776  41 f9 00 f0 46 14' in src)
_mode1_b14_ownership()

def _user_lifecycle_blocks():
    import os
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    L=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    N=lambda a:_rom[a-_B:a-_B+4]
    for nm,a in (('CRTCB',0xF04614),('START',0xF04630),
                 ('TERMT',0xF046A6),('GTSEG',0xF046C8)):
        check('the %s block names USER with session 0'%nm,
              N(a)==b'USER' and L(a+4)==0)
    check('CRTCB requests priority $6464',   L(0xF04614+0x10)==0x00006464)
    check('CRTCB requests attribute $0800 (bit 15 CLEAR = unprivileged)',
          (L(0xF04614+0x14)>>16)==0x0800)
    check('GTSEG names the segment UPGM',    N(0xF046C8+0x0C)==b'UPGM')
    check('GTSEG logical address is the staging buffer $10000',
          L(0xF046C8+0x10)==0x00010000)
    check('GTSEG length is $D000 = 53248',   L(0xF046C8+0x14)==0xD000)
    check('...which fits inside the staging buffer',
          0x10000+0xD000 <= 0x20000)
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_cp2.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    RW=lambda a:int.from_bytes(r[a:a+2],'big')
    RL=lambda a:int.from_bytes(r[a:a+4],'big')
    check('the ROM block predicts the runtime priority',
          RW(0x1DB00+0x24)==(L(0xF04614+0x10)&0xFFFF))
    check('the ROM block predicts the runtime attribute word',
          RW(0x1DB00+0x28)==(L(0xF04614+0x14)>>16))
    check('the GTSEG block predicts the runtime entry point',
          RL(0x1DB00+0x6C)==L(0xF046C8+0x10))
_user_lifecycle_blocks()

def _user_is_runnable():
    import os
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_cp2.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    L=lambda a:int.from_bytes(r[a:a+4],'big'); W=lambda a:int.from_bytes(r[a:a+2],'big')
    check('the READY list head is no longer empty', L(0x0C14)!=0, hex(L(0x0C14)))
    check('...and it is the USER TCB', L(0x0C14)==0x1DB00 and r[0x1DB10:0x1DB14]==b'USER')
    check('the ALL-tasks head is USER too (pushed most recently)', L(0x0C10)==0x1DB00)
    # walk all-tasks: exactly 7, terminating
    t=L(0x0C10); seen=[]
    while t and t not in seen and len(seen)<12:
        seen.append(t); t=L(t+0x04)
    check('the all-tasks list walks exactly 7 entries and terminates',
          len(seen)==7, str(len(seen)))
    check('all six TDTI tasks are still blocked (bit 14 or RDHC current)',
          all(W(a+0x2C)==0x4000 for a in seen if r[a+0x10:a+0x14] not in (b'USER',b'RDHC')))
    check('USER is NOT waiting -- bit 14 clear, bit 4 set',
          not (W(0x1DB00+0x2C)&0x4000) and (W(0x1DB00+0x2C)&0x0010))
    check('the NOP fill is present at the entry point USER would run',
          r[0x10000:0x10010]==b'\x4e\x71'*8)
_user_is_runnable()

def _rdhc_ack_suppression():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    check('op $7 skips the BIM re-arm', w(0xF0489E)==0x0C40 and w(0xF048A0)==0x0007
          and (w(0xF048A2)>>8)==0x67)
    check('the BIM re-arm writes $5E to $FF0230',
          w(0xF048A4)==0x3B7C and w(0xF048A6)==0x005E and w(0xF048A8)==0x0230)
    check('MODE1 bit 7 (busy) suppresses the ack',
          w(0xF048AA)==0x322D and w(0xF048AC)==0x0202
          and w(0xF048AE)==0x0801 and w(0xF048B0)==0x0007
          and (w(0xF048B2)>>8)==0x66)
    check('op $F suppresses the ack',
          w(0xF048B4)==0x0C40 and w(0xF048B6)==0x000F and (w(0xF048B8)>>8)==0x67)
    check('op $8 acks ONLY when CHANNEL_SELECT == 1',
          w(0xF048BA)==0x0C40 and w(0xF048BC)==0x0008
          and w(0xF048C0)==0x0C6D and w(0xF048C2)==0x0001 and w(0xF048C4)==0x0204)
    check('the ack itself is bclr #10 on the latched MODE0 word',
          w(0xF048C8)==0x3239 and w(0xF048CE)==0x0881 and w(0xF048D0)==0x000A
          and w(0xF048D2)==0x3B41 and w(0xF048D4)==0x0200)
    # op $F RESUME chain
    for off,blk in ((0xF04856,0xF04696),(0xF04868,0xF0468E),
                    (0xF0487A,0xF04686),(0xF04886,0xF0467E)):
        check('the RESUME chain names block $%06X'%blk,
              w(off)==0x41F9 and (w(off+2)<<16|w(off+4))==blk)
    check("the bit-7 arm's $13 RESUME names USER's block $F0469E",
          w(0xF04906)==0x41F9 and (w(0xF04908)<<16|w(0xF0490A))==0xF0469E)
_rdhc_ack_suppression()

def _cprun_start_interlock():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check("op $8's ISR arm reads MODE1 ($202) first",
          w(0xF04F52)==0x3028 and w(0xF04F54)==0x0202)
    check('...and tests bit 14',  w(0xF04F56)==0x0800 and w(0xF04F58)==0x000E)
    check('bit 14 CLEAR branches PAST $258 to the range check',
          (w(0xF04F5A)>>8)==0x67)
    check('the second condition is CHANNEL_SELECT == 0',
          w(0xF04F5C)==0x0C68 and w(0xF04F5E)==0x0000 and w(0xF04F60)==0x0204)
    check('...and non-zero ALSO branches past $258 (so STOP is never refused)',
          (w(0xF04F62)>>8)==0x66)
    check('$258 is emitted only when BOTH hold', w(0xF04F64)==0x303C and w(0xF04F66)==0x0258)
    check('the range check is on $0E7E, low bound $10000',
          w(0xF04F70)==0x0CB9 and l(0xF04F72)==0x00010000 and w(0xF04F78)==0x0E7E)
    check('...high bound $1FFFF',
          w(0xF04F7C)==0x0CB9 and l(0xF04F7E)==0x0001FFFF and w(0xF04F84)==0x0E7E)
    check('failure reports $25A', w(0xF04F88)==0x303C and w(0xF04F8A)==0x025A)
    check('success clears $0E74 -- the main loop\'s own precondition',
          w(0xF04F94)==0x33FC and w(0xF04F96)==0x0000 and w(0xF04F9A)==0x0E74)
    check("the main loop's guard is $0E74 != $25A",
          w(0xF0475E)==0x0C79 and w(0xF04760)==0x025A and w(0xF04764)==0x0E74)
_cprun_start_interlock()

def _disabled_isr_edges():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    hits={}
    for a in range(0xF00000,0xF0FFFC,2):
        w=int.from_bytes(_rom[a-_B:a-_B+2],'big')
        if (w>>12)!=6: continue
        cond=(w>>8)&0xF
        if cond<2 or (w&0xFF)!=0x04: continue
        w2=int.from_bytes(_rom[a-_B+2:a-_B+4],'big')
        if (w2>>12)==6 and ((w2>>8)&0xF)==cond and (w2&0xFF)==0:
            hits[a]=a+4+int.from_bytes(_rom[a-_B+4:a-_B+6],'big')
    check('the disabled-edge idiom occurs exactly 6 times', len(hits)==6, str(len(hits)))
    ISR={0xF04930:'RDHC',0xF05DD6:'IO1I',0xF060CE:'XP4I',
         0xF06AE6:'XP3I',0xF074E6:'XP2I',0xF07EE6:'XP1I'}
    check('...and every target is one of the six ISR entry points',
          sorted(hits.values())==sorted(ISR), str(sorted(hex(v) for v in hits.values())))
    check('...covering all six tasks with no duplicates', len(set(hits.values()))==6)
    for site,tgt in ((0xF04736,0xF04930),(0xF05DAC,0xF05DD6),(0xF0600C,0xF060CE),
                     (0xF06A06,0xF06AE6),(0xF07406,0xF074E6),(0xF07E06,0xF07EE6)):
        check('$%06X disables the edge to %s at $%06X'%(site,ISR[tgt],tgt),
              hits.get(site)==tgt)
    check('the two branches carry the SAME condition code',
          all((int.from_bytes(_rom[a-_B:a-_B+2],'big')>>8&0xF)
              ==(int.from_bytes(_rom[a-_B+2:a-_B+4],'big')>>8&0xF) for a in hits))
_disabled_isr_edges()

def _disabled_diagnostics_firmware_wide():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    sw=lambda v: v-0x10000 if v&0x8000 else v
    sb=lambda v: v-0x100 if v&0x80 else v
    def callers(tgt):
        out=[]
        for a in range(0xF00000,0xF0FFFE,2):
            o=w(a)
            if (o&0xFF00)==0x6100:
                d=o&0xFF
                if (a+2+(sw(w(a+2)) if d==0 else sb(d)))==tgt: out.append(a)
            elif o==0x4EB9 and ((w(a+2)<<16)|w(a+4))==tgt: out.append(a)
        return out
    def branch_targets_to(t):
        out=[]
        for a in range(0xF00000,0xF0FFFE,2):
            o=w(a)
            if (o&0xF000)!=0x6000: continue
            d=o&0xFF
            if (a+2+(sw(w(a+2)) if d==0 else sb(d)))==t and a!=t-2: out.append(a)
        return out
    k=callers(0xF00186); f=callers(0xF0A306)
    check('$F00186 has 23 static call sites (22 bsr + the vector-table jsr)',
          len(k)==23, str(len(k)))
    check('$F0A306 has 16 static call sites', len(f)==16, str(len(f)))
    skip=lambda cs:[a for a in cs if (w(a-2)&0xFF00)==0x6000 and (w(a-2)&0xFF)==0x04]
    ks,fs=skip(k),skip(f)
    check('6 kernel snapshot calls are jumped over', len(ks)==6, str(len(ks)))
    check('10 FPS snapshot calls are jumped over', len(fs)==10, str(len(fs)))
    kd=[a for a in ks if not branch_targets_to(a)]
    fd=[a for a in fs if not branch_targets_to(a)]
    check('...of the kernel six, FIVE are dead ($F002C2 is reachable from $F002AA)',
          len(kd)==5 and 0xF002C2 not in kd, str([hex(x) for x in kd]))
    check('...and all ten FPS ones are dead', len(fd)==10)
    check('so 15 diagnostic-snapshot calls are disabled firmware-wide',
          len(kd)+len(fd)==15)
    check('the five dead kernel sites are the expected addresses',
          sorted(kd)==[0xF01AFE,0xF01B56,0xF01BDE,0xF01D64,0xF02428])
    check('the self-test site $F09A0A is NOT disabled -- it is branched to',
          bool(branch_targets_to(0xF09A0A)))
_disabled_diagnostics_firmware_wide()

def _e7e_closed():
    rom=open('FPS3K_U11_U12_JOIN.bin','rb').read()
    al=[i for i in range(0,len(rom)-3,2) if rom[i:i+4]==b'\x00\x00\x0e\x7e']
    check('$0E7E has exactly 4 absolute-long references', len(al)==4, str(len(al)))
    check('...at the two parsers and the two op-$8 bounds',
          [0xF00000+x for x in al]==[0xF04F76,0xF04F82,0xF052D8,0xF05648])
    al4=[i for i in range(0,len(rom)-3,2) if rom[i:i+4]==b'\x00\x00\x0e\x74']
    check('CONTROL: the same detector finds $0E74 37 times, as documented',
          len(al4)==37, str(len(al4)))
    w=lambda a:int.from_bytes(rom[a-0xF00000:a-0xF00000+2],'big')
    check('both writers are move.l a1,$0E7E', w(0xF052D6)==0x23C9 and w(0xF05646)==0x23C9)
    check('the only two writers lie in the S-record parsers, not in any op handler',
          all(0xF05000 < 0xF00000+x < 0xF05700 for x in al[2:]))
_e7e_closed()

def _op3_two_pass():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('op $3 saves MODE2 on entry', w(0xF04D4E)==0x3F28 and w(0xF04D50)==0x0210)
    check('bit 5 selects direction', w(0xF04D52)==0x0839 and w(0xF04D54)==0x0005)
    check('bit 6 selects the half',  w(0xF04D5E)==0x0839 and w(0xF04D60)==0x0006)
    check('the page is $0E58 >> 20 (moveq #$14 / lsr.l)',
          w(0xF04D70)==0x7414 and w(0xF04D72)==0xE4A9)
    check('...written to MODE2 with move.w -- so up to 12 bits reach it',
          w(0xF04D74)==0x3141 and w(0xF04D76)==0x0210)
    check('the offset is ($0E58 & $FFFFF) << 2',
          w(0xF04D7E)==0x0281 and l(0xF04D80)==0x000FFFFF and w(0xF04D84)==0xE589)
    check('($FFFFF << 2) maxes at $3FFFFC, below the $400000 guard',
          (0xFFFFF<<2)==0x3FFFFC and 0x3FFFFC < 0x400000)
    check('the read low-half arm returns $0E72 with NO memory access',
          w(0xF04DB2)==0x33F9 and l(0xF04DB4)==0x00000E72)
    check('the write high-half arm only latches $0E70',
          w(0xF04DCA)==0x33E8 and w(0xF04DCC)==0x0204 and l(0xF04DCE)==0x00000E70)
    check('the write low-half arm latches $0E72 and then pages+stores',
          w(0xF04DD6)==0x33E8 and l(0xF04DDA)==0x00000E72
          and w(0xF04DE6)==0xE4A9 and w(0xF04DE8)==0x3141)
    check('MODE2 is restored at the common exit', w(0xF04E22)==0x315F and w(0xF04E24)==0x0210)
    check('the auto-increment is AFTER that common exit -- so it fires on BOTH passes',
          w(0xF04E26)==0x0839 and w(0xF04E28)==0x0004
          and w(0xF04E30)==0x52B9 and l(0xF04E32)==0x00000E58)
    check('op $3 increments by 1 (a LONGWORD index)', w(0xF04E30)==0x52B9)
_op3_two_pass()

def _isr_edges_are_real_boundaries():
    L=open('fps3k_custom.asm').read().split('\n')
    starts={l[:6] for l in L if len(l)>6 and l[:2]=='F0' and l[6:7]==' '}
    for a in ('F04736','F05DAC','F0600C','F06A06','F07406','F07E06'):
        check('$%s is a confirmed instruction boundary'%a, a in starts)
    K=open('fps3k_kernel.asm').read().split('\n')
    kstarts={l[:6] for l in K if len(l)>6 and l[:2]=='F0' and l[6:7]==' '}
    for a in ('F00C34','F03068'):
        check('$%s is NOT a boundary -- the generalised sweep candidate is spurious'%a,
              a not in kstarts)
_isr_edges_are_real_boundaries()

def _write_only_globals_are_five():
    rom=open('FPS3K_U11_U12_JOIN.bin','rb').read()
    def refs(v):
        return [0xF00000+i for i in range(0,len(rom)-3,2)
                if rom[i:i+4]==(v).to_bytes(4,'big')]
    for g,n in ((0x0E4C,1),(0x0E7C,1),(0x0E8A,1),(0x10A8,2),(0x0E6E,8)):
        check('$%04X has %d absolute-long reference(s)'%(g,n), len(refs(g))==n,
              str(len(refs(g))))
    check('CONTROL: $0E74 still gives 37', len(refs(0x0E74))==37)
    w=lambda a:int.from_bytes(rom[a-0xF00000:a-0xF00000+2],'big')
    iss=[0xF04500,0xF05688,0xF05E56,0xF068A8,0xF072C0,0xF07CC0,0xF086C0,0xF0A57E]
    check('all eight $0E6E sites are move.w d0,$0E6E', all(w(a)==0x33C0 for a in iss))
    check("...and they ARE the eight panel-command issuers",
          [x-2 for x in refs(0x0E6E)]==iss)
    check('so the write-only set is five, not four',
          sum(1 for g in (0x0E4C,0x0E7C,0x0E8A,0x10A8,0x0E6E) if refs(g))==5)
_write_only_globals_are_five()

def _gtseg_crtcb_layouts_differ():
    import os
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    L=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('GTSEG +$0C is the segment NAME', _rom[0xF046C8+0x0C-_B:0xF046C8+0x10-_B]==b'UPGM')
    check('CRTCB +$0C is zero -- not a name', L(0xF04614+0x0C)==0)
    check('GTSEG +$10/+$14 are address/length', L(0xF046C8+0x10)==0x10000
          and L(0xF046C8+0x14)==0xD000)
    check('CRTCB +$10/+$14 are priority/attribute -- a DIFFERENT layout',
          L(0xF04614+0x10)==0x6464 and (L(0xF04614+0x14)>>16)==0x0800)
    check('the two blocks differ at +$0C, +$10 and +$14',
          all(L(0xF046C8+o)!=L(0xF04614+o) for o in (0x0C,0x10,0x14)))
    SP='/tmp/claude-1000/-home-fletto-ext-src-claude-fps3000/14b5ff05-70eb-4e88-b2ba-dd12825bd185/scratchpad/'
    f=SP+'ram_cp2.bin'
    if not os.path.exists(f): return
    r=open(f,'rb').read()
    RW=lambda a:int.from_bytes(r[a:a+2],'big')
    check('CRTCB +$10 is priority: it equals the runtime TCB+$24',
          RW(0x1DB00+0x24)==(L(0xF04614+0x10)&0xFFFF))
    check('CRTCB +$14 high word is the attribute: it equals TCB+$28',
          RW(0x1DB00+0x28)==(L(0xF04614+0x14)>>16))
_gtseg_crtcb_layouts_differ()

def _op4_is_channel_register_access():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('op $4 range-checks $0E60 against $105E',
          w(0xF04E3A)==0x2239 and l(0xF04E3C)==0x00000E60 and w(0xF04E46)==0xB279)
    check('...rejecting with panel $25C', w(0xF04E4E)==0x303C and w(0xF04E50)==0x025C)
    check('it then computes the window base as (ch+1) << 5',
          w(0xF04E5C)==0x5241 and w(0xF04E5E)==0xEB49)
    check('$0E58 == 0 selects +$0E (command/status)',
          w(0xF04E60)==0x0CB9 and l(0xF04E62)==0 and w(0xF04E6C)==0x0641 and w(0xF04E6E)==0x000E)
    check('$0E58 == 1 with $0E87 bit 6 SET selects +$08 (data high)',
          w(0xF04E72)==0x0CB9 and l(0xF04E74)==1
          and w(0xF04E7E)==0x0839 and w(0xF04E80)==0x0006 and w(0xF04E88)==0x5041)
    check('...bit 6 CLEAR selects +$0A (data low)',
          w(0xF04E8C)==0x0641 and w(0xF04E8E)==0x000A)
    check('otherwise selects +$04 (write-once)', w(0xF04E92)==0x5841)
    check('so the selector enumerates exactly the four documented window registers',
          sorted([0x0E,0x08,0x0A,0x04])==[0x04,0x08,0x0A,0x0E])
    check('the address is $FF0000 + base', w(0xF04E94)==0x2241 and w(0xF04E96)==0xD3FC
          and l(0xF04E98)==0x00FF0000)
    check('op $4 falls into $F04EA0, the SAME routine op $6 uses',
          w(0xF04EA0)==0x3028 and w(0xF04EA2)==0x0216)
    check('...which brackets $FF0216 bit 7 and restores the original word',
          w(0xF04EA6)==0x0880 and w(0xF04EA8)==0x0007
          and w(0xF04EDC)==0x3141 and w(0xF04EDE)==0x0216)
    check('op $6 reaches the same routine', w(0xF04F30)==0x2279 and l(0xF04F32)==0x00000E58)
    check('the shared increment is addq.l #$2', w(0xF04ED6)==0x54B9)
_op4_is_channel_register_access()

def _op5_boundary_differs_from_op4():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('op $4 rejects 0 with BLE ($6F)', (w(0xF04E44)>>8)==0x6F)
    check('op $5 accepts 0 -- it uses BLT ($6D)', (w(0xF04EEC)>>8)==0x6D)
    check('both compare against the literal #$0',
          w(0xF04E40)==0x0C41 and w(0xF04E42)==0 and
          w(0xF04EE8)==0x0C40 and w(0xF04EEA)==0)
    check('both reject with panel $25C',
          w(0xF04E4E)==0x303C and w(0xF04E50)==0x025C and
          w(0xF04EF6)==0x303C and w(0xF04EF8)==0x025C)
    check('op $5 argument 0 returns $105E, the channel-present count',
          w(0xF04F04)==0x0C40 and w(0xF04F06)==0 and
          w(0xF04F0A)==0x33F9 and l(0xF04F0C)==0x0000105E and l(0xF04F10)==0x00000E74)
    check('op $5 argument n stores into $0E60/$0E62',
          w(0xF04F16)==0x4279 and l(0xF04F18)==0x00000E60 and
          w(0xF04F1C)==0x33E8 and l(0xF04F20)==0x00000E62)
_op5_boundary_differs_from_op4()

def _short_ops_decoded():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    # op $7: bclr #4 on $FF0230 (MC68153 IRE)
    check('op $7 clears bit 4 (IRE) of BIM0 CR $FF0230',
          w(0xF04F3A)==0x3228 and w(0xF04F3C)==0x0230
          and w(0xF04F3E)==0x0881 and w(0xF04F40)==0x0004
          and w(0xF04F42)==0x3141 and w(0xF04F44)==0x0230)
    # op $9: no bit-6 half select
    check('op $9 clears $0E68 and sets $0E6A from CHANNEL_SELECT',
          w(0xF04FA0)==0x4279 and l(0xF04FA2)==0x00000E68
          and w(0xF04FA6)==0x33E8 and w(0xF04FA8)==0x0204 and l(0xF04FAA)==0x00000E6A)
    check('op $9 has NO $0E87 bit-6 test -- the third parameter is 16-bit',
          not any(w(a)==0x0839 and w(a+2)==0x0006
                  for a in range(0xF04FA0,0xF04FBA,2)))
    check('CONTROL: op $B DOES test bit 6', w(0xF0500E)==0x0839 and w(0xF05010)==0x0006)
    # op $B
    check('op $B computes $10000 + $10',
          w(0xF05002)==0x203C and l(0xF05004)==0x00010000
          and w(0xF05008)==0x0680 and l(0xF0500A)==0x00000010)
    check('...and swaps for the high half when bit 6 is set', w(0xF05020)==0x4840)
    # op $E: both directions
    check('op $E branches on CHANNEL_SELECT == 0',
          w(0xF050CA)==0x0C68 and w(0xF050CC)==0x0000 and w(0xF050CE)==0x0204)
    check('...zero CLEARS MODE1 bit 7',
          w(0xF050D6)==0x0881 and w(0xF050D8)==0x0007 and w(0xF050DA)==0x3141)
    check('...non-zero SETS it -- so XPRUN is run/halt, not clear-only',
          w(0xF050E4)==0x08C1 and w(0xF050E6)==0x0007 and w(0xF050E8)==0x3141)
_short_ops_decoded()

