def _unbounded_wait_risk_ranking():
    import subprocess,re,collections,os
    if not os.path.exists('tools/find_unbounded_waits.py'): return
    out=subprocess.run(['python3','tools/find_unbounded_waits.py'],
                       capture_output=True,text=True,timeout=600).stdout
    m=re.search(r'total:\s*(\d+)',out)
    check('the unbounded-wait census still totals 71', m and m.group(1)=='71',
          m.group(1) if m else 'no total')
    c=collections.Counter()
    for l in out.split('\n'):
        if not re.match(r'\s+\$F0[0-9A-F]{4}\s+\S+\s+->',l): continue
        r=re.findall(r'\$([0-9a-f]+)\((a[0-9])\)',l)
        if r: c[r[0][0]]+=1
    check('$FF0218 is polled unboundedly at 20 sites (a4 + a5 bases)',
          c.get('218',0)==20, str(c.get('218')))
    check('$FF0004 at 16 sites', c.get('4',0)==16, str(c.get('4')))
    check('those two bits account for 36 of the 71',
          c.get('218',0)+c.get('4',0)==36)
    check('$FF0216 (self-test only) at 8', c.get('216',0)==8, str(c.get('216')))
_unbounded_wait_risk_ranking()

def _dispatch_table_stack_contract():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    sw=lambda v: v-0x10000 if v&0x8000 else v
    sb=lambda v: v-0x100 if v&0x80 else v
    check('the primitive pushes d4 at entry (move.w d4,-(a7) == $3F04)',
          w(0xF056BE)==0x3F04)
    check('the ERROR path pops it before rts',
          w(0xF05712)==0x381F and w(0xF0572A)==0x4E75)
    check('the SUCCESS path jmps into the table with NO pop',
          w(0xF05702)>>8==0x67 and w(0xF0572C)==0xE548
          and w(0xF05734)==0x4EF4
          and not any(w(a)==0x381F for a in range(0xF0572C,0xF05738,2)))
    for nm,t,hi in (('D2_FIN',0xF05738,0xF057F8),('D1_SEND',0xF058B2,0xF05940),
                    ('POLL',0xF05A12,0xF05B00),('BLK_XFR',0xF05B0E,0xF05BA0)):
        check('%s pops d4 itself'%nm, any(w(a)==0x381F for a in range(t,hi,2)))
    # the 42 slots
    base=0xF05BA4; noop=0; jmps={}
    for i in range(42):
        a=base+i*4
        if w(a)==0x4EFA: jmps[a+2+sw(w(a+2))]=jmps.get(a+2+sw(w(a+2)),0)+1
        elif w(a)==0x4E75 and w(a+2)==0x4E71: noop+=1
    check('13 slots are rts/nop', noop==13, str(noop))
    check('the other 29 are jmps to exactly four handlers', len(jmps)==4, str(len(jmps)))
    check('...with the documented multiplicities 10/9/9/1',
          sorted(jmps.values(),reverse=True)==[10,9,9,1])
    check('a rts/nop slot does NOT pop d4 -- so it returns to a fabricated address',
          w(base)==0x4E75 or all(w(base+i*4)!=0x381F for i in range(42)))
    # entry convention: jsr only
    jsr=sum(1 for a in range(0xF00000,0xF0FFFA,2)
            if w(a)==0x4EB9 and ((w(a+2)<<16)|w(a+4)) in (0xF056BA,0xF07F12))
    bsr=sum(1 for a in range(0xF00000,0xF0FFFA,2)
            if (w(a)&0xFF00)==0x6100 and
               (a+2+(sw(w(a+2)) if (w(a)&0xFF)==0 else sb(w(a)&0xFF))) in (0xF056BA,0xF07F12))
    check('the primitive is entered by jsr only (5 sites, zero bsr)', jsr==5 and bsr==0,
          'jsr=%d bsr=%d'%(jsr,bsr))
_dispatch_table_stack_contract()

def _noop_slots_reachable():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    base=0xF05BA4
    noop=[i for i in range(42)
          if w(base+i*4)==0x4E75 and w(base+i*4+2)==0x4E71]
    check('the no-op indices are the documented thirteen',
          noop==[0x00,0x0B,0x0C,0x11,0x12,0x13,0x15,0x20,0x21,0x26,0x27,0x28,0x29],
          str([hex(x) for x in noop]))
    reach=[i for i in noop if 1<=i<=0x10]
    check('$0B and $0C are inside the chassis-nameable range $01-$10',
          reach==[0x0B,0x0C], str(reach))
    check('op $0 takes the AC code from $0E5C, so the chassis names it',
          w(0xF04CE8)==0x4EB9)
    # base B is +21 slots
    bB=[i-21 for i in noop if i>=21]
    check('read from base B the no-op indices include $14',
          0x14 in bB, str([hex(x) for x in bB]))
    check('...while base A index $14 is D2_FIN, a real handler',
          w(base+0x14*4)==0x4EFA)
    check('the two bases are 84 bytes / 21 slots apart', (0xF05BF8-0xF05BA4)==84)
_noop_slots_reachable()

def _rdhc_cmd3_unbounded():
    _rom=open('FPS3K_U11_U12_JOIN.bin','rb').read(); _B=0xF00000
    w=lambda a:int.from_bytes(_rom[a-_B:a-_B+2],'big')
    l=lambda a:int.from_bytes(_rom[a-_B:a-_B+4],'big')
    check('cmd 3 takes the count from the command record', w(0xF054E8)==0x2418)
    check('...and points a2 at $0E8A', w(0xF054EA)==0x45F9 and l(0xF054EC)==0x00000E8A)
    check('the copy is move.l (a0)+,(a2)+', w(0xF054F4)==0x24D8)
    check('the loop bound is the record count, cmp.l d2,d1 / ble',
          w(0xF054F8)==0xB282 and (w(0xF054FA)>>8)==0x6F)
    check('cmd 3 contains NO cmpi against a limit',
          not any(w(a) in (0x0C81,0x0CB9,0x0C79,0x0C41,0x0C40)
                  for a in range(0xF054E8,0xF054FC,2)))
