# ---------------------------------------------------------------------------
# SCHEMATIC SHEETS 1, 4 and 6, and THE RIBBON PIPELINE (2026-08-06).
#
# The pin verifications here are MEASURED, not asserted: each one re-derives the
# claim by parsing apif_4448_connection_list.md -- transcribed months earlier
# from a different document -- rather than grepping the prose that reports it.
# That is the point of the cross-check, and on sheet 4 it earned its keep: I
# read INTR* at A-33, the list gave SP+DP14*, and the list has it at A-39.
# ---------------------------------------------------------------------------
def _APIF_SHEETS_146_AND_PIPELINE_2026_08_06():
    import re as _q6re

    def _q6flat(t):
        """collapse whitespace and drop markdown emphasis, so an anchor does
        not depend on where a line happens to wrap.  Defined LOCALLY: the
        suite's own _flat lives inside another check function, and assuming it
        was module-level is what the smoke test caught here."""
        return _q6re.sub(r'\s+', ' ', t.replace('**', '').replace('*', ''))

    _q6cl = open('refs_extracted/apif_4448_connection_list.md').read()
    _q6p = dict(_q6re.findall(r'\| ([AB]\d+) \| ([A-Z0-9*+!.]+)', _q6cl))
    _q6bus = open('refs_extracted/apif_host_bus_pinout.md').read()
    _q6hsk = open('refs_extracted/apif_handshake_interrupt.md').read()
    _q6clk = open('refs_extracted/apif_register_clocks.md').read()
    _q6fs = open('refs_extracted/apif_format_sequencer.md').read()
    _q6cm = _CLAUDE()

    # ---- sheet 1: the 32-bit host bus, RE-DERIVED ---------------------------
    _q6hd = ('A74', 'A76', 'A78', 'A80', 'B24', 'B26', 'B28', 'B30',
             'B36', 'B38', 'B40', 'B42', 'B58', 'B60', 'B62', 'B64')
    _q6hs = ('A61', 'A63', 'A67', 'A69', 'B9', 'B11', 'B15', 'B17',
             'B47', 'B49', 'B53', 'B55', 'B87', 'B89', 'B93', 'B95')
    _q6a = sum(1 for _i, _x in enumerate(_q6hd)
               if _q6p.get(_x) == 'HD%02d' % _i)
    check('MEASURED: sheet 1 HD00-HD15 -- 16 of 16 pins agree with the list, '
          'signal name AND bit index', _q6a == 16, '%d of 16' % _q6a)
    _q6b = sum(1 for _i, _x in enumerate(_q6hs)
               if _q6p.get(_x) == 'HST%02d' % _i)
    check('...and HST00-HST15 likewise -- so 32 of 32 across the two buses',
          _q6b == 16, '%d of 16' % _q6b)
    check('...and all 32 pins are the ones the write-up records',
          all(_x[0] + '-' + _x[1:] in _q6bus for _x in _q6hd + _q6hs))
    # the buffer asymmetry is the finding, not the width
    check('sheet 1: HD is a 74LS245 TRANSCEIVER and HST a 74LS244 BUFFER, so '
          'they are NOT symmetric halves of one 32-bit path',
          '74LS245' in _q6bus and '74LS244' in _q6bus
          and 'not symmetric halves' in _q6flat(_q6bus).lower())
    check('...and the Thevenin values give the impedances recorded',
          '235' in _q6bus and '213' in _q6bus and '470' in _q6bus
          and '390' in _q6bus)

    # ---- sheet 8's byte clocks, the same way -------------------------------
    _q6bc = {'A36': 'B0CLK', 'B32': 'B1CLK', 'A45': 'B2CLK', 'B33': 'B3CLK'}
    _q6c = sum(1 for _k, _v in _q6bc.items() if _q6p.get(_k) == _v)
    check('MEASURED: sheet 8 exports FOUR byte clocks, all four confirmed by '
          'the list -- so the AP I/F clocks the host adaptor', _q6c == 4,
          '%d of 4' % _q6c)

    # ---- sheet 4: the handshake and the interrupt, RE-DERIVED --------------
    _q6h = {'A77': 'DACKR', 'A75': 'DACK', 'A73': 'DAVALR', 'A71': 'DAVAL',
            'A44': 'INTPIN', 'A39': 'INTR*', 'A92': 'INTPOUT', 'A93': 'RUN*',
            'B7': 'APDMAACT', 'B8': 'APDMAACTR', 'B20': 'RUNIND',
            'B34': 'HALTINT*', 'B35': 'CHALTINT*', 'B37': 'WCFQ0*',
            'B50': 'CTL5INT*', 'B51': 'CCT5INT*', 'B76': 'INT06*',
            'B78': 'INT07*'}
    _q6d = sum(1 for _k, _v in _q6h.items() if _q6p.get(_k) == _v)
    check('MEASURED: sheet 4 -- 18 of 18 named connector pins agree with the '
          'list', _q6d == len(_q6h), '%d of %d' % (_q6d, len(_q6h)))
    check('...and INTEN at A-40 is the nineteenth, the list OCRing it INTFN',
          _q6p.get('A40') == 'INTFN' and 'INTFN' in _q6hsk)
    check('...so 55 pin agreements across sheets 1, 4 and 8, and the write-up '
          'says so', '55' in _q6hsk and '55' in _q6cm)
    # the correction is recorded as MINE, not as a fault of the drawing
    check('the A-33/A-39 misread is recorded as the READER corrected by the '
          'check, not the sheet',
          'A-33' in _q6hsk and '3-for-9' in _q6hsk)

    # DACK/DAVAL are two MORE differential pairs -> eight, not six
    check('DACK/R and DAVAL/R take the differential pair count from six to '
          'EIGHT', 'make **eight**' in _q6hsk or 'eight' in _q6flat(_q6hsk))
    check('...received by an MC3486, with a 300 ohm termination across each '
          'pair and a 1K/1K failsafe bias',
          'MC3486' in _q6hsk and '300' in _q6hsk and '1K' in _q6hsk)
    # and the refinement: a 3487 channel need not be a differential pair
    check('THE REFINEMENT: H16 MC3487 drives ONE true pair and THREE '
          'single-ended lines, so the 8-channel figure over-counts the '
          'DIFFERENTIAL capability',
          'over-count' in _q6flat(_q6hsk).lower()
          and 'HALTINT' in _q6hsk and 'single-ended' in _q6hsk)
    check('...and both MC3487s on the board are on this sheet, matching the '
          'photograph count of two',
          _q6flat('G6') in _q6flat(_q6hsk) and 'H16' in _q6hsk)

    # the interrupt daisy chain
    check('INTPIN in + INTPOUT out is recorded as an interrupt PRIORITY DAISY '
          'CHAIN', 'daisy chain' in _q6flat(_q6hsk).lower())
    check('...and as a SEPARATE interrupt domain the firmware cannot see',
          'MC68153' in _q6hsk and 'cannot' in _q6flat(_q6hsk).lower())

    # ---- sheet 6: the register clocks and the HMA finding ------------------
    check('MEASURED: sheet 6 CTLCLK at A-50 agrees with the list -- the '
          'twentieth pin confirmed', _q6p.get('A50') == 'CTLCLK'
          and 'A-50' in _q6clk)
    check('sheet 6 READ goes to sheet 1, which is the bus-turnaround chain '
          'sheet 1 depends on', 'READ' in _q6clk and 'turnaround' in _q6clk)
    check('THE FINDING: LDHMAL/LDHMAH name an HMA = HOST MEMORY ADDRESS '
          'register on sheet 17, loaded in two halves',
          'LDHMAL' in _q6clk and 'LDHMAH' in _q6clk
          and 'HMA REG' in _q6clk)
    check('...so the card has an address generator on EACH side -- APMA on the '
          'AP side, HMA on the host side, one shared word count',
          'APMA' in _q6clk and 'two-sided' in _q6flat(_q6clk).lower())
    # sheet 6 left the HMA width open; sheet 17 was read straight afterwards and
    # SETTLED it at 32 bits (four 74LS374).  This check moved with the finding --
    # it used to assert 'not established', which was correct only until sheet 17.
    check('...and the WIDTH of HMA, left open by sheet 6, is SETTLED at 32 bits '
          'by sheet 17 -- and sheet 6 says so, so the two documents agree',
          '32 bits' in _q6clk and 'SETTLED' in _q6clk
          and 'apif_hma_register.md' in _q6clk)
    check('the DMA direction is a complementary pair, and the FIFO sheet wants '
          'the OPPOSITE polarity from the bus buffers',
          '74LS240' in _q6clk and 'polarity' in _q6clk)
    check('DMA2AP* fans out to sheets 1, 2 and 3 -- confirming the three-sheet '
          'host bus from the BALLOON list rather than from titles',
          'DMA2AP' in _q6clk and '1, 2, 3' in _q6clk)

    # ---- the crop-coverage error, recorded as a rule -----------------------
    check('MY CROP-COVERAGE ERROR is recorded: two 1700px crops cover 48% of a '
          '3509px sheet, and I concluded an absence from half a sheet',
          '48%' in _q6clk and '3509' in _q6clk)
    check('...with the reusable guard -- the title block is always '
          'bottom-right, so a crop set that never reaches it has not covered '
          'the sheet', 'title block' in _q6flat(_q6clk).lower()
          and 'bottom-right' in _q6clk)

    # ---- SHEET 20 IS NOT MISSING ------------------------------------------
    check('the sheet index no longer says sheets 19 AND 20 are absent',
          'GE_RDCP_wo_764' in _q6fs and 'SHEET 20' in _q6fs)
    check('...and sheet 20 is identified as the separately-supplied PNG, which '
          'is the BEST-READ document in the set',
          'BLOCK' in _q6fs.upper() and 'PNG' in _q6fs)
    check('...so only sheet 19 is genuinely missing',
          'only sheet 19' in _q6flat(_q6fs).lower()
          or 'Only sheet 19' in _q6fs)
    check('MEASURED: the PNG exists on disk at the size recorded',
          os.path.getsize('refs/FPS-3000/schematics/'
                          'GE_RDCP_wo_764_schematic_1of2_1983-001_Page169.png')
          > 1000000)
    # the label is drawn across three lines in the sheet and quoted that way in
    # the file, so this anchor MUST be normalised -- matching the raw string is
    # what failed in the smoke test
    check('and the block diagram labels HSTBUS TO HOST ADAPTER -- FPS own '
          'drawing confirming the host-agnostic reading',
          'TO HOST ADAPTER' in
          _q6flat(open('refs_extracted/apif_mp32_bus.md').read()))

    # ---- THE RIBBON PIPELINE, run rather than asserted ---------------------
    sys.path.insert(0, 'tools')
    import importlib
    _q6xp = importlib.import_module('xp32_sim')
    check('the pipeline parameters are present with LATENCY 2 and DEPTH 4',
          _q6xp.Peer.LATENCY == 2 and _q6xp.Peer.DEPTH == 4)
    _q6src = open('tools/xp32_sim.py').read()
    check('...and their DIFFERENT provenance is in the source: the latency '
          'MEASURED, the depth FROM THE PART',
          'MEASURED' in _q6src and 'FROM THE PART, NOT THE STORE' in _q6src)
    check('latency DEFAULTS to 0, so nothing pinned moves unless a caller asks '
          'for the pipeline', 'latency=0' in _q6src)

    _q6r0 = _q6xp.run(latency=0)
    _q6r2 = _q6xp.run(latency=_q6xp.Peer.LATENCY)
    _q6e0, _q6p0 = _q6r0[0], _q6r0[2]
    _q6e2, _q6p2 = _q6r2[0], _q6r2[2]
    # the three PREDICTED-unchanged rows.  All are driven by the microword
    # rather than by data, and the linear walk has no data-dependent branch.
    check('PREDICTED AND HELD: engaging the pipeline leaves the address '
          'emission count unchanged at 193',
          len(_q6e0.addr_emitted) == 193
          and len(_q6e2.addr_emitted) == 193,
          '%d vs %d' % (len(_q6e0.addr_emitted), len(_q6e2.addr_emitted)))
    check('...and the peer read and write counts unchanged',
          (_q6p0.reads, _q6p0.writes) == (_q6p2.reads, _q6p2.writes))
    check('...and the STATUS BLOCK IS STILL NEVER WRITTEN, at both latencies -- '
          'the model obligation holds',
          not _q6p0.status_writes and not _q6p2.status_writes)
    # what the pipeline DOES change
    check('MEASURED: at the measured latency the model has TWO transactions '
          'outstanding, reproducing the "more than one" the store shows',
          _q6p2.max_outstanding == 2 and _q6p0.max_outstanding == 0,
          'max outstanding %d' % _q6p2.max_outstanding)
    check('...and the depth of 4 is never exceeded at latency 2',
          _q6p2.overflowed == 0)
    # the NEGATIVE: the store bounds the latency from neither side
    _q6st = [_q6xp.run(latency=_l)[2].starved_reads for _l in range(9)]
    check('NEGATIVE, MEASURED: reads NEVER starve at any latency 0-8, because '
          '193 addresses against 104 reads keep the pipe permanently ahead -- '
          'so the store bounds the latency from neither side',
          _q6st == [0] * 9, 'starved counts %s' % _q6st)
    _q6ov = [_q6xp.run(latency=_l)[2].overflowed for _l in range(9)]
    check('...and overflow begins only at latency 7, so the part four levels '
          'are headroom for this microcode',
          _q6ov[6] == 0 and _q6ov[7] > 0, 'overflow %s' % _q6ov)
    _q6rl = open('refs_extracted/ribbon_latency_measured.md').read()
    check('the sweep and its structural negative are recorded, not just the '
          'implementation', 'Starvation NEVER occurs' in _q6rl
          or 'starved reads' in _q6flat(_q6rl).lower())

    # ---- the orientation layer --------------------------------------------
    for _q6f in ('apif_host_bus_pinout', 'apif_handshake_interrupt',
                 'apif_register_clocks'):
        check('CLAUDE.md cites %s.md' % _q6f, _q6f in _q6cm,
              'a finding only in refs_extracted/ does not reach a reader of '
              'CLAUDE.md -- the drift this project repeatedly has to catch')


_APIF_SHEETS_146_AND_PIPELINE_2026_08_06()


def _SHEET17_AND_TWO_MODEL_REFUTATIONS_2026_08_06():
    """Sheet 17 settles the HMA width; two documented model JOINS are refuted.

    All three files were written after the previous block was inserted, so they
    had no checks.  The two refutations are the substantive part: both are joins
    the record ASSERTED and one of them was implemented and executing in
    tools/xp32_sim.py, which is why the contradiction was findable at all.
    """
    import re as _s7re
    _s7 = lambda t: _s7re.sub(r'\s+', ' ', t.replace('**', '').replace('*', ''))
    rd = lambda p: open(p).read()

    # ---- sheet 17: HMA = 32 bits ------------------------------------------
    hma = rd('refs_extracted/apif_hma_register.md')
    check('sheet 17 settles the HMA width at 32 BITS',
          '32 BITS' in hma or '32 bits' in hma)
    for ref, half in (('F7', 'HMAH'), ('F25', 'HMAH'),
                      ('F8', 'HMAL'), ('F26', 'HMAL')):
        check('...from `%s` (%s), one of FOUR 74LS374 octal registers'
              % (ref, half), ref in hma and half in hma)
    check('...and 4 x 8 = 32 closes with NO fifth stage on the sheet',
          'no fifth stage' in _s7(hma).lower())
    check('...read from FULL COVERAGE of the sheet, not a sample -- the '
          'discipline sheet 6 cost me', 'full coverage' in _s7(hma).lower())
    # the two internal buses the sheet identifies
    check('sheet 17 identifies RGBS as the register WRITE bus and IFOBS as the '
          'READBACK bus, 16 bits each',
          'RGBS' in hma and 'IFOBS' in hma
          and 'READBACK' in hma.upper())
    check('...gated one half at a time by HMALOUT*/HMAHOUT* from sheet 7',
          'HMALOUT' in hma and 'HMAHOUT' in hma)
    check('...which settles RGBS (16-bit DATA) vs REGSEL (6-bit SELECT) in the '
          'connection list', 'REGSEL' in hma)
    # the two non-claims, both worth pinning so nobody over-reads the width
    check('sheet 17 does NOT claim the host was a 32-bit machine',
          'does not establish that the host was a 32-bit machine'
          in _s7(hma).lower())
    check('...nor that the host-side DMA reaches 4 GB',
          '4 GB' in hma or '4GB' in hma)
    # and the doc that left it open now agrees
    clk = rd('refs_extracted/apif_register_clocks.md')
    check('sheet 6, which left the width open, now records 32 bits and points '
          'at the file that settled it',
          '32 bits' in clk and 'apif_hma_register.md' in clk)

    # ---- REFUTATION 1: R31's six "discrete output lines" -------------------
    r31 = rd('refs_extracted/r31_discretes_refuted.md')
    check('the R31 discrete-output reading is WITHDRAWN',
          'WITHDRAWN' in r31)
    check('...and the datasheet Y-Bus column is what makes the question '
          'answerable at all: SETNR DOES drive the modified word onto Y',
          'Y_i <- RAM_i' in r31 and 'Y_n <- 1' in r31)
    check('...so the reading SURVIVES that test and fails the next',
          'survives the' in _s7(r31).lower())
    # the measurement: five lanes, eleven words, all idle
    check('THE REFUTATION: on all ELEVEN words every one of the FIVE control '
          'lanes is idle and the destination selector reads its idle encoding',
          'eleven for eleven' in _s7(r31).lower()
          and '7 = idle' in r31)
    check('...and T2 is the NEW lane -- the recorded version covered four and '
          'was written BEFORE T2 was dumped',
          'before T2 was dumped' in _s7(r31))
    for a in ('$32B', '$36A', '$3E5', '$46E', '$479', '$58E',
              '$6E2', '$6EA', '$6EC', '$744', '$745'):
        check('...word %s is in the table' % a, a in r31)
    check('...and the 74LS377 candidate fails too: nothing clocks it',
          '74LS377' in r31 and 'nothing clocks it' in _s7(r31).lower())
    check('the economical alternative is DEAD WRITES, which is this machine\'s '
          'most repeated pattern',
          'DEAD WRITES' in r31.upper() and '!CCB' in r31)
    check('...and it REFRAMES $0333 rather than damaging it: the peer field is '
          'the signal', '$0333' in r31 and 'reframes' in _s7(r31).lower())
    check('what SURVIVES is stated separately from what falls',
          'set 11 times and NEVER tested' in r31.replace('**', ''))
    check('...and the honest limit is stated: "no candidate mechanism", not '
          '"impossible"', 'not "impossible"' in _s7(r31)
          or 'not “impossible”' in _s7(r31))

    # ---- REFUTATION 2: the CT pin does not cross --------------------------
    ct = rd('refs_extracted/adr_ct_does_not_cross.md')
    check('the CT-crosses-the-ribbon join is REFUTED',
          'refuted' in ct.lower())
    check('...and it was a THREE-AGAINST-ONE contradiction INSIDE the project, '
          'with the simulator the odd one out',
          'three against one' in _s7(ct).lower()
          and 'it is not the simulator' in _s7(ct).lower())
    check('...the mechanism: ADR.CT is AMD\'s name from AMD\'s SINGLE-BOARD '
          'design', 'SINGLE-BOARD' in ct)
    check('...and FPS split the units, each with its OWN Am2910',
          'AM2910ADC' in ct and 'EXEC' in ct and 'ARITH' in ct)
    check('...with two SN74S251N beside EXEC\'s and NONE of that class near '
          'ARITH\'s in three regions swept',
          'SN74S251N' in ct and 'three regions swept' in _s7(ct))
    check('...so BOTH stages of the condition decode are on EXEC',
          'Both stages are on EXEC' in ct.replace('**', ''))
    check('THE FAILURE MODE is named and it is the THIRD instance',
          'THIRD instance' in ct and 'Am29501' in ct and 'Am29540' in ct)
    check('...and the RULE is stated so it generalises',
          'which FPS card each endpoint is on' in _s7(ct))
    check('what survives: the CT decode itself, only its DESTINATION was wrong',
          'Only its destination is' in ct.replace('**', ''))
    check('...and the conclusion it contradicted gets STRONGER',
          'gets stronger' in _s7(ct).lower())
    check('...with the honest escape stated: a fan-out is not forbidden',
          'fan-out' in ct)

    # ---- both refutations are APPLIED, not merely documented ---------------
    xp = rd('tools/xp32_sim.py')
