def _EU_PEER_TYPE_FIELD_AND_N2_BIT1_2026_08_07():
    """The EU's peer TYPE field in the pure-peer blocks, and N2 bit 1.
    refs_extracted/eu_peer_type_field_and_n2_bit1.md

    EVERY number is recomputed from proms/ here -- the file is only checked for
    recording the conclusion and its limits.  The three extraction controls
    (AS max/mean 1.49, bit1 66.9%, 1136 valid) are what license the rest: they
    reproduce figures the record measured independently."""
    import os, glob, random
    _n2p = 'refs_extracted/eu_peer_type_field_and_n2_bit1.md'
    if not os.path.isfile(_n2p) or not os.path.isdir('proms'):
        return
    _n2t = open(_n2p).read()
    _n2z = ' '.join(_n2t.replace('*', '').replace('`', '')
                        .replace('\n> ', '\n').replace('\n>', '\n').split())

    def _n2ld(_dev):
        _g = glob.glob('proms/EU_%s_*.txt' % _dev)
        if not _g:
            return None
        _b = bytearray(2048)
        for _ln in open(_g[0]):
            _ln = _ln.strip()
            if not _ln.startswith('S1'):
                continue
            _n = int(_ln[2:4], 16); _a = int(_ln[4:8], 16)
            _d = _ln[8:8 + (_n - 3) * 2]
            for _i in range(0, len(_d), 2):
                if _a + _i // 2 < 2048:
                    _b[_a + _i // 2] = int(_d[_i:_i + 2], 16)
        return bytes(_b)

    _n2N = _n2ld('N2'); _n2P = _n2ld('P2'); _n2L = _n2ld('L2'); _n2M = _n2ld('M2')
    if not all((_n2N, _n2P, _n2L, _n2M)):
        return

    _n2v = [_a for _a in range(2048) if not (_n2P[_a] >> 7) & 1]

    # ---- EXTRACTION CONTROLS: three figures the record measured independently
    check('EXTRACTION CONTROL: 1136 valid words (P2 bit 7 clear), the record\'s figure',
          len(_n2v) == 1136, 'n = %d' % len(_n2v))
    _n2as = [(_n2N[_a] >> 4) & 0xF for _a in _n2v]
    _n2mx = max(_n2as.count(_k) for _k in range(16)) / (len(_n2v) / 16.0)
    check('EXTRACTION CONTROL: N2[7:4] max/mean is 1.49, the record\'s figure',
          abs(_n2mx - 1.49) < 0.02, 'max/mean = %.2f' % _n2mx)
    _n2b1 = sum((_n2N[_a] >> 1) & 1 for _a in _n2v) / float(len(_n2v))
    check('EXTRACTION CONTROL: N2 bit 1 is set on 66.9% of valid words, '
          'the record\'s figure for the bit it leaves unattributed',
          abs(_n2b1 - 0.669) < 0.003, '%.1f%%' % (100 * _n2b1))
    _n2m1 = sum(1 for _a in _n2v
                if (((_n2N[_a] >> 3) & 1) << 2 | ((_n2N[_a] >> 2) & 1) << 1 | (_n2N[_a] & 1)) == 1)
    check('...and mode 1 covers 88% of valid words, which is the record\'s ~1005 of ~1136',
          0.87 <= _n2m1 / float(len(_n2v)) <= 0.89, '%.1f%%' % (100.0 * _n2m1 / len(_n2v)))

    # ---- the two pure-peer blocks: type HELD, AS cycling
    for _nm, _lo, _hi, _nas in (('BIG', 0x346, 0x365, 15), ('SMALL', 0x53D, 0x546, 8)):
        _blk = list(range(_lo, _hi + 1))
        check('%s pure-peer block: N2 low nibble is $3 on EVERY word, so the type '
              'field is HELD' % _nm,
              all((_n2N[_a] & 0xF) == 3 for _a in _blk),
              'nibbles %r' % sorted(set(_n2N[_a] & 0xF for _a in _blk)))
        check('...and mode = 1 on every word of the %s block' % _nm,
              all((((_n2N[_a] >> 3) & 1) << 2 | ((_n2N[_a] >> 2) & 1) << 1
                   | (_n2N[_a] & 1)) == 1 for _a in _blk))
        check('...while AS = N2[7:4] takes %d distinct values in %d words' % (_nas, len(_blk)),
              len(set((_n2N[_a] >> 4) & 0xF for _a in _blk)) == _nas,
              'n distinct = %d' % len(set((_n2N[_a] >> 4) & 0xF for _a in _blk)))

    # ---- ...but the hold is NOT distinctive.  Recompute the base rate and the runs.
    _n2lo = [_n2N[_a] & 0xF for _a in _n2v]
    _n2p3 = _n2lo.count(3) / float(len(_n2lo))
    _n2p1 = _n2lo.count(1) / float(len(_n2lo))
    check('the low nibble is TWO-VALUED-DOMINANT: $3 ~61% and $1 ~27%, 88% between '
          'them -- so long constant runs are its NORMAL behaviour',
          0.60 <= _n2p3 <= 0.62 and 0.26 <= _n2p1 <= 0.28
          and 0.87 <= _n2p3 + _n2p1 <= 0.89,
          '$3 %.1f%%  $1 %.1f%%' % (100 * _n2p3, 100 * _n2p1))

    # runs over the VALID SUBSEQUENCE, gaps ignored -- ONE definition, stated
    _n2r = []; _n2s = 0
    for _i in range(1, len(_n2lo) + 1):
        if _i == len(_n2lo) or _n2lo[_i] != _n2lo[_i - 1]:
            _n2r.append((_i - _n2s, _n2lo[_n2s], _n2v[_n2s], _n2v[_i - 1])); _n2s = _i
    _n2r.sort(key=lambda _x: -_x[0])
    check('the LONGEST constant-low-nibble run is 42 and it CONTAINS the BIG block',
          _n2r[0][0] == 42 and _n2r[0][2] <= 0x346 and _n2r[0][3] >= 0x365,
          'len %d at $%03X-$%03X' % (_n2r[0][0], _n2r[0][2], _n2r[0][3]))
    check('...but the SECOND longest is 41 and it is in the DECODE CORE, not a peer '
          'block -- so a long hold is not a peer-block signature',
          _n2r[1][0] == 41 and 0x1CE <= _n2r[1][2] <= 0x2FF,
          'len %d at $%03X-$%03X' % (_n2r[1][0], _n2r[1][2], _n2r[1][3]))
    check('...and there are at least SIX runs of 22 or more',
          sum(1 for _x in _n2r if _x[0] >= 22) >= 6,
          'n = %d' % sum(1 for _x in _n2r if _x[0] >= 22))
    _n2sm = [_x for _x in _n2r if _x[2] <= 0x53D <= _x[3]]
    check('the SMALL block sits inside a run of only 11, not a long one',
          _n2sm and _n2sm[0][0] == 11, 'len %d' % (_n2sm[0][0] if _n2sm else -1))

    # permutation: labels shuffled among valid positions
    def _n2lng(_sq):
        _b = _c = 1
        for _i in range(1, len(_sq)):
            _c = _c + 1 if _sq[_i] == _sq[_i - 1] else 1
            if _c > _b:
                _b = _c
        return _b
    _n2sh = list(_n2lo); random.seed(20260807)
    _n2ge10 = _n2ge42 = _n2max = 0
    for _ in range(2000):
        random.shuffle(_n2sh)
        _n2Lg = _n2lng(_n2sh)
        if _n2Lg >= 10:
            _n2ge10 += 1
        if _n2Lg >= 42:
            _n2ge42 += 1
        if _n2Lg > _n2max:
            _n2max = _n2Lg
    check('PERMUTATION: a shuffle produces a run of 10 or more ~97% of the time, so '
          'the SMALL block\'s hold is UNREMARKABLE',
          _n2ge10 / 2000.0 > 0.90, 'P = %.3f' % (_n2ge10 / 2000.0))
    check('...and a shuffle reaches ~35, so even a 32-word hold is INSIDE its range',
          _n2max >= 30, 'max shuffled run = %d' % _n2max)
    check('...while the observed 42 is beyond it',
          _n2ge42 == 0, '%d of 2000' % _n2ge42)
    check('the file records that the shuffle null is TOO WEAK for this field -- the '
          'store has TWO runs past its maximum',
          'too weak' in _n2z.lower() and '42 and 41' in _n2z)

    # ---- the conclusion that runs AGAINST my own hypothesis must be recorded
    check('the file states the hypothesis DEFLATES and the two blocks are NOT alike',
          'deflate' in _n2z.lower() and 'NOT alike' in _n2z)
    check('...and that this PARTIALLY RESTORES the record\'s "different constructs" claim',
          'PARTIALLY RESTORES' in _n2z.upper() and 'different constructs' in _n2z)
    check('...and that AS\'s 3.09x on n=8 is NOT claimed',
          '3.09x' in _n2z and 'not claimed' in _n2z.lower())

    # ---- N2 bit 1: regional, and NOT a port signal.  Both recomputed.
    _n2reg = {'DECISION': (0x200, 0x27F), 'DISPATCH': (0x280, 0x2FF),
              'MID': (0x1CE, 0x1FF), 'RECEPTION': (0x148, 0x1CD)}
    _n2rr = {}
    for _k, (_lo, _hi) in _n2reg.items():
        _g = [_a for _a in range(_lo, _hi + 1) if not (_n2P[_a] >> 7) & 1]
        _n2rr[_k] = sum((_n2N[_a] >> 1) & 1 for _a in _g) / float(len(_g))
    check('N2 bit 1 is 82-96% across ALL THREE parts of the decode core',
          all(0.82 <= _n2rr[_k] <= 0.96 for _k in ('MID', 'DECISION', 'DISPATCH')),
          ' '.join('%s %.0f%%' % (_k, 100 * _n2rr[_k])
                   for _k in ('MID', 'DECISION', 'DISPATCH')))
    check('...and only 33% in RECEPTION -- a 3x spread against a 66.9% baseline',
          _n2rr['RECEPTION'] < 0.36 and _n2rr['DECISION'] / _n2rr['RECEPTION'] > 2.5,
          'RECEPTION %.1f%%' % (100 * _n2rr['RECEPTION']))
    _n2dst = [_a for _a in _n2v if ((_n2L[_a] >> 5) & 7) != 7]
    _n2dr = sum((_n2N[_a] >> 1) & 1 for _a in _n2dst) / float(len(_n2dst))
    check('...but FLAT against destination-selector activity -- within half a point '
          'of baseline, so it is NOT a data-path signal',
          abs(_n2dr - _n2b1) < 0.01, 'dst-active %.1f%% vs %.1f%%' % (100 * _n2dr, 100 * _n2b1))
    check('the file records bit 1 as splitting the MODE field\'s dominant value, '
          'which the record\'s decomposition does not explain',
          'splits the mode' in _n2z.lower() and 'unattributed single bit' in _n2z)
    check('...and distinguishes its shape from the PHASE field\'s',
          'not the phase' in _n2z.lower() and 'binary' in _n2z)

    # ---- the NEGATIVE about AG_INSTR
    check('bit 1 is REFUTED as the Am29540 Count, on the ground that it peaks in the '
          'region that provably receives nothing',
          'backwards' in _n2z and 'no external input' in _n2z)
    check('...and bits {1,0} do not read as the 2-bit instruction under EITHER polarity',
          'Hold' in _n2t and 'Reset-Load' in _n2t and 'polarity' in _n2z)
    check('...so xp32_sim\'s AG_INSTR stays a MODEL CHOICE',
          'AG_INSTR' in _n2t and 'MODEL CHOICE' in _n2z.upper())
    _n2xs = open('tools/xp32_sim.py').read()
    check('...and xp32_sim still labels it that way in its own source',
          'AG_INSTR' in _n2xs and 'MODEL CHOICE' in _n2xs.upper())

    # ---- the method note
    check('the two-definitions-of-run error is recorded, with both numbers',
          'two ways' in _n2z.lower() and '32' in _n2z and '42' in _n2z
          and 'State the definition before comparing' in _n2z)
    check('...and counted as the ELEVENTH base-rate artefact, fourth of the session '
          'caught before publication',
          'Eleventh base-rate artefact' in _n2z or 'eleventh base-rate artefact' in _n2z.lower())


_EU_PEER_TYPE_FIELD_AND_N2_BIT1_2026_08_07()


def _APIF_SHEET2_HST_RESOLVED_2026_08_07():
    """AP I/F sheet 2 -- the HST driver tension resolved, and the IO bus.
    refs_extracted/apif_sheet2_hst_resolved.md

    The 8 IO pins and the DPMBS pins are RE-VERIFIED against
    apif_4448_connection_list.md here rather than restated, and every
    device pinout is re-derived from the standard part pairings."""
    import os
    _s2p = 'refs_extracted/apif_sheet2_hst_resolved.md'
    _s2c = 'refs_extracted/apif_4448_connection_list.md'
    if not os.path.isfile(_s2p) or not os.path.isfile(_s2c):
        return
    _s2t = open(_s2p).read()
    _s2z = ' '.join(_s2t.replace('*', '').replace('`', '').replace('~', '')
                        .replace('\n> ', '\n').replace('\n>', '\n').split())
    _s2L = open(_s2c).read()

    # ---- the sheet identifies itself, and page N = sheet N holds for a sixth sheet
    check('sheet 2 is HSTXX, HDXX / DP, IO, RGBS, drawing 512-3448-010 rev 01',
          'HSTXX, HDXX / DP, IO, RGBS' in _s2t and '512-3448-010' in _s2t)
    check('...and the 1:1 page-to-sheet mapping is recorded as holding for a SIXTH sheet',
          'Page 2 =' in _s2z or 'page 2 = sheet 2' in _s2z.lower())

    # ---- THE RESOLUTION: all 16 HST bits are MC3487-driven
    check('THE RESOLUTION: G11 and G10 MC3487 drive HST00-HST07 from IFOUT00-IFOUT07',
          'G11' in _s2t and 'G10' in _s2t and 'IFOUT00' in _s2t
          and 'HST00' in _s2t and 'MC3487' in _s2t)
    check('...so with sheet 3\'s G23/G24 all SIXTEEN bits are MC3487-driven: '
          '4 devices x 4 channels = 16 channels for 16 bits',
          'G23' in _s2t and 'G24' in _s2t and 'HST08' in _s2t
          and '16 channels for 16 bits' in _s2z)
    check('...and the bus is therefore NOT driver-asymmetric by half',
          'NOT driver-asymmetric' in _s2z)
    check('...and the outputs are used SINGLE-ENDED, one per channel, complement unused',
          'single-ended' in _s2z and 'complement unused' in _s2z.replace('the complement', 'complement'))

    # ---- sheet 1's H10 RECEIVES -- the half that makes it "neither branch"
    check('sheet 1\'s H10 74LS244 has its INPUTS on the HST connector net and its outputs on '
          'IFIBS00-IFIBS07, so it RECEIVES',
          'H10' in _s2t and 'IFIBS00' in _s2t and 'RECEIVES' in _s2z)
    check('...so the recorded fork resolves as NEITHER branch -- not a series stage and not a '
          'per-half difference, but the OPPOSITE DIRECTION IN PARALLEL',
          'neither' in _s2z.lower() and 'opposite direction in parallel' in _s2z.lower())
    check('...and the DIAGNOSIS is recorded: two DIRECTIONS mistaken for two HALVES, because '
          'sheet 1 shows only the receiver and sheet 3 only a driver',
          'DIRECTIONS mistaken for two HALVES' in _s2t)
    check('...which also explains sheet 1\'s own HD-transceiver / HST-buffer asymmetry note',
          '74LS245' in _s2t and 'plain TTL' in _s2z)

    # ---- the MC3487 count, a SECOND correction to the same claim in two days
    check('the MC3487 count on the drawing is at least SIX: G6/H16 (4) + G23/G24 (3) + G11/G10 (2)',
          'at least SIX' in _s2t or 'AT LEAST SIX' in _s2t)
    check('...against TWO in the photograph, which declares itself a LOWER BOUND in its own text',
          'lower bound' in _s2z)
    check('...and the host-link consequence is stated: 24 outbound channels, of which the 16 on '
          'HST are single-ended, so the raw driver census OVER-COUNTS differential capability',
          '24 outbound channels' in _s2z and 'over-counts' in _s2z.lower())
    _hs = open('refs_extracted/apif_handshake_interrupt.md').read()
    _hsz = ' '.join(_hs.replace('*', '').replace('`', '').split())
    check('...and the host document is CORRECTED IN PLACE from ">= four" to ">= SIX", not just here',
          'at least SIX' in _hsz and 'CORRECTED 2026-08-07' in _hsz)

    # ---- the IO bus: RE-VERIFIED against the connection list, 8 for 8
    _io = {'A52': 'IO24', 'A54': 'IO25', 'A56': 'IO26', 'A58': 'IO27',
           'A82': 'IO28', 'A84': 'IO29', 'A86': 'IO30', 'A88': 'IO31'}
    _ok = 0
    for _pin, _sig in _io.items():
        import re as _re
        if _re.search(r'\|\s*%s\s*\|\s*%s\*' % (_pin, _sig), _s2L):
            _ok += 1
    check('RE-VERIFIED: all EIGHT IO2x* pins A-52/54/56/58/82/84/86/88 match the independently '
          'transcribed connection list, name and pin',
          _ok == 8, '%d of 8' % _ok)
    check('...and the document records the G7 74LS240 path: IFOBS00-07 -> inverting buffer '
          'gated by REG2IO* -> IO24*-IO31*',
          'G7' in _s2t and 'IFOBS00' in _s2t and 'REG2IO' in _s2t and 'IO24' in _s2t)
    check('...bringing the total to 68 pin agreements across SIX sheets',
          '68 independent pin agreements across six sheets' in _s2z)
    check('...and the IO bus is recorded as WIDER than these eight, the list carrying '
          'IO32*/IO33*/IO34* at A-7/A-8/A-9',
          'IO32' in _s2t and 'IO34' in _s2t)
    import re as _re2
    check('...which is itself re-verified: IO32*/IO33*/IO34* really are at A7/A8/A9 in the list',
          all(_re2.search(r'\|\s*A%d\s*\|\s*IO%d\*' % (_s2pn, _s2sg), _s2L)
              for _s2pn, _s2sg in ((7, 32), (8, 33), (9, 34))))

    # ---- $FF0004 is a NARROWING, not a resolution -- the discipline that matters
    check('the $FF0004 consequence is stated as a NARROWING and NOT a resolution',
          'NARROWING' in _s2t and 'not a resolution' in _s2z)
    check('...on two grounds: an SBC-side path exists and is NOT on this sheet, and IFOBS is a '
          'shared bus with at least three driver sets',
          'not on this sheet' in _s2z and 'three driver sets' in _s2z)
    check('...with the inverted-polarity point offered as a CHECK rather than a conclusion',
          'inverted' in _s2z and ('offered as a check' in _s2z.lower()
                                  or 'as a check rather than' in _s2z.lower()))
    check('...and the eleven-site figure is used, not the retracted "both"',
          '11 sites, 11 of 11' in _s2z or '11 of 11' in _s2z)
    _cr = open('refs_extracted/apif_control_reg_and_register_map.md').read()
    check('...and that host document is corrected in place from "Both" to ELEVEN',
          'ELEVEN' in _cr and '11 of 11' in _cr)

    # ---- FOUR confusable buses, and IFIBS retro-justifies the IFDB correction
    check('all FOUR similarly-named buses are tabulated: IFOBS, IFIBS, IFOUT, RGBS',
          all(_s2b in _s2t for _s2b in ('IFOBS', 'IFIBS', 'IFOUT', 'RGBS')))
    check('...IFIBS/IFOBS identified as a symmetric IN/OUT pair, which RETRO-JUSTIFIES the '
          'IFDB->IFOBS correction (IFOBS\'s partner is IFIBS, not IFDB)',
          'symmetric in/out pair' in _s2z.lower() and 'IFDB' in _s2t)
    check('...and IFOUT recorded as a genuinely THIRD name, read at 4x',
          'third name' in _s2z.lower() and 'unmistakable' in _s2z)

    # ---- the balloon convention
    check('the BLANK two-part balloon is identified as marking a MULTI-SHEET bus',
          'BLANK' in _s2t and 'multi-sheet bus' in _s2z.lower())
    check('...with the reason: HD and HST span sheets 1, 2 AND 3, so one sheet number would be wrong',
          'sheets 1, 2' in _s2z and 'would be wrong' in _s2z)

    # ---- the pinouts are SELF-CHECKING, and the bit labels are load-bearing
    _p244 = {2: 18, 4: 16, 6: 14, 8: 12, 11: 9, 13: 7, 15: 5, 17: 3}
    check('CONTROL: the 74LS244/240 input->output pairing used throughout closes on all 8 bits',
          len(_p244) == 8 and sorted(_p244) == [2, 4, 6, 8, 11, 13, 15, 17]
          and sorted(_p244.values()) == [3, 5, 7, 9, 12, 14, 16, 18])
    for _dev, _ins, _outs in (
            ('G9',  (8, 6, 4, 2, 17, 11, 13, 15), (12, 14, 16, 18, 3, 9, 7, 5)),
            ('H12', (2, 6, 4, 8, 13, 17, 15, 11), (18, 14, 16, 12, 7, 3, 5, 9)),
            ('H10', (2, 4, 8, 6, 11, 13, 15, 17), (18, 16, 12, 14, 9, 7, 5, 3))):
        check('%s\'s recorded per-bit pin assignment CLOSES against the standard 244 pairing on '
              'all 8 bits -- so the drawing\'s bit labels are self-checking' % _dev,
              all(_p244[_s2i] == _s2o for _s2i, _s2o in zip(_ins, _outs)),
              '%r vs %r' % (_ins, _outs))
    check('...and the assignments are NON-MONOTONIC and DIFFER per package, so a reader assuming '
          'monotonic pin order gets three of the four octal buffers wrong',
          'NON-MONOTONIC' in _s2t and 'three of the four octal buffers wrong' in _s2z)
    check('G8 is a 74S240 (Schottky), NOT an LS part',
          '74S240' in _s2t and 'Schottky' in _s2t)
    check('H7 is the sheet\'s only bidirectional device, DIR on pin 1 and E on pin 19',
          '74LS245' in _s2t and 'DIR' in _s2t and 'pin 1' in _s2z and 'pin 19' in _s2z)
    check('G11/G10 reproduce sheet 3\'s MC3487 reading exactly -- inputs 15 9 7 1 = D C B A, '
          'enables 4 and 12 -- and share the enable net via a junction dot',
          '15 9 7 1' in _s2z and 'junction dot' in _s2z)

    # ---- control inputs with source sheets, and APIF2HST re-confirmed
    for _sig in ('FIFOOUT', 'XCVREN', 'DPMBS2IO', 'REG2IO', 'APIF2HST', 'DMA2AP', 'OUT'):
        check('control input %s is tabulated with its source sheet' % _sig, _sig in _s2t)
    check('APIF2HST is re-confirmed here, so yesterday\'s AP2IF2HST correction holds',
          'APIF2HST' in _s2t and 'not' in _s2z and 'AP2IF2HST' in _s2t)
    check('...and DMA2AP* arriving from sheet 6 is an EIGHTH balloon-to-title agreement for the '
          'sheet index',
          'DMA2AP' in _s2t and ('eighth' in _s2z.lower() or 'agreement for the sheet index' in _s2z))

    # ---- HD: at least two drivers, and what is NOT claimed
    check('HD00-HD07 is recorded as having at least TWO drivers: sheet 1\'s 245 and H12\'s 244',
          'H12' in _s2t and 'at least two drivers' in _s2z.lower())
    check('...and G9\'s net is explicitly NOT traced and NOT claimed',
          'was not traced' in _s2z and 'not claimed' in _s2z)

    # ---- the method note: a FIFTH overview misreading
    check('the FIFTH overview misreading of the session is recorded -- the DPMBS pin group\'s '
          'second nibble',
          'FIFTH' in _s2t and 'DPMBS' in _s2t)
    check('...and those pins are explicitly NOT PUBLISHED',
          'not published' in _s2z)
