def _NATIVE_RESOLUTION_AND_WEITEK_RULES():
    """The AP I/F schematic is a 582 ppi scan, and the Weitek sequencing rules
    make a falsifier for the AU microword layout.

    Every assertion here either RUNS the checker or RE-MEASURES the PDF.  None
    restates a number from the write-up.
    """
    import subprocess

    _nrd = 'refs_extracted/schematic_native_resolution.md'
    _wkd = 'refs_extracted/weitek_rule_checker.md'
    _wkt = 'tools/weitek_rules.py'
    check('the native-resolution write-up exists', os.path.exists(_nrd), _nrd)
    check('the Weitek rule-checker write-up exists', os.path.exists(_wkd), _wkd)
    check('tools/weitek_rules.py exists', os.path.exists(_wkt), _wkt)
    if not (os.path.exists(_nrd) and os.path.exists(_wkd)
            and os.path.exists(_wkt)):
        return

    # ==================================================================
    # 1. THE PDF's NATIVE RESOLUTION, re-measured with pdfimages
    # ==================================================================
    _nrp = 'refs/FPS-3000/schematics/GE_RDCP_APIF.pdf'
    _nrhave = os.path.exists(_nrp)
    check('the AP I/F schematic PDF is present', _nrhave, _nrp)

    _nrppi, _nrstrips, _nrsum = None, 0, 0
    if _nrhave:
        try:
            _nro = subprocess.run(['pdfimages', '-list', _nrp],
                                  capture_output=True, text=True,
                                  timeout=120).stdout
        except Exception:
            _nro = ''
        for _nrl in _nro.splitlines()[2:]:
            _nrf = _nrl.split()
            if len(_nrf) >= 14 and _nrf[0] == '1':
                _nrstrips += 1
                _nrsum += int(_nrf[4])
                if _nrppi is None:
                    _nrppi = int(_nrf[12])

    check('pdfimages parsed the schematic, so the native resolution can be '
          're-measured rather than restated', _nrppi is not None,
          'ppi = %s' % _nrppi)
    if _nrppi is not None:
        check('RE-MEASURED: the AP I/F schematic is a 582 ppi scan',
              _nrppi == 582, 'pdfimages reports %d ppi' % _nrppi)
        check('...and page 1 is stored as FOUR horizontal strips, not one '
              'image -- which is why a naive extraction yields four '
              'unrelated files', _nrstrips == 4, '%d strips' % _nrstrips)
        check('...whose heights sum to the 6803-row page the write-up '
              'stitches', _nrsum == 6803, 'sum = %d rows' % _nrsum)
        # the discard figures are DERIVED, not quoted
        check('...so the 300 dpi pipeline discarded more than 40 per cent of '
              'the LINEAR detail', 1.0 - 300.0 / _nrppi > 0.40,
              'linear discard = %.1f%%' % (100 * (1 - 300.0 / _nrppi)))
        check('...and more than 70 per cent of the AREA detail',
              1.0 - (300.0 / _nrppi) ** 2 > 0.70,
              'area discard = %.1f%%'
              % (100 * (1 - (300.0 / _nrppi) ** 2)))
        # the ranked request was for "400-600 dpi"; 582 is inside that band
        check('...and 582 ppi ALREADY SATISFIES the ranked request for a '
              '"400-600 dpi re-render", from the file in hand',
              400 <= _nrppi <= 600, '%d ppi' % _nrppi)

    _nrs = open(_nrd, encoding='utf-8', errors='replace').read()

    def _nrn(_nrx):
        return (_nrx.replace('*', '').replace('`', '').replace('~', '')
                .replace('>', '').replace('\n', ' '))
    _nrt = ' '.join(_nrn(_nrs).split())

    # the TWO TRAPS must both be named -- the rotation one is the trap that
    # makes a correct extraction look like a failed one
    check('the write-up names the ROTATION trap: pdfimages needs 180 where '
          'the documented pdftoppm pipeline uses 270',
          'rotate(180)' in _nrt and '270' in _nrt, '')
    check('...and gives the REASON -- pdftoppm applies the page rotation and '
          'pdfimages does not',
          'pdftoppm already applies' in _nrt or
          'pdfimages does not' in _nrt, '')
    check('...and the strip-ordering trap', 'stacked in file order' in _nrt
          or 'stack first' in _nrt.lower(), '')

    # ==================================================================
    # 2. THE OTHER PDFs -- the sweep is re-run, not restated
    # ==================================================================
    _nrsweep = {}
    for _nrq in ('refs/Weitek/WTL-1232_1233_Jul86.pdf',
                 'refs/datasheets/M68KVM02.pdf',
                 'refs/AMD/29116_dataSheet_Mar86.pdf',
                 'refs/AMD/29C116_dataSheet_Mar88.pdf'):
        if not os.path.exists(_nrq):
            continue
        try:
            _nro = subprocess.run(['pdfimages', '-list', _nrq],
                                  capture_output=True, text=True,
                                  timeout=120).stdout
        except Exception:
            continue
        for _nrl in _nro.splitlines()[2:]:
            _nrf = _nrl.split()
            if len(_nrf) >= 14:
                _nrsweep[_nrq] = int(_nrf[12])
                break

    if len(_nrsweep) >= 3:
        _nr29 = _nrsweep.get('refs/AMD/29116_dataSheet_Mar86.pdf')
        _nr29c = _nrsweep.get('refs/AMD/29C116_dataSheet_Mar88.pdf')
        if _nr29 and _nr29c:
            check('RE-MEASURED: the CMOS Am29C116 sheet is a HIGHER-resolution '
                  'scan than the bipolar Am29116 -- and this project records '
                  'the two as the same ISA, so any hard-to-read Am29116 table '
                  'should be re-read from the CMOS one',
                  _nr29c > _nr29, '29C116 %d ppi vs 29116 %d ppi'
                  % (_nr29c, _nr29))
        _nrhi = [_nrq for _nrq, _nrv in _nrsweep.items() if _nrv > 300]
        check('...and every PDF in the sweep is above the 300 dpi the '
              'pipeline used', len(_nrhi) == len(_nrsweep),
              '%d of %d above 300' % (len(_nrhi), len(_nrsweep)))

    # ==================================================================
    # 3. THE IFOBS DISCREPANCY IS RESOLVED, and the argument is the STROBE SET
    # ==================================================================
    _nrib = 'refs_extracted/apif_ifobs_bit_order.md'
    if os.path.exists(_nrib):
        _nribt = ' '.join(_nrn(open(_nrib, encoding='utf-8',
                                    errors='replace').read()).split())
        check('the flagged IFOBS sheet-number discrepancy is marked RESOLVED, '
              'not still flagged',
              'RESOLVED' in _nribt and 'FOUR numbers' in _nribt, '')
        check('...and BOTH earlier readings are withdrawn as CLIPPED, rather '
              'than one being picked',
              'Neither was right' in _nribt and 'clipped' in _nribt, '')
        check('...and the first entry 14 is claimed from the READ-STROBE SET, '
              'explicitly NOT from the image',
              'not from the image' in _nribt
              and 'RDFIFO' in _nribt, '')
        # the strobe argument must name all four sheets and the self-exclusion
        for _nrsh in ('14', '15', '16', '17'):
            check('...the strobe table names sheet %s' % _nrsh,
                  ('| ' + _nrsh + ' ' in _nribt) or
                  (' ' + _nrsh + ' |' in _nribt) or
                  ('sheets 14-17' in _nribt), '')
        check('...and sheet 3 is excluded because APIDENT* is on THIS sheet '
              '-- the step that makes four entries rather than five',
              'APIDENT' in _nribt and
              ('cross-reference to itself' in _nribt), '')
        check('...the ordering argument is still stated to be unaffected',
              'unaffected' in _nribt, '')
        # the residual was RESOLVED 2026-08-11 by reading the balloon at native
        # resolution: FOUR entries, 3/15/16/17, and sheet 14 absent.  The file
        # itself had named two alternatives; the measurement picks the first.
        check('...and the residual is RESOLVED, not left open',
              'Still open' not in _nribt and 'RESOLVED 2026-08-11' in _nribt,
              'the balloon was read at 582 ppi, rotated upright')
        check('...the balloon carries FOUR entries -- 3, 15, 16, 17 -- not five',
              'FOUR' in _nribt and '3, 15, 16, 17' in _nribt, '')
        check('...so the convention is DRIVERS ONLY, the first of the two '
              'alternatives the file named, and sheet 14 is absent',
              'drivers only' in _nribt and
              ('14 absent' in _nribt or 'sheet 14 absent' in _nribt.lower()), '')

    # ==================================================================
    # 4. THE AU MODEL CLOCKS ITS FP UNITS ZERO TIMES -- re-measured
    # ==================================================================
    import importlib.util

    def _wkload(_wkn, _wkp):
        _wks = importlib.util.spec_from_file_location(_wkn, _wkp)
        _wkm = importlib.util.module_from_spec(_wks)
        sys.modules[_wkn] = _wkm
        _wks.loader.exec_module(_wkm)
        return _wkm

    _wkok = all(os.path.exists(_wkp) for _wkp in
                ('tools/eu_sim.py', 'tools/au_sim.py', 'tools/xp32_sim.py'))
    check('all three simulators are present so the AU clock census can be '
          're-measured', _wkok, '')
    if _wkok:
        _wkload('eu_sim', 'tools/eu_sim.py')
        _wkau = _wkload('au_sim', 'tools/au_sim.py')
        _wkxp = _wkload('xp32_sim', 'tools/xp32_sim.py')

        _wkcnt = {'w': 0, 'g': 0}
        _wkw0 = _wkau.Weitek.clock
        _wkg0 = _wkau.Am29540.clock

        def _wkw1(self, *a, **k):
            _wkcnt['w'] += 1
            return _wkw0(self, *a, **k)

        def _wkg1(self, *a, **k):
            _wkcnt['g'] += 1
            return _wkg0(self, *a, **k)

        _wkau.Weitek.clock = _wkw1
        _wkau.Am29540.clock = _wkg1
        try:
            _wkxp.run(2048)
        finally:
            _wkau.Weitek.clock = _wkw0
            _wkau.Am29540.clock = _wkg0

        check('RE-MEASURED: the joined EU-AU walk clocks the Am29540 address '
              'generator over a thousand times', _wkcnt['g'] > 1000,
              'ag clocks = %d' % _wkcnt['g'])
        check('RE-MEASURED: and it clocks the three Weitek FP units ZERO '
              'times -- the joined model is an ADDRESS-GENERATION model, and '
              'the arithmetic side of the AU has never been exercised',
              _wkcnt['w'] == 0, 'Weitek clocks = %d' % _wkcnt['w'])
        check('...which is STRUCTURAL: the FP units are reachable only through '
              'AU.step(w), and w never arrives because the AU WCS is '
              'host-loaded', hasattr(_wkau.AU, 'step')
              or 'def step' in open('tools/au_sim.py').read(), '')

        # ==============================================================
        # 5. THE RULE CHECKER -- every assertion RUNS it
        # ==============================================================
        _wkr = _wkload('weitek_rules', _wkt)
        check('weitek_rules selftest passes', _wkr._selftest(), '')

        # the MODE composition is the datasheet's own field order
        check('the 1232 MODE composes as {F3 F2 F1 F0, U0} -- five bits',
              _wkr.compose_mode(0b1010, 0b01, '1232') == 0b10101,
              bin(_wkr.compose_mode(0b1010, 0b01, '1232')))
        check('...and the 1032 keeps au_sim s SIX-bit form, which is what this '
              'board (-002 REV F) needs',
              _wkr.compose_mode(0b1010, 0b11, '1032') == 0b101011,
              bin(_wkr.compose_mode(0b1010, 0b11, '1032')))
        check('...and the 1032 layout is declared UNDOCUMENTED rather than '
              'borrowing the 1232 positions',
              _wkr.MODE_LAYOUTS['1032'] is None, '')

        _wkc = _wkr.WeitekRuleChecker('alu', part='1032')
        _wkc.tick(f=0, l=_wkr.LOAD_LMODE, u=0)
        check('...so on a 1032 is_flowthrough() returns None, and rules 5 and '
              '7 are reported UNVERIFIABLE instead of passing silently',
              _wkc.is_flowthrough() is None and _wkc.rounding() is None, '')

        # M0 is U0, NOT F0 -- the slip the selftests caught
        _wka = _wkr.WeitekRuleChecker('mul', part='1232')
        _wka.tick(f=0b0001, l=_wkr.LOAD_LMODE, u=0)
        _wkb = _wkr.WeitekRuleChecker('mul', part='1232')
        _wkb.tick(f=0b0000, l=_wkr.LOAD_LMODE, u=0b1)
        check('M0 is U0 and NOT F0: the same F with U0 set/clear gives '
              'OPPOSITE pipeline modes, so a model composing MODE from F alone '
              'gets FLOW vs PIPE inverted',
              _wka.is_flowthrough() is True
              and _wkb.is_flowthrough() is False,
              'f=1,u=0 -> flow=%s ; f=0,u=1 -> flow=%s'
              % (_wka.is_flowthrough(), _wkb.is_flowthrough()))

        # RULE 6's discriminating power, RECOMPUTED over all 16 F values
        _wkbad = 0
        for _wkf in range(16):
            _wkc = _wkr.WeitekRuleChecker('mul', part='1232')
            _wkc.tick(f=0, l=_wkr.LOAD_LMODE, u=0b1)
            if any(_wkv[1] == 6 for _wkv in
                   _wkc.tick(f=_wkf, l=_wkr.LOAD_LAB)):
                _wkbad += 1
        check('RECOMPUTED: rule 6 rejects 12 of the 16 possible F values on a '
              'multiplier load, so it kills a wrong MUL_F position ~75% of the '
              'time on ONE cycle -- the most falsifiable field in the AU word',
              _wkbad == 12, '%d of 16 rejected' % _wkbad)
        # and it is multiplier-only
        _wkbad2 = 0
        for _wkf in range(16):
            _wkc = _wkr.WeitekRuleChecker('alu', part='1232')
            _wkc.tick(f=0, l=_wkr.LOAD_LMODE, u=0b1)
            if any(_wkv[1] == 6 for _wkv in
                   _wkc.tick(f=_wkf, l=_wkr.LOAD_LAB)):
                _wkbad2 += 1
        check('...and rule 6 is multiplier-only -- the ALU s F=0b0100 is the '
              'legal A+B, so it must reject NONE', _wkbad2 == 0,
              '%d ALU rejections' % _wkbad2)

        # THE CALIBRATION, recomputed
        import random as _wkrnd
        _wkrnd.seed(11)

        def _wkscore(_wkk, _wkn=4000):
            _wkq = _wkr.WeitekRuleChecker(_wkk, part='1232')
            for _wki in range(_wkn):
                _wkq.tick(f=_wkrnd.getrandbits(4), l=_wkrnd.getrandbits(2),
                          u=_wkrnd.getrandbits(2),
                          unload=bool(_wkrnd.getrandbits(1)))
            return _wkq

        _wkm = _wkscore('mul')
        _wkl = _wkscore('alu')
        _wkg = _wkr.WeitekRuleChecker('mul', part='1232')
        _wkg.tick(f=0, l=_wkr.LOAD_LMODE, u=1)
        for _wki in range(50):
            _wkg.tick(f=0, l=_wkr.LOAD_LAB)
            _wkg.tick(f=0, l=_wkr.LOAD_LAB)
            _wkg.tick(u=_wkr.UNLOAD_UMS, unload=True)
            _wkg.tick(u=_wkr.UNLOAD_ULS, unload=True)

        check('RECOMPUTED: a random multiplier control stream scores above 0.8 '
              'violations per cycle', _wkm.rate() > 0.8,
              'rate = %.3f' % _wkm.rate())
        check('RECOMPUTED: a random ALU stream scores above 0.5',
              _wkl.rate() > 0.5, 'rate = %.3f' % _wkl.rate())
        check('RECOMPUTED: and a hand-written LEGAL PIPE kernel scores EXACTLY '
              'zero -- so a candidate AU field layout can be scored across '
              'the whole interval', _wkg.rate() == 0.0 and _wkg.ops == 50,
              'rate = %.3f over %d ops' % (_wkg.rate(), _wkg.ops))
        check('...the separation is near-total, which is what makes it a '
              'FALSIFIER rather than a diagnostic',
              _wkm.rate() - _wkg.rate() > 0.8,
              'gap = %.3f' % (_wkm.rate() - _wkg.rate()))
        check('...and several distinct rules contribute, so the score is not '
              'one rule in disguise', len(_wkm.by_rule()) >= 3,
              str(_wkm.by_rule()))
        check('...with by_rule() accounting for every violation',
              sum(_wkm.by_rule().values()) == len(_wkm.violations), '')

        # the five checkable rules must ALL be reachable
        _wkseen = set(_wkm.by_rule()) | set(_wkl.by_rule())
        check('at least four of the five checkable rules actually fire on the '
              'random streams, so none is dead code',
              len(_wkseen & {1, 3, 5, 6, 7, 8}) >= 4, str(sorted(_wkseen)))

    # ==================================================================
    # 6. The write-up must keep its own limits
    # ==================================================================
    _wkt2 = ' '.join(_nrn(open(_wkd, encoding='utf-8',
                               errors='replace').read()).split())
    check('the Weitek write-up states it does NOT model the arithmetic',
          'does not model the arithmetic' in _wkt2, '')
    check('...and that it has NEVER been run against real AU microcode, '
          'because none exists',
          'never been run against real AU microcode' in _wkt2, '')
    check('...and that integration into au_sim is DEFERRED because that file '
          'is a live suite dependency',
          'deferred' in _wkt2.lower() and 'live suite dependency' in _wkt2, '')
    check('...and it records that the selftests caught the author s OWN '
          'misreading of the field order',
          'MY OWN misreading' in _wkt2 or 'my tests' in _wkt2, '')


_NATIVE_RESOLUTION_AND_WEITEK_RULES()


