    # ---- 7. the external artefacts, guarded on existence ----------
    _cmb = _cmos.path.expanduser(
        '~/src/claude/ap120/github/github_repo/FPS 100/Schematics/')
    _cmpdf = _cmb + 'GE Schematics/GE_RDCP_wo_764_schematic_1of2_1983.pdf'
    if _cmos.path.exists(_cmpdf):
        import subprocess as _cmsp
        _cmr = _cmsp.run(['pdfinfo', _cmpdf], capture_output=True, text=True)
